select public.import_assessments($json$ {"course_slug":"english-b1-b2","checkpoints":[{"module":4,"code":"b1_consolidation","title":"Checkpoint 1 · B1 Consolidation","timing":"End of Week 4","description":"Course checkpoint (not a CEFR placement or certification test): check control across Weeks 1–4 grammar (16 items), a 45–60s spoken narrative about a change, and a short written visitor note.","minutes":30,"skills":["grammar","speaking","writing"],"tasks":["16-item diagnostic across Weeks 1–4 (4 per week: past vs present perfect, future meanings, house-rule modals, present/past passives)","45–60s spoken narrative in response to a new prompt about a change (kept separate from quiz scoring)","Short written visitor note (100–140 words) separating a place fact from personal experience"]},{"module":8,"code":"mid_course_review","title":"Checkpoint 2 · Mid-Course Review","timing":"End of Week 8","description":"Verify B1+ to B2-entry control of deduction, reported speech, gerunds/infinitives, and third/mixed conditionals in a 2-minute talk and 150–180 word response.","minutes":35,"skills":["grammar","listening","speaking","writing"],"tasks":["12-item grammar check on deduction, reporting verbs, gerunds/infinitives, and conditionals","2-minute recorded response weighing technology, work, media, or environmental choices","150–180 word structured opinion or report with clear paragraphing"]},{"module":12,"code":"b2_readiness","title":"Checkpoint 3 · B2 Readiness","timing":"End of Week 12","description":"Demonstrate B2 readiness through structured 3-minute speaking, a 180–200 word argument, and comprehension of 3-minute listening and 250–350 word reading.","minutes":40,"skills":["reading","listening","speaking","writing"],"tasks":["3-minute structured speaking task using causatives, articles/quantifiers, participle clauses, or emphasis","180–200 word analytical argument balancing competing viewpoints","Timed listening (3 min) and reading (250–350 words) comprehension verification"]},{"module":16,"code":"final_b2_assessment","title":"Checkpoint 4 · Final B2 Assessment","timing":"End of Week 16","description":"Full B2 readiness review: 10–15 min live teacher discussion, recorded position statement (up to 3 min), 200–220 word essay/proposal, personal error-log mastery check, and teacher readiness decision (Ready to start B2 exam preparation vs. named next step).","minutes":45,"skills":["grammar","vocabulary","listening","reading","speaking","writing"],"tasks":["10–15 min live teacher discussion plus recorded B2 position statement (up to 3 minutes) defending and qualifying a complex view","200–220 word formal argument or proposal using hedging, concession, and formal register","Full personal error-log consolidation check & teacher confirmation (Ready to start B2 exam preparation or named next step)"]}],"badges":[{"code":"first_step","title":"Week 1 Output","description":"Completed your first required output session in the 16-week pathway.","icon":"🌱","xp":30,"criteria":{"lessons_completed":1}},{"code":"streak_7","title":"Full 7-Day Rhythm","description":"Maintained a 7-day output-backed study streak.","icon":"🔥","xp":60,"criteria":{"streak_days":7}},{"code":"words_50","title":"50 Active Words","description":"Learned and reviewed 50 B1→B2 core vocabulary items.","icon":"🗂️","xp":75,"criteria":{"vocab_cards":50}},{"code":"words_130","title":"Core Lexicon Builder","description":"Reviewed over 130 core B1→B2 vocabulary items across the 16 weeks.","icon":"📚","xp":150,"criteria":{"vocab_cards":130}},{"code":"voice_builder","title":"Voice Builder","description":"Submitted 8 Friday speaking recordings with self-check.","icon":"🎙️","xp":100,"criteria":{"speaking_attempts":8}},{"code":"clear_writer","title":"Clear Writer","description":"Completed 8 Saturday writing tasks with revision.","icon":"✍️","xp":100,"criteria":{"writing_submissions":8}},{"code":"b2_ready","title":"16-Week Finisher","description":"Completed Checkpoint 4 at the end of Week 16.","