-- 3. Weeks, daily sessions, blocks, practice items, inputs, tasks -------
select public.import_modules($json$ {"course_slug":"english-b1-b2","modules":[{"number":1,"phase":"Month 1: Strengthen B1 foundations","title":"Personal experiences and change","summary":"Tell a story and connect a past change to now with the past simple, present perfect, and used to vs got used to.","hours":4,"releaseStage":"live","vocabularyTopic":"Personal experiences, life changes & adaptation","lightGrammar":"Past continuous background & explicit past perfect (optional B2 stretch)","grammar":[{"key":"past-simple-present-perfect-used-to","role":"main","name":"Past simple vs present perfect; used to vs got used to","explanation":"Use the past simple for a finished event (\"I moved last year\") and the present perfect for a change up to now (\"Since then, I’ve made a few friends\"). Use the past continuous as story background, and contrast used to work (a former habit or state) with got used to working (became accustomed to something new).","keyPoints":["Finished past event at a finished time: \"I moved here last year.\"","Change continuing or connected to now: \"Since then, I’ve made a few friends.\"","Story background action: \"I was walking home when I bumped into a neighbour.\"","Contrast \"used to + base verb\" (old habit/state) with \"got used to + noun / -ing\" (became accustomed to it)."],"example":"When I moved to a new city last year, I didn’t know anyone. It took me a few weeks to get used to spending my evenings alone, and since then I’ve made a few friends.","items":[{"prompt":"I ___ here last year. Since then, I’ve made a few friends.","options":["moved","have moved"],"answer":"moved","explanation":"“Last year” names a finished past time, so use the past simple (“moved”).","difficulty":1},{"prompt":"Since I joined the running club in April, I ___ much more at home in the city.","options":["felt","have felt","was feeling"],"answer":"have felt","explanation":"“Since I joined...” connects a past starting point to the present, so use the present perfect (“have felt”).","difficulty":1},{"prompt":"Two years ago, Maya ___ her office job and retrained as a pastry chef.","options":["left","has left","has been leaving"],"answer":"left","explanation":"“Two years ago” marks a finished event in the past, so use the past simple (“left”).","difficulty":1},{"prompt":"I ___ home after my first session when a runner from the group asked if I wanted a coffee.","options":["walked","was walking","have walked"],"answer":"was walking","explanation":"Use the past continuous (“was walking”) for the longer background action in a story.","difficulty":1},{"prompt":"At first the early train felt exhausting, but I gradually ___ at six.","options":["used to wake up","got used to waking up","got used to wake up"],"answer":"got used to waking up","explanation":"“Got used to + -ing” means gradually becoming accustomed to a new routine; “used to + verb” is for old habits that stopped.","difficulty":2}]},{"key":"explicit-past-perfect-stretch","role":"light","name":"Past continuous background & explicit past perfect (optional B2 stretch)","explanation":"Only add the past perfect when an earlier past event explains what happened next in an explicit sequence; habitual \"would\" and present perfect continuous are deferred.","keyPoints":["Keep the sequence explicit: \"We missed the opening scene. The film had already started when we arrived.\"","Do not force past perfect when simple chronological order is already clear."],"example":"We missed the opening scene because the film had already started when we arrived.","items":[{"prompt":"We missed the opening scene. The film ___ when we arrived.","options":["already started","had already started","has already started"],"answer":"had already started","explanation":"The past perfect (“had already started”) makes it clear the film began before we arrived.","difficulty":2},{"prompt":"By the time we reached the café, our colleagues ___ a table by the window.","options":["already booked","had already booked","were booking"],"answer":"had already booked","explanation":"Use the past perfect for the earlier action that explains the situation when you arrived.","difficulty":2},{"prompt":"While I ___ for the late bus, I chatted to two neighbours for the first time.","options":["was waiting","had waited","used to wait"],"answer":"was waiting","explanation":"Past continuous sets the background scene interrupted by a shorter past action.","difficulty":1}]}],"vocab":[{"term":"adapt","pos":"verb","band":"B2","useRole":"B","definition":"gradually change your behaviour or habits to deal with a new situation","example":"I had to adapt to living abroad.","collocations":["adapt to living abroad","adapt to a new environment"],"wordFamily":["adapt","adaptable"],"note":"Guided B2 contrast: adapt to a change vs get used to a new routine (B1). Followed by to + noun or -ing.","gapFill":{"prompt":"After moving from Madrid to Glasgow, I had to ___ living in a much wetter climate.","options":["adapt to","adapt for","adapt with"],"answer":"adapt to","explanation":"Use \"adapt to\" followed by a noun or an -ing form (e.g. \"adapt to living abroad\")."},"sentencePrompt":"Write a sentence about a major change you had to adapt to (using adapt to + noun or -ing).","translation":"adaptarse","audioRef":"module-1/adapt.mp3"},{"term":"turning point","pos":"noun phrase","band":"B2","useRole":"B","definition":"the moment at which a situation changes in an important or decisive way","example":"Moving to Leeds was a turning point in my life.","collocations":["a turning point in my life","mark a turning point"],"wordFamily":["turning point"],"note":"Countable noun phrase: a turning point.","gapFill":{"prompt":"Moving to Leeds for a new job proved to be a ___ in my life.","options":["turning point","changing side","moving step"],"answer":"turning point","explanation":"\"A turning point\" is a countable noun phrase meaning a decisive moment of change."},"sentencePrompt":"Describe a turning point in your education, career, or personal life.","translation":"punto de inflexión","audioRef":"module-1/turning-point.mp3","audioUrl":"/audio/module-1/turning-point.mp3"},{"term":"challenge","pos":"noun","band":"B1","useRole":"P","definition":"something new and difficult that tests your ability or determination","example":"I faced several challenges while I was studying abroad.","collocations":["face a challenge","face several challenges"],"wordFamily":["challenge"],"note":"Common B1–B2 verb + noun collocation: face a challenge.","gapFill":{"prompt":"I ___ several challenges while I was studying abroad, especially understanding regional accents.","options":["faced","made","took"],"answer":"faced","explanation":"The natural collocation is \"face a challenge\" or \"face several challenges\"."},"sentencePrompt":"Write a sentence about a challenge you faced and how you handled it.","translation":"reto / desafío","audioRef":"module-1/challenge.mp3"},{"term":"get used to","pos":"verb phrase","band":"B1","useRole":"P","definition":"gradually become familiar and comfortable with a new situation or routine","example":"It took me a month to get used to living alone.","collocations":["get used to living alone","get used to a new routine"],"wordFamily":["get used to"],"note":"B1 core target: get used to + noun or -ing (not base verb). Contrast with guided B2 \"adapt to\".","gapFill":{"prompt":"It took me almost a month to ___ living alone in a quiet flat.","options":["get used to","use to","get using to"],"answer":"get used to","explanation":"Follow \"get used to\" with a noun or an -ing verb form (\"living\"), never a bare infinitive."},"sentencePrompt":"Write a sentence about something new you had to get used to (+ noun or -ing).","translation":"acostumbrarse a","audioRef":"module-1/get-used-to.mp3"},{"term":"look back on","pos":"phrasal verb","band":"B2","useRole":"B","definition":"think about something that happened in your past","example":"When I look back on my first year abroad, I remember the people I met.","collocations":["look back on my first year","look back fondly on"],"wordFamily":["look back on"],"note":"Multi-word verb followed by an object (e.g. look back on those years).","gapFill":{"prompt":"When I ___ my first year abroad, I mostly remember the generous neighbours I met.","options":["look back on","look forward on","look over at"],"answer":"look back on","explanation":"\"Look back on\" must take an object such as \"my first year abroad\"."},"sentencePrompt":"Write a sentence starting with \"When I look back on...\" about an important year.","translation":"recordar / echar la vista atrás","audioRef":"module-1/look-back-on.mp3","audioUrl":"/audio/module-1/look-back-on.mp3"},{"term":"regret","pos":"verb","band":"B1","useRole":"P","definition":"feel sorry or disappointed about something you did or did not do","example":"I've never regretted leaving my old job.","collocations":["never regret + -ing","regret leaving"],"wordFamily":["regret"],"note":"Model regret + -ing directly for past actions (e.g. regretted leaving, not regretted it).","gapFill":{"prompt":"Looking back, I've never regretted ___ my old job to retrain as a nurse.","options":["leaving","to leave","leave"],"answer":"leaving","explanation":"Use \"regret + -ing\" to talk about a past action you feel sorry (or not sorry) about."},"sentencePrompt":"Write a sentence using \"regret + -ing\" about a past decision.","translation":"arrepentirse de","audioRef":"module-1/regret.mp3"},{"term":"gradually","pos":"adverb","band":"B2","useRole":"B","definition":"slowly, over a period of time rather than all at once","example":"My English gradually improved while I was living in York.","collocations":["gradually improve","gradually build confidence"],"wordFamily":["gradually"],"note":"Opposite: suddenly.","gapFill":{"prompt":"At first I spoke very hesitantly, but my English ___ improved while I was living in York.","options":["gradually","suddenly","immediately"],"answer":"gradually","explanation":"\"Gradually\" means slowly over time, the opposite of \"suddenly\"."},"sentencePrompt":"Write a sentence about a skill or habit that gradually improved for you.","translation":"gradualmente / poco a poco","audioRef":"module-1/gradually.mp3"},{"term":"memorable","pos":"adjective","band":"B2","useRole":"B","definition":"worth remembering or easy to remember because it was unusual or significant","example":"Travelling alone was a memorable experience.","collocations":["a memorable experience","a memorable trip"],"wordFamily":["memorable"],"note":"Used for experiences worth remembering — not just positive ones.","gapFill":{"prompt":"Missing the last ferry in heavy rain turned an ordinary weekend into a ___ experience.","options":["memorable","memory","memorised"],"answer":"memorable","explanation":"\"Memorable\" describes an experience worth remembering, whether joyful or unexpectedly dramatic."},"sentencePrompt":"Write a sentence describing a memorable experience (positive or challenging).","translation":"memorable / inolvidable","audioRef":"module-1/memorable.mp3"}],"inputs":[{"kind":"listening","lesson":3,"title":"Three people, three changes","source":"Studio original — mixed accents","accent":"British & Australian English","speaker_accents":[{"speaker":"LAURA","accent":"en-GB","label":"British"},{"speaker":"DIEGO","accent":"en-IE","label":"Irish"},{"speaker":"MARI","accent":"en-US","label":"American"}],"seconds":120,"audioRef":"module-1/three-people-three-changes.mp3","audioStatus":"bundled","body":"LAURA: I had been teaching for six years when I finally booked a one-way ticket. I was terrified, but it turned out to be the best decision I have ever made. DIEGO: My parents came round to the idea eventually. At first they thought I was throwing away a good job, and to be honest, so did I. MARI: I only really settled down at thirty-five. Before that I was moving every eighteen months, and I had never owned furniture that I actually chose myself. Later in the programme, all three guests reflected on how difficult the very first month felt. Priya admitted she had nearly packed her bags after two weeks of grey skies, yet staying through that winter gave her a steady confidence she still relies on today. Dan noted that switching from long-haul flights to local rail journeys saved him time as well as money, while Rosa realised that teaching neighbours in person kept her grounded whenever work grew hectic.","questions":[{"prompt":"How long had Laura been teaching before she booked the ticket?","options":["Three years","Six years","Eighteen months"],"answer":"Six years"},{"prompt":"How do Diego's parents feel now?","options":["They still oppose the decision","They have slowly accepted it","They never found out"],"answer":"They have slowly accepted it"},{"prompt":"What does Mari say about her earlier life?","options":["She moved very often","She never had a job","She bought furniture every year"],"answer":"She moved very often"}]},{"kind":"reading","lesson":4,"title":"The year everything changed","source":"Studio original","audioRef":"module-1/the-year-everything-changed.mp3","audioStatus":"bundled","body":"Most people can name the year their life changed. For Ana it was 2020, when the restaurant she managed closed for good. She had spent a decade building a career she loved, and suddenly it had gone. What she remembers now is not the loss but the noise of it: one week she was planning a menu, the next she was queuing for a job she had never imagined doing. Two years later she runs a small cooking school, and she says she would not go back. The turning point, she insists, was not the closure itself but the first morning she stopped waiting for things to return to normal. At first, the slower pace felt uncomfortable because she had spent five years measuring every evening in completed tasks. Gradually, however, she noticed that walking to the corner shop without checking her phone made her far more observant. She started speaking to the baker, trading recipes with an elderly neighbour, and reading novels she had kept on her shelf for years. By December, the move no longer felt like an interruption to her career; instead, it had become the turning point that showed her what kind of daily rhythm she genuinely wanted to keep.","questions":[{"prompt":"What did Ana lose in 2020?","options":["A cooking school","The restaurant she managed","A house"],"answer":"The restaurant she managed"},{"prompt":"What does she remember most clearly?","options":["The suddenness of the change","The money she earned","The people she hired"],"answer":"The suddenness of the change"},{"prompt":"What does Ana identify as her real turning point?","options":["Losing her job","Opening the school","Accepting that normal had gone"],"answer":"Accepting that normal had gone"}]}],"speaking":[{"kind":"prompt_card","title":"A change you got used to (45–60s)","prompt":"Record 45–60 seconds. What changed? What was difficult, what helped, and what is different now? Listen to the model first, then hide it before recording.","seconds":55,"phrases":["The biggest challenge I faced was...","It took me a few weeks to get used to...","Since then, I’ve..."],"linkers":["Since then","Gradually"],"terms":["face a challenge","get used to","since then","gradually","look back on"],"modelAnswer":"When I moved to a new city last year, I didn’t know anyone. The biggest challenge I faced was meeting people outside work. It took me a few weeks to get used to spending my evenings alone.\n\nThen I joined a running group. I was nervous at the first session, but I gradually got to know the other runners. Since then, I’ve made a few friends, and the city feels more like home. When I look back on those first few weeks, I’m really glad I went to that first session.","b2Stretch":"Explain why the change mattered. If an earlier event explains what happened next, try the past perfect; it is not compulsory."}],"writing":{"title":"Personal narrative: a change and how things are now","prompt":"Write a short personal narrative (120–150 words) about a change you got used to. Describe what happened, what felt difficult at first, what helped, and close with one sentence about how things are now.","format":"short personal narrative","wordMin":120,"wordMax":150,"outline":{"analyze":"Purpose: share news and re-connect. Audience: a friend. Register: informal but correct.","plan":"Greeting → one clear change → two questions → suggestion → sign-off.","draft":"Use present perfect for news, past simple for finished details, and at least two phrasal verbs.","improve":"Replace 'very good' and 'nice' with precise adjectives; add one linker per paragraph.","review":"Check the word count, the greeting and closing, and that both questions are clear."}},"lessons":[{"dayOfWeek":"Mon","requirement":"optional","outputRequired":false,"minutes":15,"title":"Vocabulary: Personal experiences and change","objective":"Learn 8–10 core B1→B2 expressions for personal experiences and change, focusing on collocations and word families.","canDo":"I can use core personal experiences and change collocations accurately in short personal examples.","skill":"vocabulary","input":"reading","outputTitle":"Use 4 new personal experiences and change collocations","output":"Write or record 4 short sentences using this week's target collocations about personal experiences and change.","targetSeconds":75,"wordRange":[60,100]},{"dayOfWeek":"Tue","requirement":"optional","outputRequired":false,"minutes":15,"title":"Grammar: Past simple, present perfect & getting used to change","objective":"Practise separating finished past events from changes connected to now, story background, and used to vs got used to.","canDo":"I can tell a short story about a change and connect it to how things are now.","skill":"grammar","input":"reading","outputTitle":"Say & refine one sentence about a change","output":"Say (or type) one sentence connecting a past change to now using past simple + since then + present perfect, or got used to + -ing. Review feedback and try it once more.","targetSeconds":45,"wordRange":[60,100]},{"dayOfWeek":"Wed","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Listening: Three people, three changes","objective":"Listen for main ideas, speaker attitude, and detail in a multi-accent track on personal experiences and change.","canDo":"I can follow a 2-minute discussion about personal experiences and change and summarise key points.","skill":"listening","input":"listening","outputTitle":"Summarise what you heard","output":"Record or write a concise 2–3 sentence summary of the speaker's main point.","targetSeconds":75,"wordRange":[60,100]},{"dayOfWeek":"Thu","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Reading: The year everything changed","objective":"Read a B1→B2 text on personal experiences and change, tracking argument structure and implicit detail.","canDo":"I can identify the author's main claim and supporting evidence in an article on personal experiences and change.","skill":"reading","input":"reading","outputTitle":"Respond to the text","output":"State whether you agree with the article's main conclusion and give one supporting reason.","targetSeconds":75,"wordRange":[70,110]},{"dayOfWeek":"Fri","requirement":"required","outputRequired":true,"minutes":15,"title":"Speaking (Required): A change you got used to (45–60s)","objective":"Complete the required 75-second speaking task and self-check prosody in the Shadowing Lab.","canDo":"I can speak for 45–60 seconds about a change, what helped me adapt, and what is different now.","skill":"speaking","input":"listening","outputTitle":"Recorded speaking task (45–60s)","output":"Listen to the model first, hide it before recording, then speak for 45–60 seconds about a change you got used to.","targetSeconds":55,"wordRange":[80,130]},{"dayOfWeek":"Sat","requirement":"required","outputRequired":true,"minutes":30,"title":"Writing (Required): Personal narrative & how things are now","objective":"Plan, draft, and revise a 120–150 word text on personal experiences and change.","canDo":"I can write a well-structured 120–150 word response incorporating Narrative tenses & present perfect vs past simple.","skill":"writing","input":"reading","outputTitle":"Personal narrative: a change and how things are now","output":"Write a short personal narrative (120–150 words) about a change you got used to and close with one sentence about how things are now.","targetSeconds":75,"wordRange":[120,150]},{"dayOfWeek":"Sun","requirement":"optional","outputRequired":false,"minutes":15,"title":"Review: Week 1 cards & error log","objective":"Consolidate Week 1 vocabulary via spaced repetition and rewrite your week's recurring error patterns.","canDo":"I can recall this week's target vocabulary and self-correct my top grammar or collocation slips.","skill":"review","input":"reading","outputTitle":"Error-log self-correction","output":"Delayed recall (try without a phrase bank first): \"Tell me about a new routine that felt strange at first. What helped it feel normal?\" Also review this week’s SRS cards.","targetSeconds":60,"wordRange":[40,80],"delayedRecallPrompt":"Tell me about a new routine that felt strange at first. What helped it feel normal?"}],"vocabPack":{"collocations":[{"phrase":"make a big decision","band":"B1","useRole":"P","example":"I made a big decision about my future.","note":"Always use \"make\" (never \"do\") with \"decision\"."},{"phrase":"take a risk","band":"B2","useRole":"B","example":"I took a risk and applied for a job abroad.","note":"Fixed collocation: \"take a risk\", never \"make a risk\"."},{"phrase":"make a change","band":"B1","useRole":"P","example":"I decided to make a change and cycle to work.","note":"Natural chunk for starting a new personal habit or routine."},{"phrase":"keep in touch","band":"B1","useRole":"P","example":"I've kept in touch with my old school friends.","note":"Followed by \"with someone\"; opposite: \"lose touch\"."},{"phrase":"make progress","band":"B1","useRole":"P","example":"I've made a lot of progress since September.","note":"Uncountable: \"make progress\" (never \"a progress\")."},{"phrase":"take up","band":"B1","useRole":"P","example":"I took up photography after I moved.","note":"Phrasal verb meaning start a hobby, sport, or regular activity."}],"wordFamilies":[{"base":"change","forms":["unchanged"],"formDetails":[{"form":"unchanged","pos":"adj.","band":"B2","useRole":"O","example":"My working hours have remained unchanged."}],"example":"My working hours have remained unchanged despite moving to a new team.","note":"Optional B2 recognition form derived from \"change\"."},{"base":"adapt","forms":["adaptable"],"formDetails":[{"form":"adaptable","pos":"adj.","band":"B2","useRole":"O","example":"She's adaptable and learns new routines quickly."}],"example":"She's adaptable and learns new routines quickly when work changes.","note":"\"Adapt\" is taught in Core; \"adaptable\" is optional B2 recognition."},{"base":"decide","forms":["decision","decisive","indecisive"],"formDetails":[{"form":"decision","pos":"n.","band":"B1","useRole":"P","example":"It was a difficult decision."},{"form":"decisive","pos":"adj.","band":"B2","useRole":"O","example":"She's decisive: she makes decisions quickly and confidently."},{"form":"indecisive","pos":"adj.","band":"B2","useRole":"O","example":"I get indecisive when there are too many options."}],"example":"It was a difficult decision, though being decisive helps when others feel indecisive.","note":"Use \"decision\" productively (B1); keep \"decisive\" and \"indecisive\" for optional B2 recognition."}],"linkingExpressions":[{"expression":"eventually","functionLabel":"Time · outcome","band":"B2","useRole":"B","example":"Eventually, I got used to it.","note":"Shows the result after a period of time or effort."},{"expression":"since then","functionLabel":"Time · present link","band":"B1","useRole":"P","example":"I moved in September. Since then, I've made some good friends.","note":"Pairs naturally with the present perfect."}]}},{"number":2,"phase":"Month 1: Strengthen B1 foundations","title":"Plans, goals and ambitions","summary":"Describe an intention (going to), a confirmed arrangement (present continuous), and what you will do next using present-tense future time clauses.","hours":4,"releaseStage":"live","vocabularyTopic":"Plans, goals and ambitions","lightGrammar":"Timetables, predictions & first conditional (optional B2 stretch)","grammar":[{"key":"future-intentions-arrangements-time-clauses","role":"main","name":"Future intentions, arrangements & time clauses","explanation":"For an intention, use going to. For a confirmed arrangement, use the present continuous. In ordinary future time clauses (after when, as soon as, before, until), use a present form: \"I’ll apply when I finish.\" Keep indirect questions distinct: \"I don’t know when I’ll finish.\"","keyPoints":["Intention already decided: \"I’m going to take a short course this spring.\"","Confirmed arrangement in your schedule: \"I’m meeting someone from the college on Thursday.\"","Future time clause (no \"will\"): \"I’ll apply as soon as I finish the course.\"","Indirect questions keep \"will\": \"I don’t know when I’ll finish.\" (\"I will see my dentist tomorrow\" is also grammatical; pick the wording that best highlights the intended meaning.)"],"example":"My goal is to start a career in design. I’m going to take a short course this spring, and I’m meeting someone from the college on Thursday. When I finish the course, I’ll apply for junior roles.","items":[{"prompt":"You decided yesterday to retrain in web design this spring, though you have not booked a class yet. Which wording best highlights your intention?","options":["I’m going to take a short course this spring.","I’m taking a short course at 9 a.m. tomorrow.","I take a short course when I will be free."],"answer":"I’m going to take a short course this spring.","explanation":"“Going to” highlights a personal decision or intention before a fixed appointment is made.","difficulty":1},{"prompt":"Helena has made up her mind about her long-term work goal. Which sentence best highlights her intention?","options":["I’m going to start a career in nursing next year.","I’m starting a career in nursing at 10 a.m. today.","I start a career in nursing if I will pass."],"answer":"I’m going to start a career in nursing next year.","explanation":"Use “going to” to express a settled personal intention.","difficulty":1},{"prompt":"You have already agreed a 2 p.m. time with a college tutor for Thursday. Which wording best highlights that confirmed arrangement?","options":["I’m meeting someone from the college on Thursday.","I’m going to hope to meet someone someday.","I meet someone from the college when I will finish."],"answer":"I’m meeting someone from the college on Thursday.","acceptedAnswers":["I’m meeting someone from the college on Thursday.","I will meet someone from the college on Thursday."],"explanation":"Present continuous highlights a confirmed arrangement with an agreed time and person.","difficulty":1},{"prompt":"Dan has booked his train ticket and confirmed the interview slot with the studio. Complete his message: \"I ___ the design team in Bristol on Friday morning.\"","options":["’m meeting","’m going to think about meeting","meet when I will arrive"],"answer":"’m meeting","explanation":"A confirmed arrangement with a booked time and place takes the present continuous (“I’m meeting”).","difficulty":1},{"prompt":"I’ll apply as soon as I ___ the course.","options":["finish","will finish"],"answer":"finish","explanation":"In an ordinary future time clause after “as soon as”, use the present simple (“finish”), not “will”.","difficulty":1}]},{"key":"timetables-predictions-first-conditional","role":"light","name":"Timetables, predictions & first conditional (optional B2 stretch)","explanation":"Review predictions with will and indirect questions (\"I don’t know when I’ll finish\"), plus an optional first conditional for a realistic backup plan. Zero and second conditionals live in the Grammar Clinic.","keyPoints":["Indirect question: \"I don’t know when I’ll finish\" (different from time clause \"when I finish\").","Optional B2 stretch backup plan: \"If the spring course fills up, I’ll join the September cohort.\""],"example":"I don’t know when I’ll hear back, though if the first course fills up, I’ll book the autumn session.","items":[{"prompt":"Compare the indirect question: \"I don’t know when I ___ the portfolio.\"","options":["’ll finish","finishing","finished tomorrow"],"answer":"’ll finish","explanation":"After “I don’t know when...”, “when” introduces an indirect question, so “will” is natural.","difficulty":2},{"prompt":"If the spring class is full, I ___ for the September evening group instead.","options":["’ll apply","applied","am apply"],"answer":"’ll apply","explanation":"First conditional pairs present simple in the if-clause with “will” for a realistic alternative.","difficulty":1},{"prompt":"The train to Manchester ___ at 08:15 every weekday morning.","options":["leaves","is going to leave","will leaving"],"answer":"leaves","explanation":"Fixed public timetables normally use the present simple.","difficulty":1}]}],"vocab":[{"term":"ambition","pos":"noun","band":"B1","useRole":"P","definition":"a strong wish to achieve something important in your work or life","example":"Her ambition is to run her own restaurant.","collocations":["achieve an ambition","her ambition is to"],"wordFamily":["ambition","ambitious"],"note":"B1 productive target; pair with \"ambitious\" (guided B2).","gapFill":{"prompt":"Ever since university, her main ___ has been to run her own neighbourhood bakery.","options":["ambition","ambitious","ambitiously"],"answer":"ambition","explanation":"Use the noun \"ambition\" after \"her main\"; \"ambitious\" is the adjective."},"sentencePrompt":"Write a sentence about a personal or career ambition you hold.","translation":"ambición / meta","audioRef":"week-2/ambition.mp3"},{"term":"goal","pos":"noun","band":"B1","useRole":"P","definition":"something specific you want to achieve within a certain time","example":"I'm going to set myself a goal of reading one book a month.","collocations":["set myself a goal","reach a goal"],"wordFamily":["goal"],"note":"Natural B1 frame: set (myself) a goal of + -ing.","gapFill":{"prompt":"I'm going to ___ myself a goal of reading one short novel a month.","options":["set","do","bring"],"answer":"set","explanation":"In English we \"set (myself) a goal\" and \"achieve\" or \"reach a goal\"."},"sentencePrompt":"Write a sentence about a realistic goal you have set yourself this month.","translation":"objetivo / meta","audioRef":"week-2/goal.mp3"},{"term":"achieve","pos":"verb","band":"B1","useRole":"P","definition":"succeed in finishing or reaching something after steady effort","example":"With regular practice, you'll achieve your goal.","collocations":["achieve your goal","achieve a high standard"],"wordFamily":["achieve","achievement","achievable"],"note":"B1 productive verb; noun \"achievement\" (B1) and optional adjective \"achievable\" (B2).","gapFill":{"prompt":"With regular daily practice, you'll easily ___ your speaking goal by June.","options":["achieve","achievement","achievable"],"answer":"achieve","explanation":"Use the verb \"achieve\" after \"you'll\" (\"achieve your goal\")."},"sentencePrompt":"Write a sentence about something you hope to achieve in the next six months.","translation":"lograr / alcanzar","audioRef":"week-2/achieve.mp3"},{"term":"intend","pos":"verb","band":"B1","useRole":"P","definition":"have a firm plan or purpose to do something in the future","example":"We intend to move to the coast next year.","collocations":["intend to + infinitive","fully intend to"],"wordFamily":["intend"],"note":"Model intend to + infinitive as the standard frame.","gapFill":{"prompt":"We ___ to move to the coast next year once our lease ends.","options":["intend","intending","are intend"],"answer":"intend","explanation":"Use \"intend + to + infinitive\" to express a clear future plan."},"sentencePrompt":"Write a sentence starting with \"Next year I intend to...\" about a concrete plan.","translation":"tener intención de","audioRef":"week-2/intend.mp3"},{"term":"career","pos":"noun","band":"B1","useRole":"P","definition":"the series of jobs and working life that a person has in a particular field","example":"She's going to start a career in engineering.","collocations":["start a career in","change career"],"wordFamily":["career"],"note":"Refers to a whole working life, not just one single job. Model \"a career in + field\".","gapFill":{"prompt":"After finishing her degree, she's going to start a ___ in civil engineering.","options":["career","work","task"],"answer":"career","explanation":"\"A career in + field\" refers to a long-term professional path, not a single daily job."},"sentencePrompt":"Write a sentence about starting or developing a career in a field you like.","translation":"carrera profesional","audioRef":"week-2/career.mp3"},{"term":"deadline","pos":"noun","band":"B2","useRole":"B","definition":"a date or time by which a task must be finished","example":"We'll need to finish on Thursday to meet Friday's deadline.","collocations":["meet a deadline","miss a deadline"],"wordFamily":["deadline"],"note":"Guided B2 target: meet a deadline / miss a deadline.","gapFill":{"prompt":"We'll need to finish the report on Thursday in order to ___ Friday's deadline.","options":["meet","catch","arrive"],"answer":"meet","explanation":"Use \"meet a deadline\" (finish on time) or \"miss a deadline\" (finish late)."},"sentencePrompt":"Write a sentence about how you organise your week to meet a tight deadline.","translation":"fecha límite / plazo","audioRef":"week-2/deadline.mp3"},{"term":"apply","pos":"verb","band":"B1","useRole":"P","definition":"make a formal written request for a job, course, or place","example":"She's going to apply for a job at the museum.","collocations":["apply for a job","apply to an organisation"],"wordFamily":["apply"],"note":"Separate apply FOR a job/course from apply TO an organisation.","gapFill":{"prompt":"Tom is going to ___ the city council for a training grant next week.","options":["apply to","apply for","apply at"],"answer":"apply to","explanation":"Remember: apply TO a person or organisation, and apply FOR a job, course, or grant."},"sentencePrompt":"Write a sentence using \"apply for\" or \"apply to\" about a course or role.","translation":"solicitar / postularse","audioRef":"week-2/apply.mp3"},{"term":"look forward to","pos":"phrasal verb","band":"B1","useRole":"P","definition":"feel pleased and excited about something that is going to happen","example":"I'm looking forward to starting my new course.","collocations":["look forward to + -ing","look forward to + noun"],"wordFamily":["look forward to"],"note":"In \"look forward to\", \"to\" is a preposition: always follow with a noun or an -ing form.","gapFill":{"prompt":"I'm really looking forward to ___ my new evening course in September.","options":["starting","start","started"],"answer":"starting","explanation":"Because \"to\" is a preposition in \"look forward to\", use an -ing form or a noun."},"sentencePrompt":"Write a sentence about something upcoming you are looking forward to (+ -ing).","translation":"tener ganas de / esperar con ilusión","audioRef":"week-2/look-forward-to.mp3"},{"term":"determined","pos":"adjective","band":"B2","useRole":"B","definition":"having made a firm decision and refusing to let difficulties stop you","example":"He's determined to pass, so he's going to practise every day.","collocations":["determined to + infinitive","determined to succeed"],"wordFamily":["determined"],"note":"Guided B2 target: followed by to + infinitive.","gapFill":{"prompt":"He's determined ___ his B2 exam in June, so he's going to practise every morning.","options":["to pass","passing","pass"],"answer":"to pass","explanation":"\"Determined\" is followed by \"to + infinitive\" (e.g. \"determined to pass\")."},"sentencePrompt":"Write a sentence about something you are determined to finish this year.","translation":"decidido / resuelto","audioRef":"week-2/determined.mp3"}],"inputs":[{"kind":"listening","lesson":3,"title":"Two planners, two routes","source":"Fluency Studio Podcast","accent":"British & Canadian English","speaker_accents":[{"speaker":"Host","accent":"en-GB","label":"British English"},{"speaker":"Guest","accent":"en-CA","label":"Canadian English"}],"seconds":120,"audioRef":"week-2/two-planners-two-routes.mp3","audioStatus":"tts","body":"Host: Welcome back to Next Step. Today we are comparing two very different ways people plan the next twelve months. Tessa trained in graphic design at night while keeping her daytime office role, whereas Owen saved for a year and took a six-month break to retrain. Tessa, did having a fixed schedule help? Tessa: Definitely. I booked my evening studio sessions every Tuesday before work even started, so I knew I was going to finish my portfolio by June. If I had waited for spare energy at weekends, nothing would have happened. Host: And Owen, what convinced you to leave your job temporarily? Owen: Honestly, my workload was exhausting. If you work fifty hours a week, you rarely have headspace for creative study. I told myself that if I saved enough to cover rent, I would take the leap in October. I am starting an internship next Monday, and looking back, setting one clear deadline made every smaller choice much easier.","questions":[{"prompt":"How did Tessa make sure she finished her portfolio by June?","options":["She resigned from her office job immediately","She booked regular Tuesday evening studio sessions in advance","She waited for free weekends to study"],"answer":"She booked regular Tuesday evening studio sessions in advance"},{"prompt":"Why did Owen decide to take a six-month break?","options":["His heavy workload left too little headspace for study","His company closed his department","He wanted to move to another country permanently"],"answer":"His heavy workload left too little headspace for study"}]},{"kind":"reading","lesson":4,"title":"Why small milestones beat vague resolutions","source":"Fluency Studio Feature","audioRef":"week-2/small-milestones.mp3","audioStatus":"tts","body":"Every January, millions of people announce ambitious plans to learn a language, change careers, or run a half-marathon. Yet by March, most of those promises quietly fade. Research on adult learning suggests the problem is rarely a lack of motivation; more often, the goal itself is too abstract to guide Tuesday evening decisions. Saying \"I am going to improve my English\" leaves too much room for hesitation, whereas committing to a fifteen-minute daily routine removes guesswork. When learners define concrete checkpoints—such as recording a ninety-second summary every Friday—progress becomes visible. Equally important is planning for realistic obstacles. If a busy week interrupts your usual timetable, having a backup slot protects momentum rather than triggering guilt. Goals succeed when they fit ordinary life, not only ideal weeks. For example, a trainee accountant studying part-time might block out Tuesday and Thursday mornings at seven-thirty before clients start calling. If an urgent audit disrupts Thursday, she already knows Sunday afternoon serves as her catch-up slot. Over sixteen weeks, those steady, realistic habits compound far more reliably than an exhausting burst of weekend cramming that ends before spring.","questions":[{"prompt":"According to the article, why do many resolutions fail by March?","options":["Learners lack any motivation from the beginning","Goals are often too vague to guide daily choices","Fifteen-minute sessions are too short to matter"],"answer":"Goals are often too vague to guide daily choices"},{"prompt":"What helps protect momentum during a busy week?","options":["Waiting until next month to restart","Doubling the target on Sunday","Having a practical backup slot in your schedule"],"answer":"Having a practical backup slot in your schedule"}]}],"speaking":[{"kind":"prompt_card","title":"A goal and the next step (45–60s)","prompt":"Record 45–60 seconds. Share one goal, one step already arranged and what you’ll do when that step is complete. Listen to the model first, then hide it before recording.","seconds":55,"phrases":["My goal is to...","I’m going to...","I’m meeting...","When I finish..., I’ll..."],"linkers":["In order to","When"],"terms":["goal","intend","career","look forward to"],"modelAnswer":"My goal is to start a career in design. I’m going to take a short course this spring, and I’m meeting someone from the college on Thursday. I’m looking forward to seeing some of the students’ work. A friend who did the course has offered to help me choose a project. When I finish the course, I’ll apply for a few junior roles and use my project to show what I can do.","b2Stretch":"Explain why the goal matters and give a realistic alternative if the first plan changes. A first conditional can help; do not require it."}],"writing":{"title":"Friendly message: goal, arrangement & next step","prompt":"Write a 120–150 word message to a friend about one goal you are working towards, a confirmed arrangement you have made, and what you will do next when that step is complete.","format":"informal message","wordMin":120,"wordMax":150,"outline":{"analyze":"Purpose: argue a position. Audience: an educated general reader. Format: one paragraph or two short ones.","plan":"Position in the first sentence → reason one with an example → reason two → concession → restated position.","draft":"Use one first or second conditional and two future forms.","improve":"Vary sentence openings; replace 'a lot of' with a precise quantifier.","review":"Check the position is visible in the first and last sentences."}},"lessons":[{"dayOfWeek":"Mon","requirement":"optional","outputRequired":false,"minutes":15,"title":"Vocabulary: Plans, goals and ambitions","objective":"Learn 8–10 core B1→B2 expressions for plans, goals and ambitions, focusing on collocations and word families.","canDo":"I can use core plans, goals and ambitions collocations accurately in short personal examples.","skill":"vocabulary","input":"reading","outputTitle":"Use 4 new plans, goals and ambitions collocations","output":"Write or record 4 short sentences using this week's target collocations about plans, goals and ambitions.","targetSeconds":75,"wordRange":[60,100]},{"dayOfWeek":"Tue","requirement":"optional","outputRequired":false,"minutes":15,"title":"Grammar: Intentions, arrangements & future time clauses","objective":"Distinguish intentions (going to), confirmed arrangements (present continuous), and present-tense future time clauses.","canDo":"I can describe an intention, a confirmed arrangement, and what happens next.","skill":"grammar","input":"reading","outputTitle":"Say & refine one sentence about your next step","output":"Say (or type) one sentence sharing an intention (going to), an arrangement (present continuous), or a next-step time clause (when / as soon as + present). Check feedback and try again.","targetSeconds":45,"wordRange":[60,100]},{"dayOfWeek":"Wed","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Listening: Two planners, two routes","objective":"Listen for main ideas, speaker attitude, and detail in a multi-accent track on plans, goals and ambitions.","canDo":"I can follow a 2-minute discussion about plans, goals and ambitions and summarise key points.","skill":"listening","input":"listening","outputTitle":"Summarise what you heard","output":"Record or write a concise 2–3 sentence summary of the speaker's main point.","targetSeconds":75,"wordRange":[60,100]},{"dayOfWeek":"Thu","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Reading: Why small milestones beat vague resolutions","objective":"Read a B1→B2 text on plans, goals and ambitions, tracking argument structure and implicit detail.","canDo":"I can identify the author's main claim and supporting evidence in an article on plans, goals and ambitions.","skill":"reading","input":"reading","outputTitle":"Respond to the text","output":"State whether you agree with the article's main conclusion and give one supporting reason.","targetSeconds":75,"wordRange":[70,110]},{"dayOfWeek":"Fri","requirement":"required","outputRequired":true,"minutes":15,"title":"Speaking (Required): A goal and the next step (45–60s)","objective":"Complete the required 75-second speaking task and self-check prosody in the Shadowing Lab.","canDo":"I can speak for 45–60 seconds about a goal, one arranged step, and what I will do afterwards.","skill":"speaking","input":"listening","outputTitle":"Recorded speaking task (45–60s)","output":"Listen to the model first, hide it before recording, then share your goal, arranged step, and next action in 45–60 seconds.","targetSeconds":55,"wordRange":[80,130]},{"dayOfWeek":"Sat","requirement":"required","outputRequired":true,"minutes":30,"title":"Writing (Required): Message about a goal & arrangement","objective":"Plan, draft, and revise a 120–150 word text on plans, goals and ambitions.","canDo":"I can write a well-structured 120–150 word response incorporating Future forms.","skill":"writing","input":"reading","outputTitle":"Friendly message: goal, arrangement & next step","output":"Write a 120–150 word message to a friend about one goal, a confirmed arrangement, and your next step.","targetSeconds":75,"wordRange":[120,150]},{"dayOfWeek":"Sun","requirement":"optional","outputRequired":false,"minutes":15,"title":"Review: Week 2 cards & error log","objective":"Consolidate Week 2 vocabulary via spaced repetition and rewrite your week's recurring error patterns.","canDo":"I can recall this week's target vocabulary and self-correct my top grammar or collocation slips.","skill":"review","input":"reading","outputTitle":"Error-log self-correction","output":"Delayed recall (try without a phrase bank first): \"You’ve decided to learn a new skill. What have you arranged, and what will you do afterwards?\" Also review this week’s SRS cards.","targetSeconds":60,"wordRange":[40,80],"delayedRecallPrompt":"You’ve decided to learn a new skill. What have you arranged, and what will you do afterwards?"}],"vocabPack":{"collocations":[{"phrase":"work towards","band":"B1","useRole":"P","example":"Next year I'll be working towards a degree in nursing.","note":"UK spelling: \"towards\" (US often drops the -s: \"toward\")."},{"phrase":"take the first step","band":"B1","useRole":"P","example":"I'll take the first step and contact the college.","note":"Means beginning an action or long-term plan."},{"phrase":"improve your skills","band":"B1","useRole":"P","example":"This course will help you improve your skills.","note":"High-frequency B1 collocation for training and study plans."},{"phrase":"put (something) off","band":"B1","useRole":"P","example":"Don't put off booking the course.","note":"Separable phrasal verb meaning delay/postpone. With a pronoun: \"put it off\"."}],"wordFamilies":[{"base":"ambition","forms":["ambitious"],"formDetails":[{"form":"ambitious","pos":"adj.","band":"B2","useRole":"B","example":"She has an ambitious plan to open two cafés in a year."}],"example":"She has an ambitious plan to open two cafés in a year.","note":"\"Ambition\" is taught in Core; use \"ambitious\" as guided B2."},{"base":"achieve","forms":["achievement","achievable"],"formDetails":[{"form":"achievement","pos":"n.","band":"B1","useRole":"P","example":"Finishing the course was a real achievement."},{"form":"achievable","pos":"adj.","band":"B2","useRole":"O","example":"Choose a goal that is challenging but achievable."}],"example":"Finishing the course was a real achievement because we chose an achievable weekly target.","note":"\"Achieve\" is in Core; \"achievement\" is B1 productive and \"achievable\" is optional B2."},{"base":"succeed","forms":["succeed","success","successful","successfully"],"formDetails":[{"form":"succeed","pos":"v.","band":"B1","useRole":"P","example":"I hope the project succeeds."},{"form":"success","pos":"n.","band":"B1","useRole":"P","example":"The first event was a success."},{"form":"successful","pos":"adj.","band":"B1","useRole":"P","example":"It was a successful event."},{"form":"successfully","pos":"adv.","band":"B2","useRole":"B","example":"We successfully completed the project on time."}],"example":"The first event was a success; it succeeded because the team worked together successfully.","note":"Use succeed/success/successful productively (B1) and successfully as guided B2."}],"linkingExpressions":[{"expression":"in order to","functionLabel":"Purpose","band":"B1","useRole":"P","example":"In order to save money, I'll cook at home.","note":"Use \"in order to + base verb\" to express purpose clearly."}]}},{"number":3,"phase":"Month 1: Strengthen B1 foundations","title":"Daily life and social interaction","summary":"Tell a flatmate what is required, forbidden, or optional, and give practical advice with polite permission.","hours":4,"releaseStage":"live","vocabularyTopic":"Daily life, relationships & social interaction","lightGrammar":"Polite permission & indirect questions (extension)","grammar":[{"key":"house-rules-obligation-prohibition-advice","role":"main","name":"House rules: have to, mustn’t, don’t have to & should","explanation":"Use have to for a requirement, mustn’t for something forbidden, don’t have to for something optional, and should for advice. In a permission exchange, \"Could I ...?\" softens the question and \"Yes, you can\" grants permission.","keyPoints":["Required: \"We have to clean up after cooking.\"","Forbidden: \"We mustn’t leave the cooker on when we go out.\"","Optional (allowed, not required): \"You don’t have to cook for everyone.\"","Practical advice: \"We should arrange a cleaning rota around our work hours.\" (Past ability is deferred.)"],"example":"We have to clean up after cooking, and we mustn’t leave the cooker on when we go out. You don’t have to cook for everyone, though we should arrange a fair rota.","items":[{"prompt":"Taking turns cooking is optional. You ___ cook on Mondays.","options":["mustn’t","don’t have to"],"answer":"don’t have to","explanation":"“Don’t have to” means cooking on Mondays is allowed, not required; “mustn’t” means forbidden.","difficulty":1},{"prompt":"Everyone in the flatshare is required to keep the hallway clear. You ___ leave bikes blocking the front door.","options":["mustn’t","don’t have to","should to"],"answer":"mustn’t","explanation":"Something forbidden or unsafe takes “mustn’t”.","difficulty":1},{"prompt":"The bin collection is early on Wednesday, so all flatmates ___ put the recycling outside on Tuesday night.","options":["have to","don’t have to","mustn’t"],"answer":"have to","explanation":"A shared household requirement takes “have to”.","difficulty":1},{"prompt":"Which sentence uses the modal verb form accurately?","options":["You mustn’t to use the washing machine after ten.","You don’t have to wash every pan straight away.","Does he has to lock the back gate?"],"answer":"You don’t have to wash every pan straight away.","explanation":"Use a bare infinitive after “mustn’t” (no “to”) and “have to” (not “has to”) after “does”.","difficulty":2},{"prompt":"Two flatmates work late shifts and keep missing each other. What is the best practical suggestion?","options":["We should arrange a cleaning rota around our work hours.","We mustn’t speak to anyone in the kitchen.","We don’t have to have a front door."],"answer":"We should arrange a cleaning rota around our work hours.","explanation":"Use “should” to give a practical, polite suggestion.","difficulty":1}]},{"key":"polite-permission-indirect-questions","role":"light","name":"Polite permission & indirect questions (extension)","explanation":"Use \"Could I ...?\" to soften permission requests and \"Yes, you can\" to grant permission. For B2 stretch negotiation, use indirect question frames like \"Could you tell me when you usually get home?\"","keyPoints":["Soften permission: \"Could I use the washing machine tonight?\" → \"Yes, you can, if it’s before ten.\"","B2 stretch indirect question: \"Could you tell me when you usually get home?\" (keep statement word order)."],"example":"Could I use the washing machine tonight? — Yes, you can, if it’s before ten. Could you tell me when you usually get home?","items":[{"prompt":"New flatmate: \"___ use the washing machine tonight?\" You: \"Yes, you can, if it’s before ten.\"","options":["Could I","Have I to","Shouldn’t I"],"answer":"Could I","explanation":"“Could I...?” softens a polite request for permission.","difficulty":1},{"prompt":"Could you tell me when ___ home in the evenings?","options":["you usually get","do you usually get","are you usually get"],"answer":"you usually get","explanation":"Indirect questions keep subject + verb word order without “do”.","difficulty":2},{"prompt":"What time ___ the bins usually get collected on our street?","options":["do","are","have"],"answer":"do","explanation":"Direct present-simple questions with a main verb take “do”.","difficulty":1}]}],"vocab":[{"term":"get on with","pos":"phrasal verb","band":"B1","useRole":"P","definition":"have a friendly, easy relationship with someone","example":"You don't have to be close friends to get on with your colleagues.","collocations":["get on with colleagues","get on really well"],"wordFamily":["get on with"],"note":"Pair with catch up with (exchange news) and get in touch with (initiate contact).","ukUsNote":"Audio note: British English prefers \"get on with\", while American/international speakers often say \"get along with\".","gapFill":{"prompt":"You don't have to be close friends to ___ your colleagues in a shared office.","options":["get on with","get across to","get round to"],"answer":"get on with","explanation":"In British English, \"get on with someone\" (US: \"get along with\") means have a friendly relationship."},"sentencePrompt":"Write a sentence about someone at work, school, or home whom you get on with well.","translation":"llevarse bien con","audioRef":"week-3/get-on-with.mp3"},{"term":"catch up (with)","pos":"phrasal verb","band":"B2","useRole":"B","definition":"meet or speak to someone you have not seen recently to exchange news","example":"Can we meet after work and catch up?","collocations":["catch up after work","catch up with old friends"],"wordFamily":["catch up"],"note":"Guided B2 target meaning \"exchange news\". Can be used with or without \"with someone\".","gapFill":{"prompt":"We have not spoken since Easter — can we meet for a coffee after work and ___?","options":["catch up","pick up","make up"],"answer":"catch up","explanation":"\"Catch up\" means exchange news with someone you have not seen for a while."},"sentencePrompt":"Write a sentence about a friend you want to catch up with soon.","translation":"ponerse al día con","audioRef":"week-3/catch-up.mp3"},{"term":"arrange","pos":"verb","band":"B1","useRole":"P","definition":"plan and agree on the time and place for something to happen","example":"We should arrange to meet outside the station.","collocations":["arrange to meet","make arrangements"],"wordFamily":["arrange"],"note":"Follow with to + infinitive (arrange to meet).","gapFill":{"prompt":"We ought to ___ to meet outside the station ten minutes before the concert.","options":["arrange","arrange for","arranging"],"answer":"arrange","explanation":"Follow \"arrange\" with \"to + infinitive\" (\"arrange to meet\")."},"sentencePrompt":"Write a sentence about plans you recently arranged to do with friends or colleagues.","translation":"quedar / organizar","audioRef":"week-3/arrange.mp3"},{"term":"routine","pos":"noun","band":"B1","useRole":"P","definition":"the usual order and way in which you regularly do daily things","example":"Try to stick to a routine during busy weeks.","collocations":["stick to a routine","a daily routine"],"wordFamily":["routine"],"note":"B1 collocation: stick to a routine.","gapFill":{"prompt":"Try to ___ a calm morning routine during busy weeks at work.","options":["stick to","hang on","stay in"],"answer":"stick to","explanation":"Common collocation: \"stick to a routine\" (or \"break your routine\")."},"sentencePrompt":"Write a sentence describing one habit in your daily routine that keeps you productive.","translation":"rutina","audioRef":"week-3/routine.mp3"},{"term":"rely on","pos":"phrasal verb","band":"B2","useRole":"B","definition":"trust someone or something to support you or work when needed","example":"You can rely on Maria to help if there's a problem.","collocations":["rely on someone to help","rely on public transport"],"wordFamily":["rely on","reliable","unreliable","reliably"],"note":"Guided B2 target. Related adjective/adverb forms (reliable, unreliable, reliably) are in Word Families.","gapFill":{"prompt":"You can always ___ Maria to stay calm and help if there's an urgent problem.","options":["rely on","rely to","rely with"],"answer":"rely on","explanation":"Always pair \"rely\" with the preposition \"on\" (\"rely on someone to do something\")."},"sentencePrompt":"Write a sentence about a friend or colleague you can rely on.","translation":"confiar en / depender de","audioRef":"week-3/rely-on.mp3"},{"term":"misunderstanding","pos":"noun","band":"B2","useRole":"B","definition":"a situation in which someone fails to understand something correctly","example":"We should talk and clear up the misunderstanding.","collocations":["clear up a misunderstanding","a slight misunderstanding"],"wordFamily":["misunderstanding"],"note":"Guided B2 target; pairs naturally with \"clear up\".","gapFill":{"prompt":"We should have a quick chat tonight and ___ the misunderstanding about the rota.","options":["clear up","wipe out","turn off"],"answer":"clear up","explanation":"We \"clear up a misunderstanding\" when we explain what was actually meant."},"sentencePrompt":"Write a sentence about a small misunderstanding and how it was cleared up.","translation":"malentendido","audioRef":"week-3/misunderstanding.mp3"},{"term":"invite (someone) round","pos":"phrasal verb","band":"B1","useRole":"P","definition":"ask someone politely to come to your home for a meal, coffee, or visit","example":"Can I invite some friends round on Saturday?","collocations":["invite someone round","invite friends round for dinner"],"wordFamily":["invite (someone) round"],"note":"Natural British English for hosting at home.","ukUsNote":"Audio note: \"Invite someone round\" is natural British English; \"invite someone over\" also works in both UK and US English.","gapFill":{"prompt":"Now that we have unpacked the boxes, can we ___ some friends ___ on Saturday?","options":["invite ... round","invite ... across","invite ... into"],"answer":"invite ... round","explanation":"In British English we naturally say \"invite someone round\" (or \"over\") to your home."},"sentencePrompt":"Write a sentence using \"invite ... round\" (or \"over\") for a meal or coffee.","translation":"invitar a casa","audioRef":"week-3/invite-round.mp3"},{"term":"awkward (situation)","pos":"adjective","band":"B2","useRole":"B","definition":"uncomfortable or causing embarrassment in a social situation","example":"It was an awkward situation, but we managed to talk it through.","collocations":["an awkward situation","talk through an awkward situation"],"wordFamily":["awkward (situation)"],"note":"Guided B2 sense: a situation that causes embarrassment (always practise around the situation).","gapFill":{"prompt":"When two colleagues realised they had booked the same meeting room, it created an ___ situation.","options":["awkward","easy","ordinary"],"answer":"awkward","explanation":"\"An awkward situation\" is the B2 collocation for an uncomfortable, embarrassing social moment."},"sentencePrompt":"Write a sentence describing an awkward situation and how people dealt with it.","translation":"situación incómoda","audioRef":"week-3/awkward-situation.mp3"}],"inputs":[{"kind":"listening","lesson":3,"title":"Flatshare rules without the drama","source":"Fluency Studio Everyday Dialogue","accent":"British & Irish English","speaker_accents":[{"speaker":"Liam","accent":"en-IE","label":"Irish English"},{"speaker":"Chloe","accent":"en-GB","label":"British English"}],"seconds":120,"audioRef":"week-3/flatshare-rules.mp3","audioStatus":"tts","body":"Liam: Hey Chloe, could we have a quick word about the kitchen rota before everyone heads out? Chloe: Of course. Is everything alright? Liam: Yeah, mostly great, though we ought to agree on a simple rule for late-night washing-up. Nobody has to clean every pan straight after dinner if they are exhausted, so long as it is cleared before nine the next morning. Chloe: That sounds fair. Also, could you remind Sam that guests shouldn’t leave bikes in the narrow hallway? Last Tuesday I could barely open the front door with my shopping. Liam: Good point—I will mention it gently tonight. Do you know if everyone is free on Sunday afternoon to catch up over tea? Having a relaxed chat once a month stops small annoyances turning into big arguments.","questions":[{"prompt":"What does Liam suggest about washing-up after dinner?","options":["Everyone must wash pans immediately at night","Dirty dishes should be cleared by nine the next morning","Only weekend guests should use the kitchen"],"answer":"Dirty dishes should be cleared by nine the next morning"},{"prompt":"Why did Chloe struggle to open the front door on Tuesday?","options":["The lock was broken","Bikes had been left in the narrow hallway","Parcels blocked the stairs"],"answer":"Bikes had been left in the narrow hallway"}]},{"kind":"reading","lesson":4,"title":"The unwritten rules of good conversation","source":"Fluency Studio Lifestyle Essay","audioRef":"week-3/good-conversation.mp3","audioStatus":"tts","body":"Many intermediate learners assume that good conversation in English depends on knowing rare idioms or speaking very quickly. In practice, people remember how easy you were to talk to, not how complicated your grammar sounded. One simple habit makes an immediate difference: asking open follow-up questions instead of firing rapid yes-or-no queries. For instance, asking \"What made you choose that neighbourhood?\" invites a story, whereas \"Do you like your area?\" often ends in a single word. Polite modal phrases also soften everyday requests. Saying \"Would you mind lowering the volume a little?\" keeps goodwill intact in shared offices or flats, whereas direct imperatives can sound unintentionally abrupt. Finally, small talk is rarely wasted effort. A two-minute chat about a local café or weekend plans signals warmth and builds trust before any serious discussion begins. Equally helpful is noticing turn-taking cues in lively groups. Pauses, brief summaries like \"So you mean…\", and friendly eye contact make quieter speakers feel welcome to contribute. When someone shares a different viewpoint, acknowledging what makes sense in their comment before adding your own keeps the atmosphere constructive rather than defensive—turns everyday small talk into genuine connection.","questions":[{"prompt":"Why does the text recommend open follow-up questions?","options":["They test the listener’s vocabulary","They invite stories rather than one-word answers","They make conversations shorter"],"answer":"They invite stories rather than one-word answers"},{"prompt":"How do polite modal phrases help in shared spaces?","options":["They soften requests and protect goodwill","They replace the need to listen","They avoid discussing rules altogether"],"answer":"They soften requests and protect goodwill"}]}],"speaking":[{"kind":"role_play","title":"Agree on house rules (45–60s flatmate exchange)","prompt":"Take two or three turns with a new flatmate (45–60s). Explain one shared responsibility, one rule and one optional routine. Suggest a compromise if the flatmate works late. Listen to the model first, then hide it before recording.","seconds":55,"phrases":["We have to...","We mustn’t...","You don’t have to...","We should arrange..."],"linkers":["Apart from that","On the other hand"],"terms":["get on with","arrange","routine","politely"],"modelAnswer":"New flatmate: What do I need to know about the kitchen?\nYou: We have to clean up after cooking, and we mustn’t leave the cooker on when we go out. You don’t have to cook for everyone.\nNew flatmate: I sometimes work late. Could I use the washing machine tonight?\nYou: Yes, you can, if it’s before ten. We should arrange a cleaning rota around our work hours.","b2Stretch":"Negotiate a different arrangement without a script. If a question frame helps, offer \"Could you tell me when you usually get home?\""}],"writing":{"title":"Welcome message for a new flatmate","prompt":"Write a 120–150 word welcome message for a new flatmate explaining one shared responsibility (have to), one rule (mustn’t), one optional routine (don’t have to), and a helpful suggestion (should). Use a revised linker such as \"apart from that\" only if it fits.","format":"friendly flatshare message","wordMin":120,"wordMax":150,"outline":{"analyze":"Note who you are writing to and keep the tone warm yet polite.","plan":"Greeting -> polite request -> what is/isn’t necessary -> arranged time.","draft":"Include at least two modals of obligation/permission and one indirect question.","improve":"Check that polite requests use could/would rather than bare imperatives.","review":"Check word count (120–150 words) and linkers (although, because, so)."}},"lessons":[{"dayOfWeek":"Mon","requirement":"optional","outputRequired":false,"minutes":15,"title":"Vocabulary: Daily life and social interaction","objective":"Learn 8–10 core B1→B2 expressions for daily life and social interaction, focusing on collocations and word families.","canDo":"I can use core daily life and social interaction collocations accurately in short personal examples.","skill":"vocabulary","input":"reading","outputTitle":"Use 4 new daily life and social interaction collocations","output":"Write or record 4 short sentences using this week's target collocations about daily life and social interaction.","targetSeconds":75,"wordRange":[60,100]},{"dayOfWeek":"Tue","requirement":"optional","outputRequired":false,"minutes":15,"title":"Grammar: Requirement, prohibition, no obligation & advice","objective":"Practise separating have to (required), mustn’t (forbidden), don’t have to (optional), and should (practical advice).","canDo":"I can tell a flatmate what is required, forbidden, or optional, and offer advice.","skill":"grammar","input":"reading","outputTitle":"Say & refine one flatshare rule or suggestion","output":"Say (or type) one sentence telling a new flatmate what is required, forbidden, or optional—or offering advice with should. Check feedback and try it once more.","targetSeconds":45,"wordRange":[60,100]},{"dayOfWeek":"Wed","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Listening: Flatshare rules without the drama","objective":"Listen for main ideas, speaker attitude, and detail in a multi-accent track on daily life and social interaction.","canDo":"I can follow a 2-minute discussion about daily life and social interaction and summarise key points.","skill":"listening","input":"listening","outputTitle":"Summarise what you heard","output":"Record or write a concise 2–3 sentence summary of the speaker's main point.","targetSeconds":75,"wordRange":[60,100]},{"dayOfWeek":"Thu","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Reading: The unwritten rules of good conversation","objective":"Read a B1→B2 text on daily life and social interaction, tracking argument structure and implicit detail.","canDo":"I can identify the author's main claim and supporting evidence in an article on daily life and social interaction.","skill":"reading","input":"reading","outputTitle":"Respond to the text","output":"State whether you agree with the article's main conclusion and give one supporting reason.","targetSeconds":75,"wordRange":[70,110]},{"dayOfWeek":"Fri","requirement":"required","outputRequired":true,"minutes":15,"title":"Speaking (Required): Agree on house rules (45–60s)","objective":"Complete the required 75-second speaking task and self-check prosody in the Shadowing Lab.","canDo":"I can handle a 2–3 turn exchange with a flatmate about house rules, optional routines, and a compromise.","skill":"speaking","input":"listening","outputTitle":"Recorded flatmate exchange (45–60s)","output":"Listen to the 2-turn flatmate model, hide it before recording, then deliver your own 45–60 second response.","targetSeconds":55,"wordRange":[80,130]},{"dayOfWeek":"Sat","requirement":"required","outputRequired":true,"minutes":30,"title":"Writing (Required): Welcome message for a new flatmate","objective":"Plan, draft, and revise a 120–150 word text on daily life and social interaction.","canDo":"I can write a well-structured 120–150 word response using house-rule modals (have to, mustn't, don't have to, should).","skill":"writing","input":"reading","outputTitle":"Welcome message for a new flatmate","output":"Write a 120–150 word welcome message for a new flatmate covering rules, optional routines, and a polite suggestion.","targetSeconds":75,"wordRange":[120,150]},{"dayOfWeek":"Sun","requirement":"optional","outputRequired":false,"minutes":15,"title":"Review: Week 3 cards & error log","objective":"Consolidate Week 3 vocabulary via spaced repetition and rewrite your week's recurring error patterns.","canDo":"I can recall this week's target vocabulary and self-correct my top grammar or collocation slips.","skill":"review","input":"reading","outputTitle":"Error-log self-correction","output":"Delayed recall (try without a phrase bank first): \"Tell a new colleague one thing they need to do, one thing they mustn’t do and one thing that’s optional.\" Also review this week’s SRS cards.","targetSeconds":60,"wordRange":[40,80],"delayedRecallPrompt":"Tell a new colleague one thing they need to do, one thing they mustn’t do and one thing that’s optional."}],"vocabPack":{"collocations":[{"phrase":"make an effort","band":"B1","useRole":"P","example":"We should make an effort to welcome new colleagues.","note":"Always \"make an effort\" (never \"do an effort\")."},{"phrase":"have a lot in common","band":"B1","useRole":"P","example":"We have a lot in common: we both love cycling.","note":"Negative form: \"have nothing in common\"."},{"phrase":"get in touch","band":"B1","useRole":"P","example":"You should get in touch with the organiser.","note":"Means initiate contact by phone, message, or email."},{"phrase":"come over","band":"B1","useRole":"P","example":"Can you come over for coffee on Saturday?","note":"Standard B1 phrasing for visiting someone at their home (informal BrE \"pop round\" is optional)."},{"phrase":"keep a promise","band":"B2","useRole":"B","example":"You should keep a promise even if it's difficult.","note":"Guided B2 collocation; opposite: \"break a promise\"."}],"wordFamilies":[{"base":"friend","forms":["unfriendly","friendship"],"formDetails":[{"form":"unfriendly","pos":"adj.","band":"B1","useRole":"P","example":"The receptionist seemed unfriendly."},{"form":"friendship","pos":"n.","band":"B1","useRole":"P","example":"Our friendship began at school."}],"example":"Although the receptionist seemed unfriendly at first, our friendship with the team began on day one.","note":"Both \"unfriendly\" and \"friendship\" are B1 productive targets."},{"base":"polite","forms":["politely","politeness","impolite"],"formDetails":[{"form":"politely","pos":"adv.","band":"B1","useRole":"P","example":"You can disagree politely."},{"form":"politeness","pos":"n.","band":"B2","useRole":"O","example":"She stayed for a few minutes out of politeness."},{"form":"impolite","pos":"adj.","band":"B2","useRole":"O","example":"It seemed impolite to interrupt."}],"example":"You can disagree politely, whereas interrupting feels impolite even if someone stays out of politeness.","note":"Use \"politely\" productively (B1); \"impolite\" is more formal than \"rude\" (optional B2 recognition)."},{"base":"rely","forms":["reliable","unreliable","reliably"],"formDetails":[{"form":"reliable","pos":"adj.","band":"B1","useRole":"P","example":"We need a reliable bus service."},{"form":"unreliable","pos":"adj.","band":"B2","useRole":"B","example":"The old service was unreliable."},{"form":"reliably","pos":"adv.","band":"B2","useRole":"O","example":"The buses now run reliably, even at busy times."}],"example":"The old service was unreliable, so we need a reliable bus service that runs reliably.","note":"\"Rely on\" is recycled from Core; use \"reliable\" (B1) and \"unreliable\" (guided B2)."}],"optionalExtensions":[{"phrase":"pop round","pos":"v. + particle","band":"B2","useRole":"O","example":"Can I pop round after work?","note":"Informal British English; suggests a brief, casual visit. Recognition only (prefer \"come over\" for core use)."}],"linkingExpressions":[{"expression":"on the other hand","functionLabel":"Contrast","band":"B1","useRole":"P","example":"Living with friends can be fun. On the other hand, you have to share the housework."},{"expression":"in fact","functionLabel":"Emphasis","band":"B1","useRole":"P","example":"We get on really well. In fact, we talk almost every day."},{"expression":"apart from that","functionLabel":"Exception","band":"B1","useRole":"P","example":"The bus was late. Apart from that, the day went well.","note":"Shows what single detail is being treated as an exception."}]}},{"number":4,"phase":"Month 1: Strengthen B1 foundations","title":"Travel and cultural experiences","summary":"Describe a current local practice and a historical fact about a place using present and past passive where it fits.","hours":4,"releaseStage":"live","vocabularyTopic":"Travel, transport & cultural experiences","lightGrammar":"Defining relative clauses for places (B2 stretch)","grammar":[{"key":"passive-voice-visitor-guide","role":"main","name":"Present & past passive (visitor guide)","explanation":"Use be + past participle in the present and past simple to focus on the place, event, or result; add by + agent only if the agent matters. Contrast \"is held\" (current practice) with \"was built\" (past fact), and keep \"It happened\" active.","keyPoints":["Present passive for current practices: \"The food market is held there every Saturday.\"","Past passive for historical facts: \"The market hall was built in 1890.\"","Practise irregular participles: built, held, given, made, served.","Keep active verbs natural where the focus is an event happening: \"It happened last autumn\" (never passive)."],"example":"Start at the market hall. It was built in 1890, and the food market is held there every Saturday.","items":[{"prompt":"Guide to current events: \"The craft market ___ in the main square every Sunday.\"","options":["is held","was held","is hold"],"answer":"is held","explanation":"A regular current event uses the present simple passive (“is” + irregular past participle “held”).","difficulty":1},{"prompt":"Visitor leaflet: \"Fresh local honey and sourdough bread ___ at the harbour stalls every morning.\"","options":["are sold","were sold","are sell"],"answer":"are sold","explanation":"Current everyday practices take the present passive (“are sold”).","difficulty":1},{"prompt":"Guide card (Market hall / build / 1890): \"The historic market hall ___ in 1890.\"","options":["was built","is built","was build"],"answer":"was built","explanation":"A historical fact in 1890 takes the past simple passive (“was built”).","difficulty":1},{"prompt":"Festival note: \"Last year, every first-time visitor ___ a free map at the station entrance.\"","options":["was given","is given","was gave"],"answer":"was given","explanation":"Past simple passive requires “was/were” + past participle (“given”, not “gave”).","difficulty":2},{"prompt":"Choose the most natural wording in a travel note.","options":["A street parade happened outside the castle yesterday afternoon.","A street parade was happened outside the castle yesterday afternoon.","A street parade is happened outside the castle every May."],"answer":"A street parade happened outside the castle yesterday afternoon.","explanation":"Keep “happen” active — it never takes a passive form.","difficulty":2}]},{"key":"defining-relative-clauses-stretch","role":"light","name":"Defining relative clauses for places (B2 stretch)","explanation":"Use a defining relative clause without commas to identify which place you mean (\"It’s the square where the market is held\"). Non-defining clauses come later, and comparatives/superlatives live in the Grammar Clinic.","keyPoints":["Identify a place clearly: \"It’s the square where the craft market is held.\"","Identify a building or object: \"The bakery that opened in 1920 still uses the original oven.\""],"example":"It’s the square where the market is held, right next to the bridge that was built in 1890.","items":[{"prompt":"It’s the cobbled square ___ the food market is held every Saturday.","options":["where","which","who"],"answer":"where","explanation":"Use “where” to refer to a place where an action happens (“in the square”).","difficulty":1},{"prompt":"The old stone bridge ___ connects the two neighbourhoods was restored last spring.","options":["that","where","who"],"answer":"that","explanation":"When the bridge is the subject of “connects”, use “that” or “which” (not “where”).","difficulty":2},{"prompt":"The local guide ___ showed us around the harbour grew up two streets away.","options":["who","which","where"],"answer":"who","explanation":"Use “who” (or “that”) for a person.","difficulty":1}]}],"vocab":[{"term":"tradition","pos":"noun","band":"B2","useRole":"B","definition":"a custom, belief, or way of doing things passed down over a long time","example":"Visitors are invited to take part in a local tradition.","collocations":["take part in a local tradition","a long-standing tradition"],"wordFamily":["tradition","traditional","traditionally"],"note":"Guided B2 target. Related \"traditional\" (B1) and \"traditionally\" (B2) appear in Word Families.","gapFill":{"prompt":"During the harvest festival, visitors are invited to take part in a ___ local tradition.","options":["long-standing","standing-long","newly-old"],"answer":"long-standing","explanation":"\"A long-standing tradition\" is a natural collocation for something practised for generations."},"sentencePrompt":"Write a sentence describing a local tradition (using passive voice where natural).","translation":"tradición","audioRef":"week-4/tradition.mp3"},{"term":"custom","pos":"noun","band":"B1","useRole":"P","definition":"an accepted way of behaving or doing something in a particular society","example":"The guide explained a local custom: visitors are asked to take off their shoes before they go inside.","collocations":["a local custom","follow a custom"],"wordFamily":["custom"],"note":"Different from \"customs\" at an airport or border.","gapFill":{"prompt":"The guide explained a polite local ___: guests are asked to remove their shoes before they go inside.","options":["custom","ticket","border"],"answer":"custom","explanation":"Singular \"a custom\" is a social habit; plural \"customs\" at an airport checks luggage."},"sentencePrompt":"Write a sentence explaining a polite local custom visitors should know.","translation":"costumbre","audioRef":"week-4/custom.mp3"},{"term":"destination","pos":"noun","band":"B1","useRole":"P","definition":"the town, city, or country that someone is travelling to","example":"The brochure describes the island as a popular holiday destination.","collocations":["a popular holiday destination","reach your destination"],"wordFamily":["destination"],"note":"The final place you are travelling to.","gapFill":{"prompt":"The travel brochure describes the coastal island as a popular holiday ___.","options":["destination","direction","departure"],"answer":"destination","explanation":"Your \"destination\" is the place you travel to."},"sentencePrompt":"Write a sentence about a holiday destination you would recommend.","translation":"destino","audioRef":"week-4/destination.mp3"},{"term":"set off","pos":"phrasal verb","band":"B2","useRole":"B","definition":"start a journey, especially early in the day","example":"We set off early because we had been warned about heavy traffic.","collocations":["set off early","set off on a journey"],"wordFamily":["set off"],"note":"Guided B2 target meaning start a journey (distinct from \"get around\").","gapFill":{"prompt":"We ___ early in the morning because we had been warned about heavy holiday traffic.","options":["set off","took off","turned off"],"answer":"set off","explanation":"\"Set off\" means begin a journey (\"take off\" is only for aircraft leaving the ground)."},"sentencePrompt":"Write a sentence about a trip where you had to set off early.","translation":"ponerse en marcha / salir de viaje","audioRef":"week-4/set-off.mp3"},{"term":"get around","pos":"phrasal verb","band":"B1","useRole":"P","definition":"travel from place to place within a city, area, or region","example":"We were given a map to help us get around the city.","collocations":["get around the city","easy to get around"],"wordFamily":["get around"],"note":"Used for movement within an area, not avoidance.","ukUsNote":"Audio note: British speakers sometimes also say \"get about\" with the same meaning.","gapFill":{"prompt":"At the tourist office, we were given a clear tram map to help us ___ the city.","options":["get around","get away","get over"],"answer":"get around","explanation":"\"Get around\" means move from place to place within an area or city."},"sentencePrompt":"Write a sentence explaining the easiest way to get around your town or city.","translation":"desplazarse / moverse por","audioRef":"week-4/get-around.mp3"},{"term":"unfamiliar","pos":"adjective","band":"B2","useRole":"B","definition":"not known to you; strange or new because you have not experienced it before","example":"We were unfamiliar with the ticket system.","collocations":["unfamiliar with + noun","an unfamiliar place"],"wordFamily":["unfamiliar"],"note":"Guided B2 target: a person is unfamiliar WITH something; a place is unfamiliar TO someone.","gapFill":{"prompt":"Because we were ___ with the local ticket system, a station attendant helped us.","options":["unfamiliar","unwelcoming","unknown"],"answer":"unfamiliar","explanation":"A person is \"unfamiliar with\" a system or rule."},"sentencePrompt":"Write a sentence about dealing with an unfamiliar system or place while travelling.","translation":"desconocido / poco familiar","audioRef":"week-4/unfamiliar.mp3"},{"term":"welcoming","pos":"adjective","band":"B2","useRole":"B","definition":"friendly and making visitors feel happy and comfortable","example":"The friendly staff made us feel welcome; the hotel had a welcoming atmosphere.","collocations":["a welcoming atmosphere","warm and welcoming"],"wordFamily":["welcoming"],"note":"Guided B2 target: keep in natural active sentences rather than forcing a passive.","gapFill":{"prompt":"The friendly staff made us feel at home; the guesthouse had a genuinely ___ atmosphere.","options":["welcoming","welcome","welcomed"],"answer":"welcoming","explanation":"Use \"welcoming\" as an adjective before nouns such as \"atmosphere\", \"host\", or \"village\"."},"sentencePrompt":"Write a sentence describing a welcoming place or host you met on a trip.","translation":"acogedor","audioRef":"week-4/welcoming.mp3"},{"term":"local","pos":"adjective","band":"B1","useRole":"P","definition":"belonging to or coming from the particular area or neighbourhood you are in","example":"Local food is served in the hotel restaurant.","collocations":["local food","local people"],"wordFamily":["local"],"note":"B1 productive target meaning \"from the area\" (distinct from disapproving \"touristy\").","gapFill":{"prompt":"Fresh ___ food sourced from nearby farms is served in the village inn every evening.","options":["local","touristy","foreign"],"answer":"local","explanation":"\"Local\" means coming from the surrounding area."},"sentencePrompt":"Write a sentence about local food, markets, or traditions where you live or travelled.","translation":"local / de la zona","audioRef":"week-4/local.mp3"}],"inputs":[{"kind":"listening","lesson":3,"title":"Travel podcast: the case for slow travel","source":"Studio original — travel podcast","accent":"Australian","seconds":120,"body":"People often ask me how many countries I have been to, and I have started saying that I have no idea, because the number tells you nothing. I spent three weeks in one town in Portugal last spring. I learned the baker's name. I was invited to a birthday party. That would never have happened if I had been moving every two days. Slow travel is not about seeing less; it is about being seen, and remembered, as a guest rather than a customer. Later in the episode, Elena compared two coastal towns she visited last autumn. In the first resort, dozens of identical souvenir shops had been built along the seafront, making the harbour far noisier than it used to be. In the second village, local guesthouses were run by families who cooked regional dishes and limited coach groups to small numbers. Staying four nights in one place, she argued, felt far more rewarding than rushing through four cities in four days.","questions":[{"prompt":"Why does the speaker reject the country count?","options":["It says nothing about the experience","She has forgotten the number","It is too difficult to count"],"answer":"It says nothing about the experience"},{"prompt":"What did she do last spring?","options":["Visited ten countries","Stayed three weeks in one town","Moved every two days"],"answer":"Stayed three weeks in one town"}],"speaker_accents":[{"speaker":"PRESENTER","accent":"en-AU","label":"Australian"}],"audioRef":"module-3/travel-podcast-the-case-for-slow-travel.mp3","audioStatus":"actor_pending"},{"kind":"reading","lesson":4,"title":"When tourism becomes too much","source":"Studio original","body":"Venice is not alone. From Barcelona to Kyoto, cities that were built for residents are now shaped by visitors. Short-let flats have pushed rents up, and the bakery that survived for sixty years has been replaced by a shop selling souvenirs made elsewhere. Some cities have responded with visitor taxes, caps on cruise ships or bans on new short-term lets. None of these measures is popular with everyone. Yet the question behind them is simple: is a city a place to live, or a place to be seen? Most residents would answer both, and they would add that the balance has tipped. Residents in several historic centres say the real challenge is balancing hospitality with everyday life. When bakeries and hardware stores are replaced by short-term rentals, neighbourhoods lose the people who keep traditions alive. Yet solutions are possible when cities act early. Timed entry tickets, quieter pedestrian zones, and clear guidance on local customs help visitors feel welcome while protecting fragile streets. Travel works best when guests treat a destination as someone else’s home rather than a backdrop for photos.","questions":[{"prompt":"What is the article mainly about?","options":["The effects of mass tourism on cities","The best time to visit Venice","How to book cheap accommodation"],"answer":"The effects of mass tourism on cities"},{"prompt":"Which measure is mentioned?","options":["Caps on cruise ships","Free entry to museums","Closing all bakeries"],"answer":"Caps on cruise ships"}],"audioRef":"module-3/when-tourism-becomes-too-much.mp3","audioStatus":"tts"}],"speaking":[{"kind":"prompt_card","title":"Give a short visitor guide (45–60s)","prompt":"Record a 45–60 second guide for a first-time visitor. Include a regular event or custom, one fact about the past, and a recommendation. Don’t require a set number of passives. Listen to the model first, then hide it before recording.","seconds":55,"phrases":["If you visit this town, start at...","It was built in...","The ... is held there every..."],"linkers":["To begin with","Afterwards"],"terms":["local","custom","destination","tradition","set off"],"modelAnswer":"If you visit this town, start at the market hall. It was built in 1890, and the food market is held there every Saturday. It’s a local tradition, and you can try food from nearby farms. I’d set off early if you want to see the market at its busiest.\n\nAfterwards, take a walk by the river. It’s a quiet spot and my favourite part of town.","b2Stretch":"Add a defining relative clause if it helps identify something: \"It’s the square where the market is held.\" Leave non-defining clauses for later."}],"writing":{"title":"Short visitor recommendation or trip note","prompt":"Write a short visitor recommendation or trip note (120–150 words). Separate a factual detail about the place (what normally takes place there and one fact about its past) from what you personally did when you visited.","format":"short visitor recommendation","wordMin":120,"wordMax":150,"outline":{"analyze":"Purpose: inform and persuade. Audience: curious travellers. Register: semi-formal.","plan":"Vivid opening → what makes the place special → the pressure → one suggestion → closing line.","draft":"Use at least three passives and one non-defining relative clause.","improve":"Replace general adjectives with concrete details; add a concession.","review":"Check that every passive has a clear reason for being passive."}},"lessons":[{"dayOfWeek":"Mon","requirement":"optional","outputRequired":false,"minutes":15,"title":"Vocabulary: Travel and cultural experiences","objective":"Learn 8–10 core B1→B2 expressions for travel and cultural experiences, focusing on collocations and word families.","canDo":"I can use core travel and cultural experiences collocations accurately in short personal examples.","skill":"vocabulary","input":"reading","outputTitle":"Use 4 new travel and cultural experiences collocations","output":"Write or record 4 short sentences using this week's target collocations about travel and cultural experiences.","targetSeconds":90,"wordRange":[60,100]},{"dayOfWeek":"Tue","requirement":"optional","outputRequired":false,"minutes":15,"title":"Grammar: Present & past passive in visitor guides","objective":"Practise be + past participle in present and past simple to describe current local practices and historical facts.","canDo":"I can describe a current local practice and a past fact about a place using the passive where it fits.","skill":"grammar","input":"reading","outputTitle":"Say & refine one visitor-guide sentence","output":"Say (or type) one sentence about a place using present passive (e.g. is held) or past passive (e.g. was built). Check feedback and try it once more.","targetSeconds":45,"wordRange":[60,100]},{"dayOfWeek":"Wed","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Listening: Travel podcast: the case for slow travel","objective":"Listen for main ideas, speaker attitude, and detail in a multi-accent track on travel and cultural experiences.","canDo":"I can follow a 2-minute discussion about travel and cultural experiences and summarise key points.","skill":"listening","input":"listening","outputTitle":"Summarise what you heard","output":"Record or write a concise 2–3 sentence summary of the speaker's main point.","targetSeconds":90,"wordRange":[60,100]},{"dayOfWeek":"Thu","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Reading: When tourism becomes too much","objective":"Read a B1→B2 text on travel and cultural experiences, tracking argument structure and implicit detail.","canDo":"I can identify the author's main claim and supporting evidence in an article on travel and cultural experiences.","skill":"reading","input":"reading","outputTitle":"Respond to the text","output":"State whether you agree with the article's main conclusion and give one supporting reason.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Fri","requirement":"required","outputRequired":true,"minutes":15,"title":"Speaking (Required): Give a short visitor guide (45–60s)","objective":"Complete the required 90-second speaking task and self-check prosody in the Shadowing Lab.","canDo":"I can record a 45–60 second visitor guide with a regular event, one past fact, and a recommendation.","skill":"speaking","input":"listening","outputTitle":"Recorded visitor guide (45–60s)","output":"Listen to the model guide, hide it before recording, then record your 45–60 second recommendation.","targetSeconds":55,"wordRange":[80,130]},{"dayOfWeek":"Sat","requirement":"required","outputRequired":true,"minutes":30,"title":"Writing (Required): Short visitor recommendation or trip note","objective":"Plan, draft, and revise a 120–150 word text on travel and cultural experiences.","canDo":"I can write a well-structured 120–150 word response incorporating Passive voice.","skill":"writing","input":"reading","outputTitle":"Short visitor recommendation or trip note","output":"Write a 120–150 word visitor recommendation or trip note separating place facts from what you personally did.","targetSeconds":90,"wordRange":[120,150]},{"dayOfWeek":"Sun","requirement":"optional","outputRequired":false,"minutes":15,"title":"Review: Week 4 cards & error log","objective":"Consolidate Week 4 vocabulary via spaced repetition and rewrite your week's recurring error patterns.","canDo":"I can recall this week's target vocabulary and self-correct my top grammar or collocation slips.","skill":"review","input":"reading","outputTitle":"Error-log self-correction","output":"Delayed recall (try without a phrase bank first): \"Introduce a venue in your neighbourhood. Say what normally takes place there and give one fact about its past.\" Also review this week’s SRS cards.","targetSeconds":60,"wordRange":[40,80],"delayedRecallPrompt":"Introduce a venue in your neighbourhood. Say what normally takes place there and give one fact about its past."}],"vocabPack":{"collocations":[{"phrase":"take a guided tour","band":"B1","useRole":"P","example":"We took a guided tour of the old town.","note":"Also natural in passive descriptions: \"Visitors are taken on a guided tour.\""},{"phrase":"try the local food","band":"B1","useRole":"P","example":"We were encouraged to try the local food.","note":"Clear, everyday B1 collocation."},{"phrase":"travel light","band":"B2","useRole":"B","example":"We travelled light because there wasn't much room for luggage.","note":"Guided B2 collocation meaning packing only minimal luggage."},{"phrase":"stop overnight","band":"B1","useRole":"P","example":"We stopped overnight in York before driving on.","note":"Core B1 phrase for breaking a long journey with an overnight stay (see optional \"break your journey\")."},{"phrase":"miss a connection","band":"B2","useRole":"B","example":"Our flight was delayed, so we missed our connection.","note":"Guided B2 collocation for trains, coaches, or flights."}],"wordFamilies":[{"base":"culture","forms":["culture","cultural","culturally"],"formDetails":[{"form":"culture","pos":"n.","band":"B1","useRole":"P","example":"The exhibition introduced us to local culture."},{"form":"cultural","pos":"adj.","band":"B1","useRole":"P","example":"The museum organises cultural events."},{"form":"culturally","pos":"adv.","band":"B2","useRole":"O","example":"The two regions are culturally different."}],"example":"The museum organises cultural events introducing visitors to local culture across culturally distinct regions.","note":"Use \"culture\" and \"cultural\" productively (B1); \"culturally\" is optional B2 recognition."},{"base":"tradition","forms":["traditional","traditionally"],"formDetails":[{"form":"traditional","pos":"adj.","band":"B1","useRole":"P","example":"Traditional dishes are served here."},{"form":"traditionally","pos":"adv.","band":"B2","useRole":"B","example":"The festival is traditionally held in spring."}],"example":"Traditional dishes are served at the festival, which is traditionally held in spring.","note":"\"Tradition\" is taught in Core; \"traditional\" is B1 productive and \"traditionally\" is guided B2."},{"base":"tourism","forms":["tourism","touristy"],"formDetails":[{"form":"tourism","pos":"n.","band":"B1","useRole":"P","example":"Tourism provides jobs for local people."},{"form":"touristy","pos":"adj.","band":"B2","useRole":"O","example":"The town centre felt quite touristy."}],"example":"Tourism provides jobs for local people, even when parts of the town centre feel quite touristy.","note":"\"Touristy\" is informal and often disapproving — not simply \"popular with visitors\"."}],"optionalExtensions":[{"phrase":"break your journey","pos":"v. phr.","band":"B2","useRole":"O","example":"We broke our journey with an overnight stay in York.","note":"Natural, mainly British English expression (can also mean a brief rest stop). Optional recognition alongside core \"stop overnight\"."}],"linkingExpressions":[{"expression":"to begin with","functionLabel":"Sequence","band":"B1","useRole":"P","example":"To begin with, we were shown around the old town.","note":"Use for the first event in a sequence (B1), rather than the first reason in an argument (B2)."},{"expression":"what's more","functionLabel":"Addition","band":"B2","useRole":"B","example":"The hotel was comfortable. What's more, breakfast was included.","note":"\"What is more\" is grammatical; \"what's more\" is the main natural model here."},{"expression":"despite","functionLabel":"Concession","band":"B1","useRole":"P","example":"Despite the rain, the outdoor tour went ahead.","note":"Follow \"despite\" with a noun or an -ing form (never a full clause without \"the fact that\")."},{"expression":"all in all","functionLabel":"Summary","band":"B2","useRole":"B","example":"All in all, we had an excellent trip."}]}}]} $json$::jsonb) as imported_weeks_1_2_3_4;

select public.import_modules($json$ {"course_slug":"english-b1-b2","modules":[{"number":5,"phase":"Month 2: Move toward B2","title":"Technology and digital life","summary":"Speculate about digital evidence with modals of deduction and report statements cleanly with accurate backshift.","hours":4,"releaseStage":"live","vocabularyTopic":"Algorithms, privacy and digital habits","lightGrammar":"Reported statements (backshift)","grammar":[{"key":"modals-of-deduction","name":"Modals of deduction: must, might, could, can't","explanation":"Use must when you are almost certain, might or could when something is possible, and can't when you are almost certain it is untrue.","keyPoints":["Certain: The update must have broken the app.","Possible: She might be working from home.","Impossible: That can't be the reason they cancelled."],"example":"The site is down, so they must be updating the servers; it could also be a network problem.","items":[{"prompt":"The site is down. They ___ be updating the servers.","options":["can't","must","might not"],"answer":"must","explanation":"Must expresses strong certainty based on evidence.","difficulty":1},{"prompt":"That ___ be the reason — the app works fine on other phones.","options":["must","can't","should"],"answer":"can't","explanation":"Can't marks a conclusion you are almost certain is wrong.","difficulty":2},{"prompt":"Which sentence leaves the possibility open?","options":["It must be a bug.","It could be a bug.","It can't be a bug."],"answer":"It could be a bug.","explanation":"Could expresses possibility without certainty.","difficulty":1}],"role":"main"},{"key":"reported-speech","name":"Reported statements (backshift)","explanation":"When you report speech, shift the tense back one step and adjust pronouns and time expressions; reporting verbs such as claim, admit and warn change the pattern that follows.","keyPoints":["'I will fix it tomorrow.' → She said she would fix it the next day.","Reporting verb + -ing: He admitted breaking the rules.","Reporting verb + to: They warned us not to share the link."],"example":"The engineer said the update would take two days, admitted that the testing had been rushed, and warned us not to reinstall.","items":[{"prompt":"'I will fix it tomorrow.' → She said she ___ it the next day.","options":["will fix","would fix","fixes"],"answer":"would fix","explanation":"Will shifts to would in reported speech.","difficulty":1},{"prompt":"He admitted ___ the rules.","options":["to break","breaking","break"],"answer":"breaking","explanation":"Admit takes the -ing form.","difficulty":2},{"prompt":"They warned us ___ the link.","options":["not to share","to not share","no sharing"],"answer":"not to share","explanation":"Warn + object + (not) to + infinitive.","difficulty":2}],"role":"light"}],"vocab":[{"term":"algorithm","pos":"noun","definition":"a set of rules a computer follows to choose content","example":"The algorithm shows you what keeps you watching.","collocations":["the recommendation algorithm"],"wordFamily":["algorithm"],"translation":"algoritmo","band":"B2","audioRef":"week-5/algorithm.mp3"},{"term":"screen time","pos":"noun","definition":"time spent looking at a device","example":"My screen time doubled last month.","collocations":["limit screen time"],"wordFamily":["screen time"],"translation":"tiempo de pantalla","band":"B2","audioRef":"week-5/screen-time.mp3"},{"term":"data privacy","pos":"noun","definition":"control over who can see your personal information","example":"Data privacy is the main concern for users.","collocations":["protect data privacy"],"wordFamily":["data privacy"],"translation":"privacidad de datos","band":"B2","audioRef":"week-5/data-privacy.mp3"},{"term":"misinformation","pos":"noun","definition":"false information spread without intent to deceive","example":"Misinformation travels faster than corrections.","collocations":["spread misinformation"],"wordFamily":["misinformation"],"translation":"desinformación","band":"B2","audioRef":"week-5/misinformation.mp3"},{"term":"deepfake","pos":"noun","definition":"a video or audio clip generated to look real but false","example":"The deepfake of the mayor was shared thousands of times.","collocations":["a convincing deepfake"],"wordFamily":["deepfake"],"translation":"ultrafalso","band":"B2","audioRef":"week-5/deepfake.mp3"},{"term":"go viral","pos":"phrase","definition":"spread rapidly online","example":"The clip went viral within hours.","collocations":["go viral overnight"],"wordFamily":["go viral"],"translation":"hacerse viral","band":"B2","audioRef":"week-5/go-viral.mp3"},{"term":"clickbait","pos":"noun","definition":"a headline that exaggerates to attract clicks","example":"That headline is pure clickbait.","collocations":["clickbait headlines"],"wordFamily":["clickbait"],"translation":"cebo de clics","band":"B2","audioRef":"week-5/clickbait.mp3"},{"term":"filter bubble","pos":"noun","definition":"a situation where you only see views like your own","example":"Social feeds can create a filter bubble.","collocations":["live in a filter bubble"],"wordFamily":["filter bubble"],"translation":"burbuja de filtros","band":"B2","audioRef":"week-5/filter-bubble.mp3"},{"term":"digital footprint","pos":"noun","definition":"the trace your online activity leaves","example":"Employers sometimes check your digital footprint.","collocations":["leave a digital footprint"],"wordFamily":["digital footprint"],"translation":"huella digital","band":"B2","audioRef":"week-5/digital-footprint.mp3"}],"inputs":[{"kind":"listening","lesson":3,"title":"Tech news: the week in AI","source":"Studio original — news bulletin","accent":"American","seconds":150,"body":"A major video platform has announced that AI-generated clips must now be labelled. The company said the change would take effect within thirty days and admitted that earlier labelling had been inconsistent. Researchers welcomed the move but warned that labels alone will not stop misinformation, because most people share a clip before they read the caption. One campaign group claimed the policy was 'too little, too late', while the platform insisted that it was a first step. A listener asked whether schools should ban smartphones during lessons or teach students how algorithms sort newsfeeds. Both presenters agreed that banning devices alone cannot solve misinformation. One researcher said that teenagers who learnt how clickbait headlines are tested felt far less manipulated online. Before sharing a dramatic clip, they advised listeners to check who first posted it and ask whether a genuine photographer could have missed obvious details.","questions":[{"prompt":"What is the new policy?","options":["AI clips must be labelled","AI clips are banned","All clips must be shorter"],"answer":"AI clips must be labelled"},{"prompt":"What do researchers warn?","options":["Labels are not enough on their own","The policy is too strict","Nobody will notice"],"answer":"Labels are not enough on their own"}],"speaker_accents":[{"speaker":"ANCHOR","accent":"en-US","label":"American"}],"audioRef":"module-4/tech-news-the-week-in-ai.mp3","audioStatus":"actor_pending"},{"kind":"reading","lesson":4,"title":"The price of a free app","source":"Studio original","body":"Nothing on your phone is free. When an app costs nothing to install, the cost is usually paid in attention or data. A typical free app requests access to location, contacts and microphone, and many users accept without reading the prompt. Regulators have begun to push back: several countries now require plain-language summaries of what an app collects. Yet the strongest protection remains unglamorous. Turn off permissions you do not use. Read the prompt. And remember that a service designed to keep you scrolling is not designed to help you leave. Many users only notice how much data they share when an oddly specific advert appears seconds after a private search. Browser extensions and stricter permission settings can limit passive tracking, yet convenience often wins. Experts point out that reading a two-minute privacy summary before installing a new tool is one of the simplest ways to protect your digital footprint. Free software is rarely truly free; understanding the trade-off lets you decide which platforms actually deserve space on your home screen. When communities demand clearer consent screens, companies have to redesign defaults rather than hiding key controls behind five sub-menus. Beyond personal privacy settings, digital literacy also depends on slowing down emotional reactions. Platforms earn attention when users react instantly to outrage, confusion, or surprise. Taking ten seconds to check whether a startling claim includes an original link, a clear date, and a named source drastically lowers the chance of passing along misinformation. At home and at work, establishing simple boundaries—such as leaving phones out of the bedroom or checking group chats at fixed times—restores deep concentration. Technology serves daily life best when tools wait quietly until we deliberately open them, rather than pulling us into endless scrolling.","questions":[{"prompt":"What is the writer's main claim?","options":["Free apps are paid for with attention or data","Free apps are always unsafe","Paid apps are always better"],"answer":"Free apps are paid for with attention or data"},{"prompt":"What protection does the writer call strongest?","options":["New regulations","Your own habits and permissions","Deleting all apps"],"answer":"Your own habits and permissions"}],"audioRef":"module-4/the-price-of-a-free-app.mp3","audioStatus":"tts"}],"speaking":[{"kind":"prompt_card","title":"Digital habits & online evidence (2 min)","prompt":"Speak for 2 minutes about how algorithms or smartphones shape daily attention. Speculate about why people fall for clickbait (modals of deduction) and mention one habit you changed.","seconds":120,"phrases":["The way I see it...","There is no doubt that...","That said..."],"linkers":["moreover","on the other hand","as a result"],"terms":["filter bubble","misinformation","screen time"]}],"writing":{"title":"Review: an app, film or product","prompt":"Write a 150–180 word review of an app, film or product for a general audience. Describe it, weigh its strengths and weaknesses, and give a clear recommendation.","format":"review","wordMin":150,"wordMax":180,"outline":{"analyze":"Purpose: evaluate and recommend. Audience: potential users or viewers. Register: semi-formal.","plan":"Hook → description → two strengths → one weakness → recommendation.","draft":"Use one modal of deduction and two reported-speech structures.","improve":"Replace vague praise with evidence; vary sentence length.","review":"Check that the recommendation matches the evidence you gave."}},"lessons":[{"dayOfWeek":"Mon","requirement":"optional","outputRequired":false,"minutes":15,"title":"Vocabulary: Technology and digital life","objective":"Learn 8–10 core B1→B2 expressions for technology and digital life, focusing on collocations and word families.","canDo":"I can use core technology and digital life collocations accurately in short personal examples.","skill":"vocabulary","input":"reading","outputTitle":"Use 4 new technology and digital life collocations","output":"Write or record 4 short sentences using this week's target collocations about technology and digital life.","targetSeconds":90,"wordRange":[60,100]},{"dayOfWeek":"Tue","requirement":"optional","outputRequired":false,"minutes":15,"title":"Grammar: Modals of deduction","objective":"Master Modals of deduction + Reported statements (backshift) through guided contrast examples and instant-feedback drills.","canDo":"I can apply Modals of deduction accurately when discussing technology and digital life.","skill":"grammar","input":"reading","outputTitle":"Apply Modals of deduction","output":"Produce 3 original sentences demonstrating Modals of deduction and Reported statements (backshift).","targetSeconds":90,"wordRange":[60,100]},{"dayOfWeek":"Wed","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Listening: Tech news: the week in AI","objective":"Listen for main ideas, speaker attitude, and detail in a multi-accent track on technology and digital life.","canDo":"I can follow a 2.5-minute discussion about technology and digital life and summarise key points.","skill":"listening","input":"listening","outputTitle":"Summarise what you heard","output":"Record or write a concise 2–3 sentence summary of the speaker's main point.","targetSeconds":90,"wordRange":[60,100]},{"dayOfWeek":"Thu","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Reading: The price of a free app","objective":"Read a B1→B2 text on technology and digital life, tracking argument structure and implicit detail.","canDo":"I can identify the author's main claim and supporting evidence in an article on technology and digital life.","skill":"reading","input":"reading","outputTitle":"Respond to the text","output":"State whether you agree with the article's main conclusion and give one supporting reason.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Fri","requirement":"required","outputRequired":true,"minutes":15,"title":"Speaking (Required): Technology and digital life","objective":"Complete the required 120-second speaking task and self-check prosody in the Shadowing Lab.","canDo":"I can speak coherently for 2 minutes on technology and digital life using Modals of deduction.","skill":"speaking","input":"listening","outputTitle":"Recorded speaking task (120s)","output":"Speak for 2 minutes on digital habits and online reliability using modals of deduction.","targetSeconds":120,"wordRange":[80,130]},{"dayOfWeek":"Sat","requirement":"required","outputRequired":true,"minutes":30,"title":"Writing (Required): Review: an app, film or product","objective":"Plan, draft, and revise a 150–180 word text on technology and digital life.","canDo":"I can write a well-structured 150–180 word response incorporating Modals of deduction.","skill":"writing","input":"reading","outputTitle":"Review: an app, film or product","output":"Write a 180-word review of an app, film or product for a general audience. Describe it, weigh its strengths and weaknesses, and give a clear recommendation.","targetSeconds":120,"wordRange":[150,180]},{"dayOfWeek":"Sun","requirement":"optional","outputRequired":false,"minutes":15,"title":"Review: Week 5 cards & error log","objective":"Consolidate Week 5 vocabulary via spaced repetition and rewrite your week's recurring error patterns.","canDo":"I can recall this week's target vocabulary and self-correct my top grammar or collocation slips.","skill":"review","input":"reading","outputTitle":"Error-log self-correction","output":"Review this week's SRS deck and rewrite one corrected sentence from your mistake log.","targetSeconds":60,"wordRange":[40,80]}],"vocabPack":{"collocations":[{"phrase":"protect data privacy","band":"B2","useRole":"B","example":"Users expect messaging apps to protect data privacy by default."},{"phrase":"spread misinformation","band":"B2","useRole":"B","example":"Sensational headlines often spread misinformation faster than corrections."},{"phrase":"limit screen time","band":"B2","useRole":"B","example":"Setting an evening curfew helped me limit screen time during the week."},{"phrase":"leave a digital footprint","band":"B2","useRole":"B","example":"Every public comment and photo can leave a lasting digital footprint."},{"phrase":"go viral overnight","band":"B2","useRole":"B","example":"Short clips can go viral overnight without anyone checking the original source."},{"phrase":"live in a filter bubble","band":"B2","useRole":"B","example":"If you never read opposing views, you can end up living in a filter bubble."}],"wordFamilies":[{"base":"private","forms":["privacy","privately"],"example":"Strong data privacy rules let people communicate privately online."},{"base":"inform","forms":["information","misinformation","misinform"],"example":"False claims can misinform readers and turn reliable information into misinformation."}],"linkingExpressions":[{"expression":"judging by","functionLabel":"Deduction","band":"B2","useRole":"B","example":"Judging by the phrasing, the message must have been automated."},{"expression":"on the surface","functionLabel":"Contrast","band":"B2","useRole":"B","example":"On the surface, the app looks free, yet it collects extensive usage data."}]}},{"number":6,"phase":"Month 2: Move toward B2","title":"Work and education","summary":"Choose accurately between gerunds and infinitives after key verbs and report workplace requests and instructions.","hours":4,"releaseStage":"live","vocabularyTopic":"Careers, training, feedback and collaboration","lightGrammar":"Reported requests and commands","grammar":[{"key":"gerunds-and-infinitives","role":"main","name":"Gerunds and infinitives","explanation":"Distinguish verbs followed by -ing (avoid, consider, suggest, enjoy), verbs followed by to-infinitive (manage, afford, decide, refuse), and verbs whose meaning shifts (remember/stop/try).","keyPoints":["Verbs like suggest, recommend, avoid, and risk take -ing, never a to-infinitive.","Stop + -ing means quit an activity; stop + to-infinitive means pause in order to do something else.","Remember + -ing looks back at a memory; remember + to-infinitive reminds you of a duty."],"example":"She suggested rehearsing the presentation twice before remembering to back up her slides.","items":[{"prompt":"Our mentor suggested ___ the workshop notes into three clear actions.","options":["to summarise","summarising","summarise"],"answer":"summarising","explanation":"\"Suggest\" is followed by -ing (or a that-clause), not a to-infinitive.","difficulty":1},{"prompt":"I stopped ___ emails after eight o’clock so I could sleep properly.","options":["checking","to check","checked"],"answer":"checking","explanation":"Stop + -ing means giving up or ending the action.","difficulty":2},{"prompt":"Did you remember ___ the application form before the noon deadline?","options":["submitting","to submit","submit"],"answer":"to submit","explanation":"Remember + to-infinitive refers to not forgetting a task.","difficulty":1}]},{"key":"reported-requests-commands","role":"light","name":"Reported requests and commands","explanation":"Report instructions, advice, and requests cleanly using tell / ask / remind / advise + object + (not) to-infinitive.","keyPoints":["Use ask + object + to-infinitive for polite requests: She asked us to send the draft early.","Use tell / instruct + object + not to-infinitive for negative rules.","Never use \"say\" directly with object + to-infinitive."],"example":"The coordinator asked us not to interrupt during the client demo and reminded everyone to mute notifications.","items":[{"prompt":"The line manager ___ me to double-check the budget figures.","options":["said","asked","suggested"],"answer":"asked","explanation":"Ask + object + to-infinitive reports a request; \"said me to\" is incorrect.","difficulty":1},{"prompt":"Our tutor told us ___ memorise whole essays word for word.","options":["to not","not to","don’t"],"answer":"not to","explanation":"Negative reported commands place \"not\" before \"to\".","difficulty":1},{"prompt":"The HR adviser reminded new graduates ___ relevant examples in interviews.","options":["prepare","preparing","to prepare"],"answer":"to prepare","explanation":"Remind takes object + to-infinitive.","difficulty":1}]}],"vocab":[{"term":"apprenticeship","pos":"noun","definition":"a paid training programme combining practical workplace experience with formal study","example":"An engineering apprenticeship gave him hands-on experience without university debt.","collocations":["complete an apprenticeship","digital apprenticeship"],"wordFamily":["apprentice"],"translation":"contrato de formación / aprendizaje","band":"B2","audioRef":"week-6/apprenticeship.mp3"},{"term":"delegate","pos":"verb","definition":"give a task or responsibility to another team member","example":"Learning to delegate routine checks freed her up for strategic planning.","collocations":["delegate tasks","delegate responsibility"],"wordFamily":["delegation"],"translation":"delegar","band":"B2","audioRef":"week-6/delegate.mp3"},{"term":"constructive feedback","pos":"noun phrase","definition":"useful comments aimed at helping someone improve rather than merely criticising","example":"Good managers give constructive feedback as soon as a draft is ready.","collocations":["offer constructive feedback","welcome constructive feedback"],"wordFamily":["construct","constructively"],"translation":"retroalimentación constructiva","band":"B2","audioRef":"week-6/constructive-feedback.mp3"},{"term":"transferable skills","pos":"noun phrase","definition":"abilities such as clear writing or problem-solving that are useful across different jobs","example":"Teaching helped her build transferable skills in public speaking and planning.","collocations":["develop transferable skills","highlight transferable skills"],"wordFamily":["transfer"],"translation":"habilidades transferibles","band":"B2","audioRef":"week-6/transferable-skills.mp3"},{"term":"meet a deadline","pos":"verb phrase","definition":"finish a piece of work by the agreed time or date","example":"Splitting big projects into weekly targets makes it easier to meet a deadline.","collocations":["struggle to meet a deadline","comfortably meet a deadline"],"wordFamily":["deadline"],"translation":"cumplir un plazo","band":"B1","audioRef":"week-6/meet-a-deadline.mp3"},{"term":"catch up on","pos":"phrasal verb","definition":"do work or reading you missed earlier so you reach the current stage","example":"After three days off, he spent Monday morning catching up on emails.","collocations":["catch up on reading","catch up on work"],"wordFamily":["catch-up"],"translation":"ponerse al día con","band":"B1","audioRef":"week-6/catch-up-on.mp3"},{"term":"collaborative","pos":"adjective","definition":"involving two or more people working together toward a shared goal","example":"Weekly design critiques create a collaborative atmosphere across departments.","collocations":["collaborative environment","collaborative project"],"wordFamily":["collaborate","collaboration"],"translation":"colaborativo","band":"B2","audioRef":"week-6/collaborative.mp3"},{"term":"mentor","pos":"noun","definition":"an experienced colleague or teacher who guides someone less experienced","example":"Having a supportive mentor made my first term at college far less daunting.","collocations":["an experienced mentor","act as a mentor"],"wordFamily":["mentoring","mentorship"],"translation":"mentor / tutor","band":"B2","audioRef":"week-6/mentor.mp3"},{"term":"hand in","pos":"phrasal verb","definition":"submit homework, a report, or a form to a teacher or supervisor","example":"Students are expected to hand in their lab summaries by Friday at five.","collocations":["hand in an assignment","hand in on time"],"wordFamily":["hand-in"],"translation":"entregar","band":"B1","audioRef":"week-6/hand-in.mp3"}],"inputs":[{"kind":"listening","lesson":3,"title":"First-year mentoring at work and university","source":"Fluency Studio Careers Roundtable","accent":"Scottish & British English","speaker_accents":[{"speaker":"Callum","accent":"en-GB","label":"Scottish English"},{"speaker":"Maya","accent":"en-GB","label":"British English"}],"seconds":150,"audioRef":"week-6/mentoring-roundtable.mp3","audioStatus":"tts","body":"Callum: In today’s workplace brief, we are looking at why so many graduates struggle during their first six months in a new role. Maya, you run a mentoring scheme for young technicians. What surprised you most when you started? Maya: Honestly, it was not a lack of technical knowledge. Most apprentices already knew the software. What stressed them out was guessing unwritten expectations. Nobody had ever told them not to spend four hours polishing a routine update, or suggested asking for feedback halfway through a task instead of waiting until Friday. Callum: So clear communication saved time on both sides? Maya: Completely. We started pairing every newcomer with a senior mentor who meets them for twenty minutes each Wednesday. Mentors remind new staff to prioritise urgent jobs, delegate shared admin, and ask questions early. Within one term, fewer people missed deadlines and confidence jumped noticeably.","questions":[{"prompt":"What caused the most stress for new technicians in Maya’s scheme?","options":["Difficulty learning basic software","Guessing unwritten expectations about how to work","Long commutes to the office"],"answer":"Guessing unwritten expectations about how to work"},{"prompt":"What change helped reduce missed deadlines within one term?","options":["Short weekly check-ins with an experienced mentor","Removing all Friday deadlines","Banning internal emails"],"answer":"Short weekly check-ins with an experienced mentor"}]},{"kind":"reading","lesson":4,"title":"Beyond exam grades: what employers and tutors value","source":"Fluency Studio Education Brief","audioRef":"week-6/beyond-exam-grades.mp3","audioStatus":"tts","body":"For decades, university prospectuses and job adverts treated formal grades as the quickest way to compare applicants. While exam scores still show whether someone can absorb demanding material under pressure, hiring managers increasingly look for evidence of how candidates work once a project becomes messy. A recent survey of training coordinators across Britain found that three habits repeatedly set strong candidates apart: asking precise questions early, accepting constructive feedback without becoming defensive, and explaining complex choices clearly to non-specialists. None of these skills requires a specific degree subject. Students build them through part-time work, community volunteering, apprenticeships, and group seminars where deadlines actually matter. One coordinator noted that applicants who avoid admitting mistakes often slow an entire team down, whereas people who flag problems early help everyone adjust before a deadline slips. Practical reflection—asking what worked, what failed, and what to change next week—turns everyday study into genuine professional readiness. Interviews and probation reviews increasingly reflect this shift toward practical problem-solving. Rather than asking candidates to recite textbook definitions, hiring panels frequently present a realistic short scenario: a client has changed priorities two days before a deadline, or a teammate has fallen behind on shared data. Strong applicants explain who they would consult first, what tasks they would delegate or pause, and how they would confirm expectations in writing. At the same time, continuing to read widely and practising formal writing ensures that practical experience rests on clear communication. Combining hands-on adaptability with reflective study prepares learners for both university seminars and collaborative workplaces.","questions":[{"prompt":"Which habit did training coordinators warn slows teams down?","options":["Working part-time alongside university study","Avoiding admitting mistakes early","Asking questions during seminars"],"answer":"Avoiding admitting mistakes early"},{"prompt":"How does the article suggest students build transferable skills?","options":["Through real projects, teamwork, and practical reflection","By avoiding group assignments altogether","By choosing only theoretical exam subjects"],"answer":"Through real projects, teamwork, and practical reflection"}]}],"speaking":[{"kind":"monologue","title":"Useful feedback at work or study (2 min)","prompt":"Speak for 2 minutes about a useful piece of advice or constructive feedback a teacher, mentor, or manager gave you. Explain what they asked you to do, what you tried changing, and what happened next.","seconds":120,"phrases":["My mentor suggested trying…","She reminded me not to…","Since then, I have managed to…"],"linkers":["in addition","as a result","even though"],"terms":["constructive feedback","mentor","meet a deadline","transferable skills"]}],"writing":{"title":"Opinion piece: practical training vs. academic study","prompt":"Write 150–180 words discussing whether schools and universities should put more emphasis on practical projects and apprenticeships alongside traditional exams.","format":"opinion essay","wordMin":150,"wordMax":180,"outline":{"analyze":"Take a clear position while acknowledging why exams still exist.","plan":"Introduction -> practical/apprenticeship benefits -> role of academic grounding -> conclusion.","draft":"Use at least three gerund/infinitive patterns accurately.","improve":"Replace repetitive \"work\" or \"study\" with collocations like transferable skills.","review":"Check 150–180 words and verb patterns after suggest, avoid, and decide."}},"lessons":[{"dayOfWeek":"Mon","requirement":"optional","outputRequired":false,"minutes":15,"title":"Vocabulary: Work and education","objective":"Learn 8–10 core B1→B2 expressions for work and education, focusing on collocations and word families.","canDo":"I can use core work and education collocations accurately in short personal examples.","skill":"vocabulary","input":"reading","outputTitle":"Use 4 new work and education collocations","output":"Write or record 4 short sentences using this week's target collocations about work and education.","targetSeconds":90,"wordRange":[60,100]},{"dayOfWeek":"Tue","requirement":"optional","outputRequired":false,"minutes":15,"title":"Grammar: Gerunds and infinitives","objective":"Master Gerunds and infinitives + Reported requests and commands through guided contrast examples and instant-feedback drills.","canDo":"I can apply Gerunds and infinitives accurately when discussing work and education.","skill":"grammar","input":"reading","outputTitle":"Apply Gerunds and infinitives","output":"Produce 3 original sentences demonstrating Gerunds and infinitives and Reported requests and commands.","targetSeconds":90,"wordRange":[60,100]},{"dayOfWeek":"Wed","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Listening: First-year mentoring at work and university","objective":"Listen for main ideas, speaker attitude, and detail in a multi-accent track on work and education.","canDo":"I can follow a 2.5-minute discussion about work and education and summarise key points.","skill":"listening","input":"listening","outputTitle":"Summarise what you heard","output":"Record or write a concise 2–3 sentence summary of the speaker's main point.","targetSeconds":90,"wordRange":[60,100]},{"dayOfWeek":"Thu","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Reading: Beyond exam grades: what employers and tutors value","objective":"Read a B1→B2 text on work and education, tracking argument structure and implicit detail.","canDo":"I can identify the author's main claim and supporting evidence in an article on work and education.","skill":"reading","input":"reading","outputTitle":"Respond to the text","output":"State whether you agree with the article's main conclusion and give one supporting reason.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Fri","requirement":"required","outputRequired":true,"minutes":15,"title":"Speaking (Required): Work and education","objective":"Complete the required 120-second speaking task and self-check prosody in the Shadowing Lab.","canDo":"I can speak coherently for 2 minutes on work and education using Gerunds and infinitives.","skill":"speaking","input":"listening","outputTitle":"Recorded speaking task (120s)","output":"Speak for 2 minutes about helpful mentor feedback using gerunds, infinitives, and reported requests.","targetSeconds":120,"wordRange":[80,130]},{"dayOfWeek":"Sat","requirement":"required","outputRequired":true,"minutes":30,"title":"Writing (Required): Opinion piece: practical training vs. academic study","objective":"Plan, draft, and revise a 150–180 word text on work and education.","canDo":"I can write a well-structured 150–180 word response incorporating Gerunds and infinitives.","skill":"writing","input":"reading","outputTitle":"Opinion piece: practical training vs. academic study","output":"Write 150–180 words weighing practical apprenticeships against academic exams.","targetSeconds":120,"wordRange":[150,180]},{"dayOfWeek":"Sun","requirement":"optional","outputRequired":false,"minutes":15,"title":"Review: Week 6 cards & error log","objective":"Consolidate Week 6 vocabulary via spaced repetition and rewrite your week's recurring error patterns.","canDo":"I can recall this week's target vocabulary and self-correct my top grammar or collocation slips.","skill":"review","input":"reading","outputTitle":"Error-log self-correction","output":"Review this week's SRS deck and rewrite one corrected sentence from your mistake log.","targetSeconds":60,"wordRange":[40,80]}],"vocabPack":{"collocations":[{"phrase":"complete an apprenticeship","band":"B2","useRole":"B","example":"She chose to complete an apprenticeship in electrical engineering after college."},{"phrase":"offer constructive feedback","band":"B2","useRole":"B","example":"Good mentors offer constructive feedback rather than vague praise."},{"phrase":"develop transferable skills","band":"B2","useRole":"B","example":"Part-time retail roles still help graduates develop transferable skills."},{"phrase":"meet a deadline","band":"B1","useRole":"P","example":"Breaking large projects into weekly tasks helps teams meet a deadline."},{"phrase":"delegate responsibility","band":"B2","useRole":"B","example":"Experienced managers learn to delegate responsibility without losing oversight."},{"phrase":"hand in an assignment","band":"B1","useRole":"P","example":"Remember to hand in the written assignment before five on Friday."}],"wordFamilies":[{"base":"collaborate","forms":["collaborative","collaboration"],"example":"Effective collaboration thrives in a genuinely collaborative workplace."},{"base":"construct","forms":["constructive","constructively"],"example":"Offering feedback constructively turns criticism into constructive support."}],"linkingExpressions":[{"expression":"as a result","functionLabel":"Result","band":"B1","useRole":"P","example":"He acted on his mentor’s advice; as a result, his presentations improved."},{"expression":"whereas","functionLabel":"Contrast","band":"B2","useRole":"B","example":"Academic courses prioritise theory, whereas apprenticeships build hands-on skill."}]}},{"number":7,"phase":"Month 2: Move toward B2","title":"Media, news and influence","summary":"Summarise press claims precisely with B2 reporting verbs (admit, deny, suggest, insist) and turn direct interview questions into reported questions.","hours":4,"releaseStage":"live","vocabularyTopic":"Newsrooms, sources, bias and viral stories","lightGrammar":"Reported questions","grammar":[{"key":"reporting-verbs","role":"main","name":"Reporting verbs (admit, deny, suggest, insist)","explanation":"Move beyond \"say\" and \"tell\" by matching each reporting verb to its grammatical pattern: verb + -ing (admit, deny, suggest), verb + on + -ing (insist), or verb + to-infinitive (promise, refuse).","keyPoints":["Admit, deny, and suggest take -ing (or a that-clause): The editor denied altering the quote.","Insist takes on + -ing or that + clause: She insisted on checking both sources.","Warn and persuade require an object before the to-infinitive."],"example":"The presenter denied exaggerating the figures and insisted on publishing the full dataset online.","items":[{"prompt":"The journalist admitted ___ an unverified headline too quickly.","options":["to share","sharing","share"],"answer":"sharing","explanation":"\"Admit\" takes -ing or a that-clause.","difficulty":1},{"prompt":"The spokesperson insisted ___ reading the complete transcript before commenting.","options":["on","to","for"],"answer":"on","explanation":"Insist pairs with the preposition \"on\" + -ing.","difficulty":2},{"prompt":"Several readers warned the site ___ confusing opinion columns with news reports.","options":["not","against","to not"],"answer":"against","explanation":"\"Warn someone against + -ing\" is a natural B2 structure.","difficulty":2}]},{"key":"reported-questions","role":"light","name":"Reported questions","explanation":"Report yes/no questions with if/whether and wh-questions with statement word order (no auxiliary do/did and no question mark).","keyPoints":["Use ask / wonder + if or whether for yes/no questions.","Keep subject before verb: She asked where the reporter had found the statistics.","Drop do/does/did and shift tenses back when the reporting verb is in the past."],"example":"The host asked the editor whether readers still trusted local radio and how the newsroom checked viral clips.","items":[{"prompt":"The interviewer asked the author why ___ the article.","options":["had she written","she had written","did she write"],"answer":"she had written","explanation":"Reported questions use statement word order (subject + verb).","difficulty":1},{"prompt":"Listeners asked ___ the podcast would release a follow-up episode.","options":["that","whether","what"],"answer":"whether","explanation":"Yes/no reported questions require \"if\" or \"whether\".","difficulty":1},{"prompt":"He wanted to know how long the verification process usually ___.","options":["took","did take","takes it"],"answer":"took","explanation":"Backshift present simple to past simple without \"did\".","difficulty":2}]}],"vocab":[{"term":"verify","pos":"verb","definition":"check carefully whether information or a source is accurate and true","example":"Reporters should verify every claim with at least two independent sources.","collocations":["verify a source","independently verify"],"wordFamily":["verification","verified"],"translation":"verificar","band":"B2","audioRef":"week-7/verify.mp3"},{"term":"headline","pos":"noun","definition":"the title of a news story printed in large letters","example":"Dramatic headlines often oversimplify complicated economic reports.","collocations":["grab headlines","misleading headline"],"wordFamily":["headline"],"translation":"titular","band":"B1","audioRef":"week-7/headline.mp3"},{"term":"biased","pos":"adjective","definition":"unfairly favouring one side or viewpoint over another","example":"Readers quickly lose trust when coverage feels obviously biased.","collocations":["heavily biased","politically biased"],"wordFamily":["bias","unbiased"],"translation":"sesgado","band":"B2","audioRef":"week-7/biased.mp3"},{"term":"eyewitness","pos":"noun","definition":"a person who saw an event happen in person and can describe it","example":"The broadcast included an interview with an eyewitness at the harbour.","collocations":["eyewitness account","reliable eyewitness"],"wordFamily":["witness"],"translation":"testigo ocular","band":"B2","audioRef":"week-7/eyewitness.mp3"},{"term":"sensationalise","pos":"verb","definition":"present a story as more shocking or dramatic than it really is","example":"Quality editors try not to sensationalise early medical studies.","collocations":["sensationalise a story","sensationalised reporting"],"wordFamily":["sensational","sensationalism"],"translation":"sensacionalizar","band":"B2","audioRef":"week-7/sensationalise.mp3"},{"term":"reliable source","pos":"noun phrase","definition":"a person, document, or organisation whose facts you can trust","example":"Always look for a reliable source before repeating dramatic figures.","collocations":["cite a reliable source","cross-check reliable sources"],"wordFamily":["rely","reliability"],"translation":"fuente fiable","band":"B1","audioRef":"week-7/reliable-source.mp3"},{"term":"retract","pos":"verb","definition":"officially withdraw a statement or article because it was wrong","example":"The magazine had to retract the claim after checking the public records.","collocations":["retract a statement","retract an article"],"wordFamily":["retraction"],"translation":"retractarse / retirar","band":"B2","audioRef":"week-7/retract.mp3"},{"term":"echo chamber","pos":"noun phrase","definition":"an online space where people only hear views that reinforce their own beliefs","example":"Following journalists with different perspectives helps you step out of an echo chamber.","collocations":["online echo chamber","escape an echo chamber"],"wordFamily":["echo"],"translation":"cámara de eco","band":"B2","audioRef":"week-7/echo-chamber.mp3"},{"term":"take with a pinch of salt","pos":"idiom","definition":"not completely believe something until you see stronger proof","example":"I always take anonymous product reviews with a pinch of salt.","collocations":["take claims with a pinch of salt"],"wordFamily":["salt"],"translation":"coger con pinzas","band":"B2","audioRef":"week-7/pinch-of-salt.mp3"}],"inputs":[{"kind":"listening","lesson":3,"title":"Inside a fact-checking desk","source":"Fluency Studio Media Podcast","accent":"British & Indian English","speaker_accents":[{"speaker":"Presenter","accent":"en-GB","label":"British English"},{"speaker":"Ananya","accent":"en-IN","label":"Indian English"}],"seconds":165,"audioRef":"week-7/fact-checking-desk.mp3","audioStatus":"tts","body":"Presenter: When a dramatic video goes viral before breakfast, how does a small fact-checking team decide what is genuine? Ananya, you spent three years leading an investigative desk in Mumbai before moving to London. What happens in the first twenty minutes? Ananya: First, we slow down. Last month, a clip claimed a historic bridge had collapsed overnight. Several websites repeated the rumour immediately, though one local council denied any damage had occurred. Our team asked whether any eyewitnesses had posted clear photographs with local street signs, and we checked weather logs from that morning. Presenter: Did the original account admit making a mistake? Ananya: Not at first—they insisted on keeping the post up for clicks, even after engineers confirmed the footage came from an old film set in another region. Eventually, the platform added a warning label and the blog retracted its headline. Listeners asked how ordinary readers can avoid getting caught out. My rule is simple: pause for sixty seconds, check who benefits from your anger, and see whether two independent newsrooms confirm the same details.","questions":[{"prompt":"How did Ananya’s team prove the bridge footage was misleading?","options":["They deleted the blog’s account immediately","They checked eyewitness street details, weather logs, and the footage origin","They waited three weeks for a TV broadcast"],"answer":"They checked eyewitness street details, weather logs, and the footage origin"},{"prompt":"What first step does Ananya recommend to ordinary readers?","options":["Pause briefly and see if two independent outlets confirm the claim","Never read local news online","Share posts quickly so friends can check them"],"answer":"Pause briefly and see if two independent outlets confirm the claim"}]},{"kind":"reading","lesson":4,"title":"Why slow journalism is finding an audience again","source":"Fluency Studio Media Review","audioRef":"week-7/slow-journalism.mp3","audioStatus":"tts","body":"For much of the past decade, digital newsrooms raced to publish breaking updates faster than their rivals. Breaking alerts certainly help during emergencies, yet speed-first reporting carries a clear cost: nuances disappear, early rumours get repeated before anyone can verify them, and readers end up exhausted rather than informed. In response, a growing number of weekly newsletters, audio documentaries, and independent magazines have turned toward what editors call slow journalism. Instead of chasing every trending headline, journalists spend weeks interviewing eyewitnesses, checking public budgets, and testing claims against original data. When mistakes occur, transparent outlets admit getting a detail wrong and publish visible corrections rather than quietly editing a paragraph online. Readers appear willing to pay modestly for calmer reporting that respects their time and avoids sensationalising routine disagreements. As one editor put it recently, audiences do not want twenty breathless updates an hour; they want one trustworthy explanation they can still rely on next month. Choosing two or three balanced sources—including outlets outside your usual echo chamber—helps transform passive scrolling into genuinely critical reading. Digital tools have also made it far easier for everyday readers to verify basic claims themselves before reacting. Checking when an image first appeared online, reading past the headline to the original report, and comparing two outlets with different editorial traditions take less than three minutes. Teachers and community libraries increasingly run short workshops showing teenagers and older adults how headlines frame identical statistics in opposite ways. When readers ask \"Who collected this sample?\" or \"What important context is missing?\", sensationalised posts lose much of their power. Informed habits on the audience side reward journalists who invest time in accurate, unhurried reporting.","questions":[{"prompt":"What downside of speed-first reporting does the article highlight?","options":["Audiences refuse to read breaking alerts during emergencies","Rumours spread before verification and nuances get lost","Print newspapers become too expensive to deliver"],"answer":"Rumours spread before verification and nuances get lost"},{"prompt":"How do transparent slow-journalism outlets handle errors?","options":["They quietly delete the entire article","They admit mistakes openly and publish visible corrections","They blame social media algorithms"],"answer":"They admit mistakes openly and publish visible corrections"}]}],"speaking":[{"kind":"prompt_card","title":"Evaluating a viral news story (2 min)","prompt":"Speak for 2 minutes about how you decide whether a surprising news story or social media claim is trustworthy. Report what someone once claimed or denied, and explain two steps you take to verify facts.","seconds":120,"phrases":["The headline claimed…","When I checked a reliable source…","I tend to take dramatic claims with a pinch of salt…"],"linkers":["for instance","whereas","consequently"],"terms":["verify","biased","reliable source","echo chamber"]}],"writing":{"title":"Review: a news podcast, magazine, or media app","prompt":"Write a 150–180 word review of a news podcast, magazine, or media platform you use. Summarise what it covers, explain how balanced its reporting is, and recommend who would benefit from it.","format":"balanced review","wordMin":150,"wordMax":180,"outline":{"analyze":"Balance description with clear evaluation criteria (accuracy, clarity, bias).","plan":"Introduction -> strengths -> one limitation -> clear recommendation.","draft":"Include at least one reporting verb (suggest, insist, admit) and varied linkers.","improve":"Swap vague adjectives (\"good\", \"interesting\") for precise terms (balanced, verify).","review":"Check 150–180 words and reported-question word order if used."}},"lessons":[{"dayOfWeek":"Mon","requirement":"optional","outputRequired":false,"minutes":15,"title":"Vocabulary: Media, news and influence","objective":"Learn 8–10 core B1→B2 expressions for media, news and influence, focusing on collocations and word families.","canDo":"I can use core media, news and influence collocations accurately in short personal examples.","skill":"vocabulary","input":"reading","outputTitle":"Use 4 new media, news and influence collocations","output":"Write or record 4 short sentences using this week's target collocations about media, news and influence.","targetSeconds":90,"wordRange":[60,100]},{"dayOfWeek":"Tue","requirement":"optional","outputRequired":false,"minutes":15,"title":"Grammar: Reporting verbs (admit, deny, suggest, insist)","objective":"Master Reporting verbs (admit, deny, suggest, insist) + Reported questions through guided contrast examples and instant-feedback drills.","canDo":"I can apply Reporting verbs (admit, deny, suggest, insist) accurately when discussing media, news and influence.","skill":"grammar","input":"reading","outputTitle":"Apply Reporting verbs (admit, deny, suggest, insist)","output":"Produce 3 original sentences demonstrating Reporting verbs (admit, deny, suggest, insist) and Reported questions.","targetSeconds":90,"wordRange":[60,100]},{"dayOfWeek":"Wed","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Listening: Inside a fact-checking desk","objective":"Listen for main ideas, speaker attitude, and detail in a multi-accent track on media, news and influence.","canDo":"I can follow a 2.5-minute discussion about media, news and influence and summarise key points.","skill":"listening","input":"listening","outputTitle":"Summarise what you heard","output":"Record or write a concise 2–3 sentence summary of the speaker's main point.","targetSeconds":90,"wordRange":[60,100]},{"dayOfWeek":"Thu","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Reading: Why slow journalism is finding an audience again","objective":"Read a B1→B2 text on media, news and influence, tracking argument structure and implicit detail.","canDo":"I can identify the author's main claim and supporting evidence in an article on media, news and influence.","skill":"reading","input":"reading","outputTitle":"Respond to the text","output":"State whether you agree with the article's main conclusion and give one supporting reason.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Fri","requirement":"required","outputRequired":true,"minutes":15,"title":"Speaking (Required): Media, news and influence","objective":"Complete the required 120-second speaking task and self-check prosody in the Shadowing Lab.","canDo":"I can speak coherently for 2 minutes on media, news and influence using Reporting verbs (admit, deny, suggest, insist).","skill":"speaking","input":"listening","outputTitle":"Recorded speaking task (120s)","output":"Speak for 2 minutes on checking news reliability using reporting verbs and reported questions.","targetSeconds":120,"wordRange":[80,130]},{"dayOfWeek":"Sat","requirement":"required","outputRequired":true,"minutes":30,"title":"Writing (Required): Review: a news podcast, magazine, or media app","objective":"Plan, draft, and revise a 150–180 word text on media, news and influence.","canDo":"I can write a well-structured 150–180 word response incorporating Reporting verbs (admit, deny, suggest, insist).","skill":"writing","input":"reading","outputTitle":"Review: a news podcast, magazine, or media app","output":"Write a 150–180 word balanced review of a media source or news podcast.","targetSeconds":120,"wordRange":[150,180]},{"dayOfWeek":"Sun","requirement":"optional","outputRequired":false,"minutes":15,"title":"Review: Week 7 cards & error log","objective":"Consolidate Week 7 vocabulary via spaced repetition and rewrite your week's recurring error patterns.","canDo":"I can recall this week's target vocabulary and self-correct my top grammar or collocation slips.","skill":"review","input":"reading","outputTitle":"Error-log self-correction","output":"Review this week's SRS deck and rewrite one corrected sentence from your mistake log.","targetSeconds":60,"wordRange":[40,80]}],"vocabPack":{"collocations":[{"phrase":"verify a source","band":"B2","useRole":"B","example":"Responsible editors always verify a source before repeating an extraordinary claim."},{"phrase":"cite a reliable source","band":"B1","useRole":"P","example":"Every front-page report ought to cite a reliable source."},{"phrase":"grab headlines","band":"B1","useRole":"P","example":"Dramatic statistics grab headlines even when the sample is tiny."},{"phrase":"retract a statement","band":"B2","useRole":"B","example":"The magazine had to retract a statement after an eyewitness contradicted it."},{"phrase":"sensationalise a story","band":"B2","useRole":"B","example":"Click-driven outlets often sensationalise a story for quick attention."},{"phrase":"take claims with a pinch of salt","band":"B2","useRole":"B","example":"Always take anonymous claims on social media with a pinch of salt."}],"wordFamilies":[{"base":"verify","forms":["verification","verified","unverified"],"example":"Independent verification separates verified facts from unverified rumours."},{"base":"bias","forms":["biased","unbiased"],"example":"Readers notice biased framing quickly when they compare it with unbiased reporting."}],"linkingExpressions":[{"expression":"according to","functionLabel":"Attribution","band":"B1","useRole":"P","example":"According to the regional survey, trust in local journalism is rising."},{"expression":"nevertheless","functionLabel":"Concession","band":"B2","useRole":"B","example":"The clip spread widely; nevertheless, reporters insisted on checking the date."}]}},{"number":8,"phase":"Month 2: Move toward B2","title":"Environment and sustainability","summary":"Reflect on past environmental choices with third and mixed conditionals, and express regrets or desired changes with wish / if only.","hours":4,"releaseStage":"live","vocabularyTopic":"Climate action, urban heat and sustainability","lightGrammar":"wish / if only","grammar":[{"key":"third-mixed-conditionals","name":"Conditionals 3 and mixed","explanation":"The third conditional imagines an unreal past; mixed conditionals connect an unreal past to a present result, or a present state to a past result.","keyPoints":["Third: If the city had invested earlier, the floods would not have been so severe.","Past → present: If I had studied planning, I would be working on this project now.","Present → past: If she were more patient, she would not have quit."],"example":"If the council had built the drainage in 2015, the damage would not be costing us millions now.","items":[{"prompt":"If the city had invested earlier, the floods ___ so severe.","options":["would not be","would not have been","will not be"],"answer":"would not have been","explanation":"Third conditional: had + past participle, would have + past participle.","difficulty":1},{"prompt":"If I had studied planning, I ___ on this project now.","options":["would work","would be working","had worked"],"answer":"would be working","explanation":"Mixed conditional: past cause with a present result.","difficulty":3},{"prompt":"Which sentence blames a past action for a present situation?","options":["If we had acted, the park would be open now.","If we act, the park will open.","If we were acting, the park would be open."],"answer":"If we had acted, the park would be open now.","explanation":"Past perfect in the if-clause plus present result is the mixed pattern.","difficulty":2}],"role":"main"},{"key":"wish-regret","name":"wish / if only","explanation":"Use wish or if only with the past simple for a present regret, with the past perfect for a past regret, and with would to complain about someone else's behaviour.","keyPoints":["Present regret: I wish I lived closer to work.","Past regret: I wish we had started ten years ago.","Complaint: I wish the council would collect the bins on time."],"example":"I wish the city had kept the old tram line; if only we could use it now.","items":[{"prompt":"I wish I ___ closer to work.","options":["live","lived","had lived"],"answer":"lived","explanation":"A present regret takes the past simple after wish.","difficulty":1},{"prompt":"I wish we ___ ten years ago.","options":["started","had started","would start"],"answer":"had started","explanation":"A past regret takes the past perfect after wish.","difficulty":2},{"prompt":"Which sentence complains about someone else's behaviour?","options":["I wish I had a bike.","I wish the council would fix the road.","If only I were taller."],"answer":"I wish the council would fix the road.","explanation":"Wish + would expresses irritation about another person's action.","difficulty":2}],"role":"light"}],"vocab":[{"term":"carbon footprint","pos":"noun","definition":"the amount of carbon dioxide your activity produces","example":"Flying less cut her carbon footprint in half.","collocations":["reduce your carbon footprint"],"wordFamily":["carbon footprint"],"translation":"huella de carbono","band":"B2","audioRef":"week-8/carbon-footprint.mp3"},{"term":"renewable energy","pos":"noun","definition":"energy from sources that do not run out","example":"The island runs entirely on renewable energy.","collocations":["invest in renewable energy"],"wordFamily":["renewable energy"],"translation":"energía renovable","band":"B2","audioRef":"week-8/renewable-energy.mp3"},{"term":"sustainable","pos":"adjective","definition":"able to continue without damaging resources","example":"We need a sustainable transport plan, not a short fix.","collocations":["a sustainable solution"],"wordFamily":["sustainable"],"translation":"sostenible","band":"B2","audioRef":"week-8/sustainable.mp3"},{"term":"urban sprawl","pos":"noun","definition":"the uncontrolled spread of a city into the countryside","example":"Urban sprawl has swallowed the farmland around the city.","collocations":["limit urban sprawl"],"wordFamily":["urban sprawl"],"translation":"expansión urbana","band":"B2","audioRef":"week-8/urban-sprawl.mp3"},{"term":"public transport network","pos":"noun","definition":"the system of buses, trains and trams people share","example":"The public transport network is cheap and reliable here.","collocations":["extend the public transport network"],"wordFamily":["public transport network"],"translation":"red de transporte público","band":"B2","audioRef":"week-8/public-transport-network.mp3"},{"term":"green space","pos":"noun","definition":"parks and other open natural areas in a city","example":"Every district should have green space within ten minutes.","collocations":["protect green space"],"wordFamily":["green space"],"translation":"zona verde","band":"B2","audioRef":"week-8/green-space.mp3"},{"term":"air quality","pos":"noun","definition":"how clean or polluted the air is","example":"Air quality improves when the schools close for summer.","collocations":["poor air quality"],"wordFamily":["air quality"],"translation":"calidad del aire","band":"B2","audioRef":"week-8/air-quality.mp3"},{"term":"recycling scheme","pos":"noun","definition":"an organised system for reusing waste","example":"The new recycling scheme covers food waste.","collocations":["introduce a recycling scheme"],"wordFamily":["recycling scheme"],"translation":"programa de reciclaje","band":"B2","audioRef":"week-8/recycling-scheme.mp3"},{"term":"climate target","pos":"noun","definition":"a goal for reducing emissions by a set date","example":"The city missed its climate target by two years.","collocations":["meet a climate target"],"wordFamily":["climate target"],"translation":"objetivo climático","band":"B2","audioRef":"week-8/climate-target.mp3"}],"inputs":[{"kind":"listening","lesson":3,"title":"Documentary excerpt: the city that cooled itself","source":"Studio original — documentary","accent":"British","seconds":165,"body":"In 2019 this square was a car park. Summer temperatures here were four degrees higher than in the park two streets away, an effect researchers call the urban heat island. The city tried something unfashionable: it planted trees, removed the asphalt and put a small fountain where the delivery vans used to park. Four years later, the temperature difference has almost disappeared. The scheme cost less than one kilometre of road. What surprised the engineers was not the cooling, but how quickly residents started using the space. Residents interviewed on the street said they wished earlier planners had protected older trees instead of paving over parks in the nineties. If those green corridors had survived, summer nights would be noticeably cooler right now. Even so, local volunteers remain practical: small shaded pocket parks and reliable trams prove that towns can adapt steadily when citizens and engineers plan together.","questions":[{"prompt":"What was the site before 2019?","options":["A park","A car park","A fountain"],"answer":"A car park"},{"prompt":"What surprised the engineers most?","options":["The cost","How quickly residents used the space","The temperature drop"],"answer":"How quickly residents used the space"}],"speaker_accents":[{"speaker":"NARRATOR","accent":"en-GB","label":"British"}],"audioRef":"module-5/documentary-excerpt-the-city-that-cooled-itself.mp3","audioStatus":"actor_pending"},{"kind":"reading","lesson":4,"title":"Problem, solution: the heat in our streets","source":"Studio original","body":"Cities are hotter than the countryside around them, and the difference is not evenly spread. Districts with fewer trees and more asphalt can be five degrees warmer than wealthier, greener neighbours, which means the people least able to afford air conditioning are the ones who need it most. The solutions are unglamorous and well understood: plant mature trees rather than saplings, replace dark surfaces with reflective ones, and open air-conditioned public buildings during heatwaves. The obstacle is rarely knowledge. It is the budget cycle, which rewards visible new projects over invisible maintenance. Look closely at how a few mid-sized cities turned summer complaints into lasting redesigns. Instead of waiting for expensive megaprojects, councils started by painting dark asphalt roofs pale white, planting native street trees outside bus shelters, and converting single car lanes into shaded cycle corridors. Within three summers, ground temperatures dropped and independent cafés reported higher afternoon footfall because people could actually sit outside comfortably. If local authorities had ignored those early pilot schemes, energy bills for air conditioning would now be climbing even faster. Every small adaptation teaches residents what a calmer, greener street feels like—turning abstract climate targets into everyday comfort. Just as importantly, community involvement ensures that green redesigns last beyond a single election cycle. When residents help decide where shaded benches, bike racks, and rainwater gardens go, neighbourhoods protect those spaces as shared assets rather than viewing them as imposed rules. Schoolchildren help water newly planted saplings along walking routes, while local shopkeepers notice calmer streets invite families to linger longer. Critics once worried that removing roadside parking spaces would reduce trade, yet surveys across several European towns showed retail footfall either held steady or rose once crossings felt safer and summer shade improved.","questions":[{"prompt":"Who suffers most from urban heat?","options":["The wealthiest districts","Districts with fewer trees and less money","People in the countryside"],"answer":"Districts with fewer trees and less money"},{"prompt":"What does the writer say is the real obstacle?","options":["Lack of knowledge","Budget priorities","Public opposition"],"answer":"Budget priorities"}],"audioRef":"module-5/problem-solution-the-heat-in-our-streets.mp3","audioStatus":"tts"}],"speaking":[{"kind":"prompt_card","title":"Local environmental change (2 min)","prompt":"Identify one environmental problem in your area and propose a realistic solution. Explain the cost, the benefit and the obstacle. Two minutes.","seconds":120,"phrases":["The problem in my area is...","One solution would be...","The main obstacle is..."],"linkers":["firstly","as a result","however"],"terms":["green space","air quality","take action"]}],"writing":{"title":"Problem-solution report: a local issue","prompt":"Write a 150–180 word report for a residents' association about one local environmental problem. Describe the problem, analyse two causes, propose two solutions and recommend one.","format":"problem-solution report","wordMin":150,"wordMax":180,"outline":{"analyze":"Purpose: inform and recommend. Audience: residents and local officials. Register: formal, impersonal.","plan":"Problem → causes → solutions → recommendation.","draft":"Use the passive, one third or mixed conditional, and linkers of cause and consequence.","improve":"Replace informal phrasing with impersonal constructions; add figures or comparisons.","review":"Check that each solution answers one of the causes you described."}},"lessons":[{"dayOfWeek":"Mon","requirement":"optional","outputRequired":false,"minutes":15,"title":"Vocabulary: Environment and sustainability","objective":"Learn 8–10 core B1→B2 expressions for environment and sustainability, focusing on collocations and word families.","canDo":"I can use core environment and sustainability collocations accurately in short personal examples.","skill":"vocabulary","input":"reading","outputTitle":"Use 4 new environment and sustainability collocations","output":"Write or record 4 short sentences using this week's target collocations about environment and sustainability.","targetSeconds":90,"wordRange":[60,100]},{"dayOfWeek":"Tue","requirement":"optional","outputRequired":false,"minutes":15,"title":"Grammar: Conditionals 3 and mixed","objective":"Master Conditionals 3 and mixed + wish / if only through guided contrast examples and instant-feedback drills.","canDo":"I can apply Conditionals 3 and mixed accurately when discussing environment and sustainability.","skill":"grammar","input":"reading","outputTitle":"Apply Conditionals 3 and mixed","output":"Produce 3 original sentences demonstrating Conditionals 3 and mixed and wish / if only.","targetSeconds":90,"wordRange":[60,100]},{"dayOfWeek":"Wed","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Listening: Documentary excerpt: the city that cooled itself","objective":"Listen for main ideas, speaker attitude, and detail in a multi-accent track on environment and sustainability.","canDo":"I can follow a 2.5-minute discussion about environment and sustainability and summarise key points.","skill":"listening","input":"listening","outputTitle":"Summarise what you heard","output":"Record or write a concise 2–3 sentence summary of the speaker's main point.","targetSeconds":90,"wordRange":[60,100]},{"dayOfWeek":"Thu","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Reading: Problem, solution: the heat in our streets","objective":"Read a B1→B2 text on environment and sustainability, tracking argument structure and implicit detail.","canDo":"I can identify the author's main claim and supporting evidence in an article on environment and sustainability.","skill":"reading","input":"reading","outputTitle":"Respond to the text","output":"State whether you agree with the article's main conclusion and give one supporting reason.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Fri","requirement":"required","outputRequired":true,"minutes":15,"title":"Speaking (Required): Environment and sustainability","objective":"Complete the required 120-second speaking task and self-check prosody in the Shadowing Lab.","canDo":"I can speak coherently for 2 minutes on environment and sustainability using Conditionals 3 and mixed.","skill":"speaking","input":"listening","outputTitle":"Recorded speaking task (120s)","output":"Speak for 2 minutes on an environmental problem and solution using third/mixed conditionals and wish.","targetSeconds":120,"wordRange":[80,130]},{"dayOfWeek":"Sat","requirement":"required","outputRequired":true,"minutes":30,"title":"Writing (Required): Problem-solution report: a local issue","objective":"Plan, draft, and revise a 150–180 word text on environment and sustainability.","canDo":"I can write a well-structured 150–180 word response incorporating Conditionals 3 and mixed.","skill":"writing","input":"reading","outputTitle":"Problem-solution report: a local issue","output":"Write a 180–200-word report for a residents' association about one local environmental problem. Describe the problem, analyse two causes, propose two solutions and recommend one.","targetSeconds":120,"wordRange":[150,180]},{"dayOfWeek":"Sun","requirement":"optional","outputRequired":false,"minutes":15,"title":"Review: Week 8 cards & error log","objective":"Consolidate Week 8 vocabulary via spaced repetition and rewrite your week's recurring error patterns.","canDo":"I can recall this week's target vocabulary and self-correct my top grammar or collocation slips.","skill":"review","input":"reading","outputTitle":"Error-log self-correction","output":"Review this week's SRS deck and rewrite one corrected sentence from your mistake log.","targetSeconds":60,"wordRange":[40,80]}],"vocabPack":{"collocations":[{"phrase":"reduce your carbon footprint","band":"B2","useRole":"B","example":"Replacing short flights with rail travel can significantly reduce your carbon footprint."},{"phrase":"invest in renewable energy","band":"B2","useRole":"B","example":"Several coastal towns decided to invest in renewable energy last decade."},{"phrase":"limit urban sprawl","band":"B2","useRole":"B","example":"Planners built around existing stations to limit urban sprawl."},{"phrase":"protect green space","band":"B2","useRole":"B","example":"Residents campaigned to protect green space near the canal."},{"phrase":"introduce a recycling scheme","band":"B2","useRole":"B","example":"The council could introduce a recycling scheme for small electronics."},{"phrase":"meet a climate target","band":"B2","useRole":"B","example":"If cities had acted earlier, more regions would meet a climate target on time."}],"wordFamilies":[{"base":"sustain","forms":["sustainable","sustainability","unsustainable"],"example":"True sustainability requires replacing unsustainable habits with sustainable transit."},{"base":"renew","forms":["renewable","non-renewable"],"example":"Shifting from non-renewable fuels to renewable power lowers emissions."}],"linkingExpressions":[{"expression":"if only","functionLabel":"Regret","band":"B2","useRole":"B","example":"If only planners had planted street trees twenty years ago."},{"expression":"provided that","functionLabel":"Condition","band":"B2","useRole":"B","example":"Cycle lanes work well, provided that junctions are properly protected."}]}}]} $json$::jsonb) as imported_weeks_5_6_7_8;

select public.import_modules($json$ {"course_slug":"english-b1-b2","modules":[{"number":9,"phase":"Month 3: Develop B2 communication","title":"Health and wellbeing","summary":"Distinguish arranged services with causative verbs (have/get something done) and present public health findings neutrally with passive reporting.","hours":4,"releaseStage":"live","vocabularyTopic":"Wellbeing, preventive care and daily habits","lightGrammar":"Passive reporting","grammar":[{"key":"causatives","name":"Causative verbs","explanation":"Use have or get something done when someone else performs a service for you, and have someone do something when you arrange it directly.","keyPoints":["Service: I had my blood pressure checked last week.","Arrangement: She got the pharmacy to deliver the prescription.","Trouble: He had his appendix removed on Monday."],"example":"I had my eyes tested on Friday and got the optician to adjust the lenses for free.","items":[{"prompt":"I ___ my blood pressure checked last week.","options":["checked","had","did checked"],"answer":"had","explanation":"Have + object + past participle shows a service performed by someone else.","difficulty":1},{"prompt":"Which sentence means someone else did the work?","options":["I repaired my bike.","I had my bike repaired.","I was repairing my bike."],"answer":"I had my bike repaired.","explanation":"The causative makes the agent of the action someone other than the subject.","difficulty":2},{"prompt":"She ___ the pharmacy to deliver the prescription.","options":["had","got","made"],"answer":"got","explanation":"Get + person + to + infinitive describes persuading or arranging.","difficulty":3}],"role":"main"},{"key":"passive-reporting","role":"light","name":"Passive reporting","explanation":"Report widely held beliefs or medical findings formally with \"It is believed/estimated that…\" or \"Subject + is thought to + infinitive\".","keyPoints":["Impersonal frame: It is widely recognised that poor sleep affects concentration.","Personal frame: Short afternoon walks are thought to reduce stress levels.","Use \"to have + past participle\" for an earlier event: Stress is thought to have contributed to the rise."],"example":"Regular walking is widely reported to lower blood pressure, so more patients are getting their check-ups booked early.","items":[{"prompt":"Adequate sleep ___ to improve memory consolidation overnight.","options":["is known","knows","is knowing"],"answer":"is known","explanation":"Passive reporting uses \"is known/thought/believed + to-infinitive\".","difficulty":1},{"prompt":"It is ___ estimated that sitting all day raises discomfort in the lower back.","options":["wide","widely","widen"],"answer":"widely","explanation":"Collocation: \"widely estimated / reported / recognised\".","difficulty":1},{"prompt":"Older residents ___ their prescriptions delivered directly by a local pharmacist.","options":["have","are knowing","report"],"answer":"have","explanation":"Causative \"have + object + past participle\" describes an arranged service.","difficulty":2}]}],"vocab":[{"term":"balanced diet","pos":"noun","definition":"a way of eating with the right variety of nutrients","example":"A balanced diet matters more than any single superfood.","collocations":["maintain a balanced diet"],"wordFamily":["balanced diet"],"translation":"dieta equilibrada","band":"B2","audioRef":"week-9/balanced-diet.mp3"},{"term":"sedentary lifestyle","pos":"noun","definition":"a way of living with very little physical activity","example":"A sedentary lifestyle raises the risk of heart disease.","collocations":["lead a sedentary lifestyle"],"wordFamily":["sedentary lifestyle"],"translation":"estilo de vida sedentario","band":"B2","audioRef":"week-9/sedentary-lifestyle.mp3"},{"term":"mental wellbeing","pos":"noun","definition":"the state of feeling psychologically healthy","example":"Sleep affects mental wellbeing more than most people realise.","collocations":["support mental wellbeing"],"wordFamily":["mental wellbeing"],"translation":"bienestar mental","band":"B2","audioRef":"week-9/mental-wellbeing.mp3"},{"term":"cut down on","pos":"phrasal verb","definition":"reduce the amount you consume","example":"I am cutting down on sugary drinks.","collocations":["cut down on sugar"],"wordFamily":["cut down on"],"translation":"reducir el consumo de","band":"B2","audioRef":"week-9/cut-down-on.mp3"},{"term":"addictive","pos":"adjective","definition":"difficult to stop doing or consuming","example":"Highly processed food is designed to be addictive.","collocations":["highly addictive"],"wordFamily":["addictive"],"translation":"adictivo","band":"B2","audioRef":"week-9/addictive.mp3"},{"term":"ethical","pos":"adjective","definition":"morally right or acceptable","example":"Is it ethical to advertise junk food to children?","collocations":["an ethical question"],"wordFamily":["ethical"],"translation":"ético","band":"B2","audioRef":"week-9/ethical.mp3"},{"term":"consumer choice","pos":"noun","definition":"the freedom to decide what to buy","example":"Taxes are meant to shape consumer choice, not punish it.","collocations":["restrict consumer choice"],"wordFamily":["consumer choice"],"translation":"elección del consumidor","band":"B2","audioRef":"week-9/consumer-choice.mp3"},{"term":"fair trade","pos":"noun","definition":"trade that pays producers a fair price","example":"The café only sells fair trade coffee.","collocations":["fair trade products"],"wordFamily":["fair trade"],"translation":"comercio justo","band":"B2","audioRef":"week-9/fair-trade.mp3"},{"term":"sugary drinks","pos":"noun","definition":"beverages with a high sugar content","example":"Several cities now tax sugary drinks.","collocations":["a tax on sugary drinks"],"wordFamily":["sugary drinks"],"translation":"bebidas azucaradas","band":"B2","audioRef":"week-9/sugary-drinks.mp3"}],"inputs":[{"kind":"listening","lesson":3,"title":"Panel discussion: whose responsibility is health?","source":"Studio original — panel discussion","accent":"British and South African","seconds":180,"body":"CHAIR: Whose responsibility is health? DR OSEI: I get uncomfortable when we talk only about individual choice, because choice is shaped. If the only shop within a kilometre sells processed food, that is not a free choice. DR LEWIS: I agree up to a point, but people do respond to information. Smoking fell for decades before any ban, largely because attitudes changed. CHAIR: So is taxation part of the answer? DR OSEI: It can be, provided the revenue goes back into prevention. Otherwise it just looks like a fine on being poor. Later in the programme, the physiotherapist explained why small workplace adjustments matter just as much as weekend exercise. Many desk workers never get their chair height or screen distance checked until neck pain sets in. It is increasingly recognised that short five-minute movement breaks every hour protect focus as well as posture. Meanwhile, the community nutritionist noted that people cut down on ultra-processed snacks much more easily when healthy lunches are affordable near schools and train stations.","questions":[{"prompt":"Why does Dr Osei distrust the 'individual choice' argument?","options":["Because choice is shaped by the environment","Because people are irresponsible","Because taxation never works"],"answer":"Because choice is shaped by the environment"},{"prompt":"What condition does Dr Osei set for taxation?","options":["Revenue must fund prevention","It must apply only to the rich","It must be temporary"],"answer":"Revenue must fund prevention"}],"speaker_accents":[{"speaker":"CHAIR","accent":"en-GB","label":"British"},{"speaker":"DR OSEI","accent":"en-ZA","label":"South African"},{"speaker":"DR LEWIS","accent":"en-GB","label":"British"}],"audioRef":"module-6/panel-discussion-whose-responsibility-is-health.mp3","audioStatus":"actor_pending"},{"kind":"reading","lesson":4,"title":"Should junk food be taxed? Two views","source":"Studio original — opinion page","body":"FOR: The case is straightforward. Sugar taxes reduce consumption, and consumption of sugar raises the risk of diseases that cost public health systems billions. A levy of ten per cent in one European country cut purchases of sugary drinks by eighteen per cent within a year, and the revenue funded free school meals. AGAINST: The case is equally straightforward. Such taxes are regressive: they take a larger share of income from poorer households, who also have less time to cook and fewer affordable alternatives. Education and better labelling would achieve more, and would not punish people for buying what is cheapest. Public health researchers also point out that labelling rules and local environment play a decisive role. When supermarkets place sugary drinks at eye level near every checkout, busy parents face constant nudges, whereas clear nutritional labelling makes healthier swaps straightforward. At the same time, critics warn that taxes alone rarely change habits unless revenue helps fund sports clubs, cycling routes, and affordable fresh produce in lower-income neighbourhoods. Ultimately, combining clear public information with practical neighbourhood support is widely thought to deliver steadier improvements than blame or strict bans. Employers and schools are also discovering that small structural nudges outperform dramatic wellness posters. Offering flexible walking meetings, keeping quiet break rooms free from work screens, and subsidising seasonal fruit bowls cost relatively little compared with high staff turnover. Even simple sleep hygiene workshops—encouraging people to dim bright screens an hour before bed and keep steady waking times—often improve afternoon focus more reliably than extra coffee. When healthier options become the easiest default on an ordinary Tuesday, citizens do not have to rely purely on willpower to protect long-term physical and mental wellbeing.","questions":[{"prompt":"What evidence supports the tax?","options":["An eighteen per cent drop in purchases","Higher employment","Lower food prices"],"answer":"An eighteen per cent drop in purchases"},{"prompt":"What is the main objection?","options":["The tax is regressive","The tax is too low","The tax is illegal"],"answer":"The tax is regressive"}],"audioRef":"module-6/should-junk-food-be-taxed-two-views.mp3","audioStatus":"tts"}],"speaking":[{"kind":"prompt_card","title":"Public health & personal habits (3 min)","prompt":"Argue either for or against a tax on junk food in a 3-minute response. Use two pieces of evidence, address the strongest objection and conclude.","seconds":180,"phrases":["The evidence suggests...","The strongest objection is...","On balance, I would argue..."],"linkers":["whereas","nevertheless","consequently"],"terms":["public health","consumer choice","regressive"]}],"writing":{"title":"Argument essay: health and responsibility","prompt":"Write a 180–200 word argument essay: should governments tax unhealthy products to improve public health? Present both sides and reach a clear conclusion.","format":"argument essay","wordMin":180,"wordMax":200,"outline":{"analyze":"Purpose: argue and conclude. Audience: an examiner or opinion page. Register: formal.","plan":"Introduction with position → argument for → argument against → evaluation → conclusion.","draft":"Use at least three advanced linkers and one causative structure.","improve":"Qualify your claims; replace absolutes with hedging where evidence is limited.","review":"Check that the conclusion follows from the evaluation, not from repetition."}},"lessons":[{"dayOfWeek":"Mon","requirement":"optional","outputRequired":false,"minutes":15,"title":"Vocabulary: Health and wellbeing","objective":"Learn 8–10 core B2 items for health and wellbeing, practising collocations and word families.","canDo":"I can deploy B2 health and wellbeing collocations accurately in context.","skill":"vocabulary","input":"reading","outputTitle":"Use 4 health and wellbeing expressions","output":"Write or record 4 nuanced sentences using this week's B2 collocations.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Tue","requirement":"optional","outputRequired":false,"minutes":15,"title":"Grammar: Causative verbs","objective":"Practise Causative verbs + Passive reporting with contrast rules and diagnostic drills.","canDo":"I can control Causative verbs cleanly in formal and semi-formal B2 expression.","skill":"grammar","input":"reading","outputTitle":"Apply Causative verbs","output":"Write or speak 3 complex sentences using Causative verbs and Passive reporting.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Wed","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Listening: Panel discussion: whose responsibility is health?","objective":"Follow a 3-minute multi-accent discussion on health and wellbeing, noting nuance and hedging.","canDo":"I can extract main arguments, concessions, and implied attitude from a 3-minute track.","skill":"listening","input":"listening","outputTitle":"Summarise the speaker's position","output":"Summarise the main viewpoint and one counter-argument from today's listening track.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Thu","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Reading: Should junk food be taxed? Two views","objective":"Analyse a 250–350 word B2 article on health and wellbeing for evidence, tone, and structure.","canDo":"I can evaluate evidence and distinguish fact from opinion in a 250–350 word text.","skill":"reading","input":"reading","outputTitle":"Critical reaction to the article","output":"Write or record a short reaction explaining which point in the article is strongest and why.","targetSeconds":90,"wordRange":[80,120]},{"dayOfWeek":"Fri","requirement":"required","outputRequired":true,"minutes":15,"title":"Speaking (Required): Health and wellbeing","objective":"Deliver a structured 3-minute speaking response on health and wellbeing, plus Shadowing self-check.","canDo":"I can sustain a structured 3-minute B2 response on health and wellbeing.","skill":"speaking","input":"listening","outputTitle":"Structured speaking task (180s)","output":"Speak for 3 minutes on health habits and public responsibility using causatives and passive reporting.","targetSeconds":180,"wordRange":[100,160]},{"dayOfWeek":"Sat","requirement":"required","outputRequired":true,"minutes":30,"title":"Writing (Required): Argument essay: health and responsibility","objective":"Plan, draft, and polish a 180–200 word B2 piece on health and wellbeing.","canDo":"I can produce a cohesive 180–200 word B2 text using Causative verbs.","skill":"writing","input":"reading","outputTitle":"Argument essay: health and responsibility","output":"Write a 200-word argument essay: should governments tax unhealthy products to improve public health? Present both sides and reach a clear conclusion.","targetSeconds":180,"wordRange":[180,200]},{"dayOfWeek":"Sun","requirement":"optional","outputRequired":false,"minutes":15,"title":"Review: Week 9 cards & error log","objective":"Consolidate Week 9 vocabulary cards and self-correct recurring mistakes before the next week.","canDo":"I can recall this week's B2 vocabulary and rewrite my recurring mistakes cleanly.","skill":"review","input":"reading","outputTitle":"Error-log rewrite","output":"Review due SRS cards and complete at least two error-log rewrite checks.","targetSeconds":60,"wordRange":[50,90]}],"vocabPack":{"collocations":[{"phrase":"maintain a balanced diet","band":"B2","useRole":"B","example":"Busy shift workers often struggle to maintain a balanced diet."},{"phrase":"lead a sedentary lifestyle","band":"B2","useRole":"B","example":"Desk jobs make it easy to lead a sedentary lifestyle without noticing."},{"phrase":"support mental wellbeing","band":"B2","useRole":"B","example":"Regular outdoor exercise helps support mental wellbeing as well as physical fitness."},{"phrase":"cut down on sugar","band":"B2","useRole":"B","example":"Clear labelling helps families cut down on sugar gradually."},{"phrase":"restrict consumer choice","band":"B2","useRole":"B","example":"Critics argue that bans restrict consumer choice unnecessarily."},{"phrase":"get a health check done","band":"B2","useRole":"B","example":"More adults are encouraged to get a routine health check done each year."}],"wordFamilies":[{"base":"addict","forms":["addictive","addiction"],"example":"Highly addictive snacks make sugar addiction harder to overcome."},{"base":"prevent","forms":["preventive","prevention"],"example":"Preventive care treats health promotion and prevention as long-term savings."}],"linkingExpressions":[{"expression":"it is widely believed that","functionLabel":"Passive reporting","band":"B2","useRole":"B","example":"It is widely believed that preventive care reduces hospital pressure."},{"expression":"by contrast","functionLabel":"Contrast","band":"B2","useRole":"B","example":"Taxes raise prices immediately; by contrast, education changes habits slowly."}]}},{"number":10,"phase":"Month 3: Develop B2 communication","title":"Cities, transport and society","summary":"Consolidate article and quantifier precision for abstract urban issues, and weigh policies accurately using varied comparative structures.","hours":4,"releaseStage":"live","vocabularyTopic":"Urban planning, transit and liveable neighbourhoods","lightGrammar":"Comparative structures","grammar":[{"key":"articles-quantifiers-consolidation","role":"main","name":"Articles and quantifiers (consolidation)","explanation":"Combine zero article for general uncountable concepts (traffic, pollution, housing) with \"the\" for specific urban policies and precise quantifiers (a great deal of, far fewer, hardly any).","keyPoints":["Use \"the + singular countable\" only for specific institutions or generic inventions (the underground, the bicycle).","Use far fewer / several with plural countables and far less / a considerable amount of with uncountables.","Remember that housing, transport, research, and congestion are uncountable."],"example":"Cities with reliable trams see far fewer traffic jams and spend a great deal less on road repairs.","items":[{"prompt":"Pedestrian zones produce ___ noise than multi-lane ring roads.","options":["far fewer","much less","a few"],"answer":"much less","explanation":"Noise is uncountable, so compare with \"much less\".","difficulty":1},{"prompt":"___ affordable housing remains one of the sharpest challenges in capital cities.","options":["The","An","No article"],"answer":"No article","explanation":"General uncountable noun phrases (\"affordable housing\") take zero article.","difficulty":2},{"prompt":"Only ___ residents objected once the cycle lane opened safely.","options":["a little","a few","much"],"answer":"a few","explanation":"\"Residents\" is plural countable, so use \"a few\".","difficulty":1}]},{"key":"comparative-structures","role":"light","name":"Comparative structures","explanation":"Move past basic -er/more with B2 modifiers (far more, marginally quieter, nowhere near as expensive as) and double comparatives (the more…, the less…).","keyPoints":["Gradable modifiers: considerably faster, slightly cheaper, nowhere near as reliable as.","Double comparatives show cause-and-effect: The more frequent the trains, the fewer cars enter the centre.","Use \"as… as\" to compare equality or shortfall cleanly."],"example":"The more reliable regional rail becomes, the less tempting it is to drive—and electric buses are nowhere near as noisy as older diesel fleets.","items":[{"prompt":"The wider the pavements are, ___ pleasant the high street feels.","options":["more","the more","most"],"answer":"the more","explanation":"Double comparative structure: \"The + comparative..., the + comparative...\".","difficulty":2},{"prompt":"Regional buses are ___ as punctual as express trains during rush hour.","options":["nowhere near","far less","slightly"],"answer":"nowhere near","explanation":"\"Nowhere near as + adjective + as\" emphasises a big gap.","difficulty":2},{"prompt":"Walking is ___ healthier and cheaper than sitting in traffic.","options":["much more","considerably","very"],"answer":"considerably","explanation":"\"Considerably\" modifies an existing comparative (\"healthier\"); avoid \"much more healthier\".","difficulty":2}]}],"vocab":[{"term":"commute","pos":"verb / noun","definition":"travel regularly between home and work or college","example":"A reliable light-rail line cut her morning commute from an hour to twenty-five minutes.","collocations":["daily commute","commute by train"],"wordFamily":["commuter","commuting"],"translation":"desplazarse al trabajo","band":"B1","audioRef":"week-10/commute.mp3"},{"term":"congestion","pos":"noun","definition":"the state of roads being crowded and slow because there is too much traffic","example":"Low-emission charges reduced peak congestion across the inner ring road.","collocations":["traffic congestion","ease congestion"],"wordFamily":["congested"],"translation":"congestión / atascos","band":"B2","audioRef":"week-10/congestion.mp3"},{"term":"infrastructure","pos":"noun","definition":"the basic physical systems a city needs, such as railways, water pipes, and bridges","example":"Investing in cycling infrastructure pays off quickly in healthier neighbourhoods.","collocations":["transport infrastructure","ageing infrastructure"],"wordFamily":["infrastructural"],"translation":"infraestructura","band":"B2","audioRef":"week-10/infrastructure.mp3"},{"term":"pedestrianise","pos":"verb","definition":"close a street to motor vehicles so people can walk safely","example":"When the town decided to pedestrianise Market Square, café terraces doubled.","collocations":["pedestrianised zone","pedestrianise the centre"],"wordFamily":["pedestrian","pedestrianisation"],"translation":"peatonalizar","band":"B2","audioRef":"week-10/pedestrianise.mp3"},{"term":"affordable housing","pos":"noun phrase","definition":"homes priced so people on ordinary or lower incomes can rent or buy them","example":"Without affordable housing near transit stops, essential workers face exhausting journeys.","collocations":["shortage of affordable housing","build affordable housing"],"wordFamily":["afford","affordability"],"translation":"vivienda asequible","band":"B2","audioRef":"week-10/affordable-housing.mp3"},{"term":"mixed-use","pos":"adjective","definition":"combining homes, shops, parks, and workplaces within the same neighbourhood","example":"Mixed-use streets stay lively in the evening without forcing residents to drive everywhere.","collocations":["mixed-use development","mixed-use neighbourhood"],"wordFamily":["mix"],"translation":"de uso mixto","band":"B2","audioRef":"week-10/mixed-use.mp3"},{"term":"accessibility","pos":"noun","definition":"how easily everyone, including wheelchair users and parents with prams, can reach a place","example":"Step-free lifts greatly improved station accessibility for older travellers.","collocations":["improve accessibility","step-free accessibility"],"wordFamily":["accessible","access"],"translation":"accesibilidad","band":"B2","audioRef":"week-10/accessibility.mp3"},{"term":"gentrification","pos":"noun","definition":"the process of renovating an area so wealthier residents move in and rents rise","example":"Long-term residents worried that rapid gentrification would price out family bakeries.","collocations":["rapid gentrification","resist gentrification"],"wordFamily":["gentrify"],"translation":"gentrificación","band":"B2","audioRef":"week-10/gentrification.mp3"},{"term":"peak hours","pos":"noun phrase","definition":"the busiest times of day when transport and roads carry the most passengers","example":"Buses run every four minutes during morning peak hours.","collocations":["during peak hours","avoid peak hours"],"wordFamily":["peak"],"translation":"horas punta","band":"B1","audioRef":"week-10/peak-hours.mp3"}],"inputs":[{"kind":"listening","lesson":3,"title":"The fifteen-minute neighbourhood: reality or slogan?","source":"Fluency Studio Urban Affairs Podcast","accent":"British & Canadian English","speaker_accents":[{"speaker":"Hannah","accent":"en-GB","label":"British English"},{"speaker":"Tariq","accent":"en-CA","label":"Canadian English"}],"seconds":180,"audioRef":"week-10/fifteen-minute-city.mp3","audioStatus":"tts","body":"Hannah: Almost every mayor talks about liveable cities now, yet commuters still spend hours stuck in traffic. Tariq, you study urban transport across mid-sized European and Canadian towns. Why do some neighbourhoods feel effortless to walk around while others feel exhausting? Tariq: Honestly, it comes down to two practical details: safe street crossings and mixed-use zoning. When a district has only office towers or only rows of houses, people have no choice except to drive or crowd onto trains during peak hours. By contrast, where bakeries, primary schools, clinics, and parks sit within a fifteen-minute walk, far fewer short car journeys are needed. Hannah: Critics sometimes complain that pedestrianising centres hurts small shops or pushes rents higher. Is there truth in that? Tariq: There can be if councils stop at cosmetic paving. The cities that succeed pair car-free streets with strict affordable housing quotas and fast step-free buses linking outer estates to the centre. The better outer districts are connected, the less pressure builds up on historic streets. Good transit is nowhere near as expensive as widening motorways—and it leaves far more room for trees and benches.","questions":[{"prompt":"According to Tariq, what two details make a neighbourhood easy to walk around?","options":["Larger car parks and wider motorways","Safe street crossings and mixed-use zoning","Taller office towers and night buses"],"answer":"Safe street crossings and mixed-use zoning"},{"prompt":"How do successful cities prevent pedestrianisation from hurting outer residents?","options":["By pairing car-free zones with affordable housing quotas and fast buses","By closing all outer bus routes","By charging pedestrians to enter parks"],"answer":"By pairing car-free zones with affordable housing quotas and fast buses"}]},{"kind":"reading","lesson":4,"title":"What makes a city street feel genuinely alive?","source":"Fluency Studio Architecture Essay","audioRef":"week-10/liveable-streets.mp3","audioStatus":"tts","body":"Walk through two neighbourhoods with similar population density and you may experience completely different atmospheres. On one street, pavements are narrow, blank walls line the ground floor, and delivery vans idle beside fast-moving traffic; pedestrians hurry past without looking up. Three blocks away, wider pavements, street trees, small independent grocers, and benches invite neighbours to pause and chat. Urban planners argue that liveability has far less to do with shiny skyscrapers than with what happens at eye level. When ground floors hold bookshops, repair cafés, clinics, and libraries rather than shuttered garages, streets feel considerably safer after dusk because ordinary people are naturally around. Transport infrastructure shapes that social life just as strongly. Cities that prioritise step-free accessibility, shaded bus shelters, and protected cycle lanes allow children, commuters, and older residents to share space comfortably without relying on private cars for every short errand. Of course, attractive districts can trigger rising rents and rapid gentrification if local authorities ignore housing supply. Protecting long-standing workshops and funding affordable housing alongside cleaner transit ensures that revitalised streets serve the whole community rather than pricing residents out. Encouragingly, several European and Latin American towns have proved that fairer street design does not require decades of underground tunnelling. Painted bus-priority lanes, secure cycle hangars on residential corners, and frequent weekend regional trains can transform daily mobility within two or three budget cycles. Residents who previously drove short three-kilometre errands willingly switch when walking routes feel well-lit, continuous, and pleasant in poor weather. Meanwhile, preserving ground-floor leases for independent pharmacies, repair workshops, and grocers keeps essential errands local, reducing congestion across the whole city while protecting social connection for older neighbours.","questions":[{"prompt":"Why do planners focus on what happens at eye level on a street?","options":["Tall skyscrapers are illegal in historic centres","Active ground-floor shops and spaces encourage safety and social contact","Delivery vans prefer wide pavements"],"answer":"Active ground-floor shops and spaces encourage safety and social contact"},{"prompt":"What risk does the essay warn about when a neighbourhood becomes more attractive?","options":["Rising rents and gentrification unless affordable housing is protected","Too many public libraries opening at night","A shortage of private cars"],"answer":"Rising rents and gentrification unless affordable housing is protected"}]}],"speaking":[{"kind":"monologue","title":"Improving transport in your town (3 min)","prompt":"Speak for 3 minutes comparing two transport or housing options in a city you know. Explain how to reduce congestion and improve accessibility using accurate articles, quantifiers, and comparative structures.","seconds":180,"phrases":["Compared with driving during peak hours…","The more accessible public transit is, the fewer…","It is nowhere near as costly as…"],"linkers":["meanwhile","consequently","on the other hand"],"terms":["congestion","infrastructure","pedestrianise","affordable housing"]}],"writing":{"title":"Council report: making a neighbourhood more liveable","prompt":"Write a 180–200 word report evaluating current transport or housing challenges in a town and recommending two practical changes using comparative structures and precise quantifiers.","format":"formal report","wordMin":180,"wordMax":200,"outline":{"analyze":"Use clear report headings (Overview, Current Issues, Recommendations).","plan":"Introduction -> two key issues -> two specific recommendations.","draft":"Check uncountable nouns (housing, congestion, infrastructure) have no -s or \"a\".","improve":"Include at least one double comparative (\"The more..., the...\") and varied modifiers.","review":"Verify 180–200 words and neutral formal tone."}},"lessons":[{"dayOfWeek":"Mon","requirement":"optional","outputRequired":false,"minutes":15,"title":"Vocabulary: Cities, transport and society","objective":"Learn 8–10 core B2 items for cities, transport and society, practising collocations and word families.","canDo":"I can deploy B2 cities, transport and society collocations accurately in context.","skill":"vocabulary","input":"reading","outputTitle":"Use 4 cities, transport and society expressions","output":"Write or record 4 nuanced sentences using this week's B2 collocations.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Tue","requirement":"optional","outputRequired":false,"minutes":15,"title":"Grammar: Articles and quantifiers (consolidation)","objective":"Practise Articles and quantifiers (consolidation) + Comparative structures with contrast rules and diagnostic drills.","canDo":"I can control Articles and quantifiers (consolidation) cleanly in formal and semi-formal B2 expression.","skill":"grammar","input":"reading","outputTitle":"Apply Articles and quantifiers (consolidation)","output":"Write or speak 3 complex sentences using Articles and quantifiers (consolidation) and Comparative structures.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Wed","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Listening: The fifteen-minute neighbourhood: reality or slogan?","objective":"Follow a 3-minute multi-accent discussion on cities, transport and society, noting nuance and hedging.","canDo":"I can extract main arguments, concessions, and implied attitude from a 3-minute track.","skill":"listening","input":"listening","outputTitle":"Summarise the speaker's position","output":"Summarise the main viewpoint and one counter-argument from today's listening track.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Thu","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Reading: What makes a city street feel genuinely alive?","objective":"Analyse a 250–350 word B2 article on cities, transport and society for evidence, tone, and structure.","canDo":"I can evaluate evidence and distinguish fact from opinion in a 250–350 word text.","skill":"reading","input":"reading","outputTitle":"Critical reaction to the article","output":"Write or record a short reaction explaining which point in the article is strongest and why.","targetSeconds":90,"wordRange":[80,120]},{"dayOfWeek":"Fri","requirement":"required","outputRequired":true,"minutes":15,"title":"Speaking (Required): Cities, transport and society","objective":"Deliver a structured 3-minute speaking response on cities, transport and society, plus Shadowing self-check.","canDo":"I can sustain a structured 3-minute B2 response on cities, transport and society.","skill":"speaking","input":"listening","outputTitle":"Structured speaking task (180s)","output":"Speak for 3 minutes comparing urban transport solutions with accurate articles, quantifiers, and comparatives.","targetSeconds":180,"wordRange":[100,160]},{"dayOfWeek":"Sat","requirement":"required","outputRequired":true,"minutes":30,"title":"Writing (Required): Council report: making a neighbourhood more liveable","objective":"Plan, draft, and polish a 180–200 word B2 piece on cities, transport and society.","canDo":"I can produce a cohesive 180–200 word B2 text using Articles and quantifiers (consolidation).","skill":"writing","input":"reading","outputTitle":"Council report: making a neighbourhood more liveable","output":"Write a 180–200 word report recommending urban transport and housing improvements.","targetSeconds":180,"wordRange":[180,200]},{"dayOfWeek":"Sun","requirement":"optional","outputRequired":false,"minutes":15,"title":"Review: Week 10 cards & error log","objective":"Consolidate Week 10 vocabulary cards and self-correct recurring mistakes before the next week.","canDo":"I can recall this week's B2 vocabulary and rewrite my recurring mistakes cleanly.","skill":"review","input":"reading","outputTitle":"Error-log rewrite","output":"Review due SRS cards and complete at least two error-log rewrite checks.","targetSeconds":60,"wordRange":[50,90]}],"vocabPack":{"collocations":[{"phrase":"ease traffic congestion","band":"B2","useRole":"B","example":"Frequent regional buses can ease traffic congestion during peak hours."},{"phrase":"upgrade ageing infrastructure","band":"B2","useRole":"B","example":"The municipality must upgrade ageing infrastructure before expanding the tram line."},{"phrase":"build affordable housing","band":"B2","useRole":"B","example":"Councils need land rules that encourage developers to build affordable housing."},{"phrase":"improve step-free accessibility","band":"B2","useRole":"B","example":"Lifts at every platform will improve step-free accessibility across the network."},{"phrase":"pedestrianise the centre","band":"B2","useRole":"B","example":"A vote to pedestrianise the centre transformed local café trade."},{"phrase":"avoid peak hours","band":"B1","useRole":"P","example":"Flexible start times allow commuters to avoid peak hours."}],"wordFamilies":[{"base":"access","forms":["accessible","accessibility","inaccessible"],"example":"Poor step-free accessibility leaves older stations inaccessible to many passengers."},{"base":"afford","forms":["affordable","affordability"],"example":"Rising rents threaten housing affordability even where apartments look modern."}],"linkingExpressions":[{"expression":"far fewer / far less","functionLabel":"Comparison","band":"B2","useRole":"B","example":"Pedestrianised streets carry far fewer cars and generate far less noise."},{"expression":"in addition","functionLabel":"Addition","band":"B1","useRole":"P","example":"Reliable buses cut journey times; in addition, they lower street-level pollution."}]}},{"number":11,"phase":"Month 3: Develop B2 communication","title":"Art, culture and creativity","summary":"Pack descriptive and analytical prose smoothly using participle clauses and reduced relative clauses.","hours":4,"releaseStage":"live","vocabularyTopic":"Museums, cinema, creative work and funding","lightGrammar":"Reduced relative clauses","grammar":[{"key":"participle-clauses","role":"main","name":"Participle clauses","explanation":"Use present (-ing), past (-ed), or perfect (having + past participle) clauses to link time, reason, or background concisely—making sure both clauses share the same subject.","keyPoints":["Having visited the exhibition twice, she noticed subtle brushwork she had missed first time.","Built in 1894, the theatre still hosts community plays every autumn.","Avoid dangling participles: the subject after the comma must be the person/thing doing the participle action."],"example":"Inspired by local folk tales, the director spent three winters filming along the coast.","items":[{"prompt":"___ in 1928, the cinema recently reopened as an independent arts centre.","options":["Building","Built","Having built"],"answer":"Built","explanation":"Passive meaning (\"which was built\") uses the past participle \"Built\".","difficulty":1},{"prompt":"___ read the director’s notes, I understood the ending much better.","options":["Having","Have","Had"],"answer":"Having","explanation":"\"Having + past participle\" shows one action finished before the main clause.","difficulty":2},{"prompt":"Which sentence avoids a dangling participle?","options":["Walking into the gallery, the sculptures immediately impressed us.","Walking into the gallery, we were immediately impressed by the sculptures.","Walking into the gallery, a large crowd was blocking the entrance."],"answer":"Walking into the gallery, we were immediately impressed by the sculptures.","explanation":"\"We\" are the ones walking into the gallery, matching the participle clause subject.","difficulty":3}]},{"key":"reduced-relative-clauses","role":"light","name":"Reduced relative clauses","explanation":"Shorten defining relative clauses cleanly by dropping \"who/which/that + be\" before active -ing or passive -ed phrases.","keyPoints":["Active: Visitors hoping to catch the evening talk (= who hope) should arrive early.","Passive: Photographs taken during the rehearsal (= which were taken) are displayed upstairs.","Never reduce a relative clause when the relative pronoun is the object of the verb."],"example":"Artists applying for the residency (= who are applying) must submit work completed within the past two years.","items":[{"prompt":"The mural ___ by neighbourhood teenagers brightens the whole underpass.","options":["painting","painted","which painting"],"answer":"painted","explanation":"Passive reduced relative clause (\"which was painted\").","difficulty":1},{"prompt":"Musicians ___ in small venues often rely on ticket sales rather than streaming.","options":["performing","performed","who performing"],"answer":"performing","explanation":"Active reduced relative clause (\"who perform\").","difficulty":1},{"prompt":"Anyone ___ to attend Friday’s play should collect a pass at reception.","options":["wish","wishing","wished"],"answer":"wishing","explanation":"\"Anyone wishing\" replaces \"anyone who wishes\".","difficulty":2}]}],"vocab":[{"term":"thought-provoking","pos":"adjective","definition":"making you think seriously about an idea or question","example":"The documentary offered a thought-provoking look at how public libraries adapt.","collocations":["thought-provoking exhibition","deeply thought-provoking"],"wordFamily":["thought","provoke"],"translation":"que invita a la reflexión","band":"B2","audioRef":"week-11/thought-provoking.mp3"},{"term":"curate","pos":"verb","definition":"select, organise, and present items in an exhibition, festival, or programme","example":"Local historians helped curate the photography display at the civic hall.","collocations":["curate an exhibition","carefully curated"],"wordFamily":["curator","curation"],"translation":"comisariar / seleccionar","band":"B2","audioRef":"week-11/curate.mp3"},{"term":"mainstream","pos":"adjective / noun","definition":"considered normal and widely accepted by most people rather than experimental","example":"Several small animation studios stayed independent rather than chasing mainstream hits.","collocations":["mainstream cinema","enter the mainstream"],"wordFamily":["mainstream"],"translation":"convencional / mayoritario","band":"B2","audioRef":"week-11/mainstream.mp3"},{"term":"acclaimed","pos":"adjective","definition":"publicly praised and admired by critics and audiences","example":"Her acclaimed short stories draw on voices from small coastal towns.","collocations":["critically acclaimed","widely acclaimed"],"wordFamily":["acclaim"],"translation":"aclamado","band":"B2","audioRef":"week-11/acclaimed.mp3"},{"term":"patronage","pos":"noun","definition":"financial support given to artists or cultural organisations by councils, charities, or individuals","example":"Without steady public patronage, regional orchestras struggle to tour smaller towns.","collocations":["arts patronage","depend on patronage"],"wordFamily":["patron"],"translation":"mecenazgo / patrocinio","band":"B2","audioRef":"week-11/patronage.mp3"},{"term":"evocative","pos":"adjective","definition":"bringing strong images, memories, or feelings clearly to mind","example":"The soundtrack used evocative folk melodies recorded in an empty chapel.","collocations":["evocative imagery","evocative description"],"wordFamily":["evoke"],"translation":"evocador","band":"B2","audioRef":"week-11/evocative.mp3"},{"term":"breakthrough","pos":"noun","definition":"an important new discovery or creative step forward after a period of effort","example":"Winning the Edinburgh fringe prize marked a major breakthrough for the playwright.","collocations":["creative breakthrough","major breakthrough"],"wordFamily":["break through"],"translation":"avance decisivo","band":"B2","audioRef":"week-11/breakthrough.mp3"},{"term":"accessible","pos":"adjective","definition":"easy for a wide range of people to understand, afford, or attend","example":"Pay-what-you-can evenings make live theatre accessible to students.","collocations":["accessible to everyone","make culture accessible"],"wordFamily":["access"],"translation":"accesible","band":"B2","audioRef":"week-11/accessible.mp3"},{"term":"originality","pos":"noun","definition":"the quality of being genuinely new, fresh, and inventive rather than copied","example":"Judges praised the sculpture’s quiet originality and recycled materials.","collocations":["creative originality","lack originality"],"wordFamily":["original","originally"],"translation":"originalidad","band":"B2","audioRef":"week-11/originality.mp3"}],"inputs":[{"kind":"listening","lesson":3,"title":"Why regional arts venues matter","source":"Fluency Studio Culture Show","accent":"British & Australian English","speaker_accents":[{"speaker":"Claire","accent":"en-GB","label":"British English"},{"speaker":"Ben","accent":"en-AU","label":"Australian English"}],"seconds":180,"audioRef":"week-11/regional-arts-venues.mp3","audioStatus":"tts","body":"Claire: When municipal budgets get tight, cultural grants are often the first line cut. Yet artists working outside capital cities say small theatres and neighbourhood galleries are where new voices actually begin. Ben, you directed a regional arts festival in Adelaide before moving to Sheffield. What disappears when a local venue closes? Ben: Far more than a Saturday night out. Having toured towns across two continents, I have seen how a single community cinema or rehearsal studio anchors an entire high street. Young writers experimenting with their first play rarely start on a West End stage; they test ideas in rooms seating eighty people, supported by curators willing to take a risk on originality. Built inside former warehouses or Victorian town halls, these spaces also bring generations together. A photography show curated by retired dockworkers alongside school students sparks conversations you never get in mainstream multiplexes. Claire: So public patronage is really seed funding for future culture? Ben: Exactly. Making culture accessible locally gives people confidence to create, not just consume.","questions":[{"prompt":"Why does Ben say small regional venues are vital for new artists?","options":["They pay higher salaries than national television","They give emerging creators space to test original work before smaller audiences","They only show mainstream blockbusters"],"answer":"They give emerging creators space to test original work before smaller audiences"},{"prompt":"What social benefit does Ben mention about local cultural spaces?","options":["They bring different generations together around shared exhibitions","They replace local schools and colleges","They keep ticket prices above commercial theatres"],"answer":"They bring different generations together around shared exhibitions"}]},{"kind":"reading","lesson":4,"title":"Does creative boredom still have a place?","source":"Fluency Studio Arts Essay","audioRef":"week-11/creative-boredom.mp3","audioStatus":"tts","body":"Ask novelists, composers, or designers where their strongest ideas first surfaced, and very few mention scrolling through a feed of trending clips. Surrounded by constant notifications and polished templates, modern creators can easily confuse rapid consumption with genuine originality. Several psychologists studying creative breakthroughs point out that the brain needs quiet, unstructured intervals to connect distant memories into something unexpected. Walking without headphones, sketching in a pocket notebook, or staring out of a train window may look unproductive on paper, yet those unhurried pauses often allow half-formed thoughts to settle. Museums and galleries curated with restraint understand this rhythm too. Exhibitions crowding fifty screens into a single room often leave visitors exhausted, whereas quieter galleries displaying twenty evocative paintings with space to sit invite sharper attention. Having stepped away from constant noise, viewers notice details—a shift in light, an unusual material, an unfinished line—that rushed viewing hides. Protecting creative space does not mean rejecting technology; rather, it means keeping room for stillness, curiosity, and slow experimentation alongside digital tools. Public arts education plays a quiet, vital role in keeping that curiosity alive across generations. When secondary schools protect time for theatre workshops, choral music, ceramics, and film editing alongside STEM subjects, teenagers discover practical ways to express complex ideas without relying purely on multiple-choice answers. Community funding also helps keep museum admissions affordable so families never feel excluded by ticket costs on wet Sunday afternoons. Whether through a small local bookshop hosting debut poets or a municipal gallery lending prints to clinics, accessible culture enriches everyday civic life far beyond major tourist festivals.","questions":[{"prompt":"What do psychologists say unstructured quiet intervals help the brain do?","options":["Memorise trending social feeds faster","Connect distant memories and ideas into original insights","Avoid visiting art galleries altogether"],"answer":"Connect distant memories and ideas into original insights"},{"prompt":"Why does the essay prefer restrained exhibitions over screen-crowded rooms?","options":["Quiet rooms with seating invite closer attention to detail","Paintings are cheaper to insure than screens","Visitors prefer spending less than ten minutes in museums"],"answer":"Quiet rooms with seating invite closer attention to detail"}]}],"speaking":[{"kind":"monologue","title":"A film, book, or exhibition that stayed with you (3 min)","prompt":"Speak for 3 minutes reviewing a film, exhibition, book, or concert that genuinely moved you, and explain whether public funding for local arts venues is worthwhile. Use participle clauses and reduced relative clauses.","seconds":180,"phrases":["Having seen it twice…","Set in a quiet coastal town…","Works created by local artists…"],"linkers":["notably","nevertheless","above all"],"terms":["thought-provoking","curate","evocative","accessible"]}],"writing":{"title":"Cultural article: why local arts spaces deserve support","prompt":"Write a 180–200 word magazine article reviewing a local cultural event or arguing why regional museums, libraries, and arts venues deserve steady funding.","format":"cultural feature article","wordMin":180,"wordMax":200,"outline":{"analyze":"Engage readers with a vivid opening image before presenting your argument.","plan":"Hook -> personal or local example -> broader cultural value -> memorable closing thought.","draft":"Include at least two participle clauses (-ing / -ed / having + pp) and one reduced relative clause.","improve":"Check that every opening participle shares its subject with the main clause.","review":"Verify 180–200 words and rich cultural collocations."}},"lessons":[{"dayOfWeek":"Mon","requirement":"optional","outputRequired":false,"minutes":15,"title":"Vocabulary: Art, culture and creativity","objective":"Learn 8–10 core B2 items for art, culture and creativity, practising collocations and word families.","canDo":"I can deploy B2 art, culture and creativity collocations accurately in context.","skill":"vocabulary","input":"reading","outputTitle":"Use 4 art, culture and creativity expressions","output":"Write or record 4 nuanced sentences using this week's B2 collocations.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Tue","requirement":"optional","outputRequired":false,"minutes":15,"title":"Grammar: Participle clauses","objective":"Practise Participle clauses + Reduced relative clauses with contrast rules and diagnostic drills.","canDo":"I can control Participle clauses cleanly in formal and semi-formal B2 expression.","skill":"grammar","input":"reading","outputTitle":"Apply Participle clauses","output":"Write or speak 3 complex sentences using Participle clauses and Reduced relative clauses.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Wed","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Listening: Why regional arts venues matter","objective":"Follow a 3-minute multi-accent discussion on art, culture and creativity, noting nuance and hedging.","canDo":"I can extract main arguments, concessions, and implied attitude from a 3-minute track.","skill":"listening","input":"listening","outputTitle":"Summarise the speaker's position","output":"Summarise the main viewpoint and one counter-argument from today's listening track.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Thu","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Reading: Does creative boredom still have a place?","objective":"Analyse a 250–350 word B2 article on art, culture and creativity for evidence, tone, and structure.","canDo":"I can evaluate evidence and distinguish fact from opinion in a 250–350 word text.","skill":"reading","input":"reading","outputTitle":"Critical reaction to the article","output":"Write or record a short reaction explaining which point in the article is strongest and why.","targetSeconds":90,"wordRange":[80,120]},{"dayOfWeek":"Fri","requirement":"required","outputRequired":true,"minutes":15,"title":"Speaking (Required): Art, culture and creativity","objective":"Deliver a structured 3-minute speaking response on art, culture and creativity, plus Shadowing self-check.","canDo":"I can sustain a structured 3-minute B2 response on art, culture and creativity.","skill":"speaking","input":"listening","outputTitle":"Structured speaking task (180s)","output":"Speak for 3 minutes on an inspiring cultural work and public arts support using participle clauses.","targetSeconds":180,"wordRange":[100,160]},{"dayOfWeek":"Sat","requirement":"required","outputRequired":true,"minutes":30,"title":"Writing (Required): Cultural article: why local arts spaces deserve support","objective":"Plan, draft, and polish a 180–200 word B2 piece on art, culture and creativity.","canDo":"I can produce a cohesive 180–200 word B2 text using Participle clauses.","skill":"writing","input":"reading","outputTitle":"Cultural article: why local arts spaces deserve support","output":"Write a 180–200 word cultural article using participle and reduced relative clauses.","targetSeconds":180,"wordRange":[180,200]},{"dayOfWeek":"Sun","requirement":"optional","outputRequired":false,"minutes":15,"title":"Review: Week 11 cards & error log","objective":"Consolidate Week 11 vocabulary cards and self-correct recurring mistakes before the next week.","canDo":"I can recall this week's B2 vocabulary and rewrite my recurring mistakes cleanly.","skill":"review","input":"reading","outputTitle":"Error-log rewrite","output":"Review due SRS cards and complete at least two error-log rewrite checks.","targetSeconds":60,"wordRange":[50,90]}],"vocabPack":{"collocations":[{"phrase":"curate an exhibition","band":"B2","useRole":"B","example":"Community volunteers helped curate an exhibition on neighbourhood craft."},{"phrase":"critically acclaimed","band":"B2","useRole":"B","example":"The critically acclaimed documentary sold out three local screenings."},{"phrase":"make culture accessible","band":"B2","useRole":"B","example":"Pay-what-you-can evenings help regional theatres make culture accessible."},{"phrase":"achieve a creative breakthrough","band":"B2","useRole":"B","example":"Stepping away from screens helped the composer achieve a creative breakthrough."},{"phrase":"enter the mainstream","band":"B2","useRole":"B","example":"Independent cinema often shapes style long before ideas enter the mainstream."},{"phrase":"depend on public patronage","band":"B2","useRole":"B","example":"Experimental venues still depend on public patronage to survive quiet seasons."}],"wordFamilies":[{"base":"origin","forms":["original","originality","originally"],"example":"Originally an experimental print shop, the space became famous for bold originality."},{"base":"evoke","forms":["evocative","evocation"],"example":"The film uses spare dialogue and evocative music rather than heavy exposition."}],"linkingExpressions":[{"expression":"having seen","functionLabel":"Participle link","band":"B2","useRole":"B","example":"Having seen the exhibition twice, I noticed how carefully the lighting was planned."},{"expression":"moreover","functionLabel":"Addition","band":"B2","useRole":"B","example":"Public galleries draw visitors; moreover, they host free youth workshops."}]}},{"number":12,"phase":"Month 3: Develop B2 communication","title":"Ethics, fairness and choices","summary":"Add rhetorical weight to ethical arguments using negative inversion (Not only…, Seldom…) and cleft sentences for sharp focus.","hours":4,"releaseStage":"live","vocabularyTopic":"Fairness, transparency and everyday ethics","lightGrammar":"Cleft sentences","grammar":[{"key":"inversion-emphasis","name":"Inversion and emphasis","explanation":"After a negative or limiting adverbial at the start of a sentence, invert the subject and auxiliary to add emphasis.","keyPoints":["Not only did the policy cut emissions, but it also created jobs.","Rarely have I seen such a weak argument.","Never before has the city faced this choice. / Little did we know…"],"example":"Not only did the levy reduce consumption, but it also funded school meals; rarely has a policy faced such organised opposition.","items":[{"prompt":"Not only ___ the policy cut emissions, but it also created jobs.","options":["did","has","did it"],"answer":"did","explanation":"Not only + auxiliary + subject + verb: Not only did the policy cut emissions…","difficulty":2},{"prompt":"Rarely ___ such a weak argument.","options":["I have heard","have I heard","I heard"],"answer":"have I heard","explanation":"A fronted negative adverbial triggers inversion: Rarely have I heard…","difficulty":2},{"prompt":"Which sentence is correctly inverted?","options":["Never the city has faced this choice.","Never has the city faced this choice.","Never has faced the city this choice."],"answer":"Never has the city faced this choice.","explanation":"Auxiliary before subject, then the main verb.","difficulty":3}],"role":"main"},{"key":"cleft-sentences","role":"light","name":"Cleft sentences","explanation":"Highlight the key reason, person, or detail in a debate using \"It is… that…\" or \"What matters most is…\".","keyPoints":["It-cleft: It is clear labelling—not vague promises—that builds shopper trust.","What-cleft: What consumers actually need is transparent supply-chain data.","Use cleft sentences selectively so your emphasis stays punchy."],"example":"Not only did the audit expose overtime abuses, but what shocked shoppers most was how easy fixes were.","items":[{"prompt":"___ matters most in fair-trade schemes is whether farmers receive stable prices.","options":["That","What","Which"],"answer":"What","explanation":"What-cleft (\"What matters most is...\") puts focus on the clause after \"is\".","difficulty":1},{"prompt":"It was the lack of independent checks ___ undermined public trust.","options":["what","that","whom"],"answer":"that","explanation":"It-cleft uses \"It is/was + focus + that/who...\".","difficulty":1},{"prompt":"Only when companies publish audit results ___ trust the label.","options":["consumers can","can consumers","do consumers can"],"answer":"can consumers","explanation":"\"Only when...\" at the start triggers subject-auxiliary inversion in the main clause.","difficulty":3}]}],"vocab":[{"term":"accountability","pos":"noun","definition":"the duty to accept responsibility and explain decisions openly","example":"Public funding should always come with clear financial accountability.","collocations":["demand accountability","lack of accountability"],"wordFamily":["accountable"],"translation":"rendición de cuentas","band":"B2","audioRef":"week-12/accountability.mp3"},{"term":"transparent","pos":"adjective","definition":"open and honest about rules, prices, or decisions so nothing is hidden","example":"Transparent pricing stops hidden fees appearing on the final screen.","collocations":["transparent process","be transparent about"],"wordFamily":["transparency","transparently"],"translation":"transparente","band":"B2","audioRef":"week-12/transparent.mp3"},{"term":"dilemma","pos":"noun","definition":"a difficult situation where you must choose between two competing options","example":"Whistleblowers often face a moral dilemma between loyalty and honesty.","collocations":["ethical dilemma","face a dilemma"],"wordFamily":["dilemma"],"translation":"dilema","band":"B2","audioRef":"week-12/dilemma.mp3"},{"term":"double standard","pos":"noun phrase","definition":"a rule or principle applied unfairly more strictly to one group than another","example":"Employees quickly notice a double standard if senior staff ignore office rules.","collocations":["expose a double standard","obvious double standard"],"wordFamily":["standard"],"translation":"doble rasero","band":"B2","audioRef":"week-12/double-standard.mp3"},{"term":"exploit","pos":"verb","definition":"treat someone unfairly for your own financial or personal gain","example":"Strict labour inspections help ensure seasonal workers are not exploited.","collocations":["exploit workers","exploit a loophole"],"wordFamily":["exploitation","exploitative"],"translation":"explotar / aprovecharse de","band":"B2","audioRef":"week-12/exploit.mp3"},{"term":"integrity","pos":"noun","definition":"the quality of being honest and sticking to strong moral principles","example":"Maintaining academic integrity means citing every source accurately.","collocations":["personal integrity","act with integrity"],"wordFamily":["integral"],"translation":"integridad","band":"B2","audioRef":"week-12/integrity.mp3"},{"term":"conflict of interest","pos":"noun phrase","definition":"a situation where private gain could improperly influence an official decision","example":"Panel members must declare any conflict of interest before scoring bids.","collocations":["declare a conflict of interest","potential conflict of interest"],"wordFamily":["conflict"],"translation":"conflicto de intereses","band":"B2","audioRef":"week-12/conflict-of-interest.mp3"},{"term":"loophole","pos":"noun","definition":"a gap in a rule or law that allows people to avoid its intended purpose","example":"Lawmakers closed the tax loophole after journalists published leaked records.","collocations":["close a loophole","exploit a loophole"],"wordFamily":["loophole"],"translation":"vacío legal","band":"B2","audioRef":"week-12/loophole.mp3"},{"term":"stand up for","pos":"phrasal verb","definition":"defend or support a person or principle openly when it is difficult","example":"Colleagues respected her for standing up for junior staff during pay talks.","collocations":["stand up for fairness","stand up for yourself"],"wordFamily":["stand up"],"translation":"defender","band":"B2","audioRef":"week-12/stand-up-for.mp3"}],"inputs":[{"kind":"listening","lesson":3,"title":"Panel debate: should cities ban cars from the centre?","source":"Studio original — panel discussion","accent":"British and American","seconds":180,"body":"HOST: Is a car-free centre realistic? COUNCILLOR REID: Not only has it worked elsewhere, but it has also increased footfall in the shops. That is the part people miss. TRADER MS KOVAC: With respect, that has not been our experience. Our deliveries arrive before seven, and the loading bay is gone. COUNCILLOR REID: Then let us concede that point and solve it — timed access. MS KOVAC: I would accept timed access, provided it is enforced. My worry is that it looks good in a report and fails in the street. Later in the debate, the consumer advocate raised an ethical dilemma: what happens when green policies hit lower-income households harder than wealthy drivers? Not only must councils offer fair exemptions for shift workers and disabled residents, she argued, but what builds lasting fairness is transparent communication about where congestion fees go. When every pound raised funds cleaner regional buses, citizens see tangible accountability rather than a double standard.","questions":[{"prompt":"What does Councillor Reid claim about shops?","options":["Footfall increased elsewhere","Shops closed","Deliveries stopped"],"answer":"Footfall increased elsewhere"},{"prompt":"What does Ms Kovac accept in the end?","options":["Timed access with enforcement","A total ban","No change at all"],"answer":"Timed access with enforcement"}],"speaker_accents":[{"speaker":"HOST","accent":"en-GB","label":"British"},{"speaker":"COUNCILLOR REID","accent":"en-GB","label":"British"},{"speaker":"MS KOVAC","accent":"en-US","label":"American"}],"audioRef":"module-7/panel-debate-should-cities-ban-cars-from-the-centre.mp3","audioStatus":"actor_pending"},{"kind":"reading","lesson":4,"title":"Why small everyday fairness builds lasting trust","source":"Fluency Studio Ethics Essay","audioRef":"week-12/everyday-fairness.mp3","audioStatus":"tts","body":"When people think about ethics, dramatic courtroom trials or corporate scandals usually come to mind first. Yet in ordinary workplaces, schools, and local councils, trust rises or falls on much quieter decisions: whether rules apply equally to senior leaders, whether a conflict of interest is declared before a contract is awarded, and whether someone admits a mistake without shifting blame onto junior staff. Rarely do institutions collapse overnight; instead, credibility erodes slowly whenever double standards become routine. What distinguishes healthy organisations is not perfection, since human judgement is always fallible, but visible accountability when loopholes appear. Suppose a team notices that flexible working is praised in recruitment adverts yet quietly penalised during promotion reviews. Not only does morale fall, but talented staff stop speaking honestly in meetings. Conversely, when leaders publish clear criteria, explain trade-offs transparently, and protect colleagues who stand up for fair treatment, people feel safe raising concerns early. Integrity at scale begins with small, consistent choices long before any crisis arrives. Training programmes in medicine, law, and engineering now spend far more time on realistic case studies than abstract moral puzzles. Instead of debating unlikely emergencies, trainees examine everyday pressures: what to do when a manager asks you to omit an inconvenient delay from a client summary, or how to respond when an algorithm scores applicants unevenly. Practising clear, respectful phrases for raising concerns early makes ethical courage far easier when real pressure hits. Organisations that reward honesty during routine reviews build cultures where integrity becomes normal practice rather than a risky exception.","questions":[{"prompt":"According to the essay, how does institutional credibility usually erode?","options":["In a single dramatic courtroom trial","Gradually when double standards become routine","Whenever junior staff speak in meetings"],"answer":"Gradually when double standards become routine"},{"prompt":"What does the essay say builds psychological safety in healthy organisations?","options":["Transparent criteria, accountability, and protecting people who raise concerns","Never allowing flexible working arrangements","Keeping promotion criteria private"],"answer":"Transparent criteria, accountability, and protecting people who raise concerns"}]}],"speaking":[{"kind":"monologue","title":"An ethical choice or fairness debate (3 min)","prompt":"Speak for 3 minutes about an ethical dilemma in business, sport, or everyday work—such as unpaid internships or hidden online fees. Use inversion and a cleft sentence to highlight your central argument.","seconds":180,"phrases":["Not only does this practice…","What matters most is…","Seldom do consumers see…"],"linkers":["in contrast","consequently","furthermore"],"terms":["accountability","transparent","double standard","integrity"]}],"writing":{"title":"Analytical essay: fairness and transparency at work","prompt":"Write a 180–200 word analytical essay discussing whether companies should be legally required to publish pay ranges and supply-chain audits openly.","format":"analytical essay","wordMin":180,"wordMax":200,"outline":{"analyze":"Present both the argument for mandatory transparency and business objections.","plan":"Introduction -> transparency benefits -> practical drawbacks -> balanced conclusion.","draft":"Use one negative inversion (\"Not only...\", \"Rarely...\") and one cleft sentence (\"What...\").","improve":"Strengthen topic sentences and replace general nouns with ethical terms (loophole, accountability).","review":"Check 180–200 words and inverted word order."}},"lessons":[{"dayOfWeek":"Mon","requirement":"optional","outputRequired":false,"minutes":15,"title":"Vocabulary: Ethics, fairness and choices","objective":"Learn 8–10 core B2 items for ethics, fairness and choices, practising collocations and word families.","canDo":"I can deploy B2 ethics, fairness and choices collocations accurately in context.","skill":"vocabulary","input":"reading","outputTitle":"Use 4 ethics, fairness and choices expressions","output":"Write or record 4 nuanced sentences using this week's B2 collocations.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Tue","requirement":"optional","outputRequired":false,"minutes":15,"title":"Grammar: Inversion and emphasis","objective":"Practise Inversion and emphasis + Cleft sentences with contrast rules and diagnostic drills.","canDo":"I can control Inversion and emphasis cleanly in formal and semi-formal B2 expression.","skill":"grammar","input":"reading","outputTitle":"Apply Inversion and emphasis","output":"Write or speak 3 complex sentences using Inversion and emphasis and Cleft sentences.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Wed","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Listening: Panel debate: should cities ban cars from the centre?","objective":"Follow a 3-minute multi-accent discussion on ethics, fairness and choices, noting nuance and hedging.","canDo":"I can extract main arguments, concessions, and implied attitude from a 3-minute track.","skill":"listening","input":"listening","outputTitle":"Summarise the speaker's position","output":"Summarise the main viewpoint and one counter-argument from today's listening track.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Thu","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Reading: Why small everyday fairness builds lasting trust","objective":"Analyse a 250–350 word B2 article on ethics, fairness and choices for evidence, tone, and structure.","canDo":"I can evaluate evidence and distinguish fact from opinion in a 250–350 word text.","skill":"reading","input":"reading","outputTitle":"Critical reaction to the article","output":"Write or record a short reaction explaining which point in the article is strongest and why.","targetSeconds":90,"wordRange":[80,120]},{"dayOfWeek":"Fri","requirement":"required","outputRequired":true,"minutes":15,"title":"Speaking (Required): Ethics, fairness and choices","objective":"Deliver a structured 3-minute speaking response on ethics, fairness and choices, plus Shadowing self-check.","canDo":"I can sustain a structured 3-minute B2 response on ethics, fairness and choices.","skill":"speaking","input":"listening","outputTitle":"Structured speaking task (180s)","output":"Speak for 3 minutes on an ethical dilemma using inversion and cleft sentences.","targetSeconds":180,"wordRange":[100,160]},{"dayOfWeek":"Sat","requirement":"required","outputRequired":true,"minutes":30,"title":"Writing (Required): Analytical essay: fairness and transparency at work","objective":"Plan, draft, and polish a 180–200 word B2 piece on ethics, fairness and choices.","canDo":"I can produce a cohesive 180–200 word B2 text using Inversion and emphasis.","skill":"writing","input":"reading","outputTitle":"Analytical essay: fairness and transparency at work","output":"Write a 180–200 word essay on pay and supply-chain transparency.","targetSeconds":180,"wordRange":[180,200]},{"dayOfWeek":"Sun","requirement":"optional","outputRequired":false,"minutes":15,"title":"Review: Week 12 cards & error log","objective":"Consolidate Week 12 vocabulary cards and self-correct recurring mistakes before the next week.","canDo":"I can recall this week's B2 vocabulary and rewrite my recurring mistakes cleanly.","skill":"review","input":"reading","outputTitle":"Error-log rewrite","output":"Review due SRS cards and complete at least two error-log rewrite checks.","targetSeconds":60,"wordRange":[50,90]}],"vocabPack":{"collocations":[{"phrase":"demand accountability","band":"B2","useRole":"B","example":"Employees rightly demand accountability when promotion criteria feel opaque."},{"phrase":"face an ethical dilemma","band":"B2","useRole":"B","example":"Whistleblowers often face an ethical dilemma between loyalty and honesty."},{"phrase":"expose a double standard","band":"B2","useRole":"B","example":"Auditors were quick to expose a double standard in expense approvals."},{"phrase":"declare a conflict of interest","band":"B2","useRole":"B","example":"Committee members must declare a conflict of interest before voting."},{"phrase":"close a legal loophole","band":"B2","useRole":"B","example":"New pay-reporting rules aim to close a legal loophole on contractor wages."},{"phrase":"act with integrity","band":"B2","useRole":"B","example":"Trust grows when leaders act with integrity even when nobody is checking."}],"wordFamilies":[{"base":"transparent","forms":["transparency","transparently"],"example":"Genuine transparency requires firms to publish salary bands transparently."},{"base":"exploit","forms":["exploitation","exploitative"],"example":"Weak oversight allows exploitative practices and worker exploitation."}],"linkingExpressions":[{"expression":"not only ... but also","functionLabel":"Emphasis","band":"B2","useRole":"B","example":"Not only did the audit cut waste, but it also restored staff trust."},{"expression":"what matters most is","functionLabel":"Cleft focus","band":"B2","useRole":"B","example":"What matters most is that every applicant faces the same transparent standard."}]}}]} $json$::jsonb) as imported_weeks_9_10_11_12;

select public.import_modules($json$ {"course_slug":"english-b1-b2","modules":[{"number":13,"phase":"Month 4: Consolidate B2","title":"Global issues and cooperation","summary":"Qualify complex international claims with hedging language and maintain an objective tone using impersonal structures.","hours":4,"releaseStage":"live","vocabularyTopic":"Cross-border treaties, aid, water and climate diplomacy","lightGrammar":"Impersonal structures","grammar":[{"key":"hedging","name":"Hedging language","explanation":"Hedging shows how confident you are, protects you from overclaiming and makes debate sound reasonable rather than dogmatic.","keyPoints":["It appears that the data supports the claim, although further study is needed.","This may suggest a link between the two, rather than prove one.","Use tend to, arguably, to some extent and it is likely that to soften claims."],"example":"The figures appear to support the tax, although they may also reflect a broader change in buying habits.","items":[{"prompt":"Which sentence is best hedged for an academic essay?","options":["Sugar taxes definitely work.","The evidence suggests that sugar taxes tend to reduce consumption.","Everyone knows sugar taxes work."],"answer":"The evidence suggests that sugar taxes tend to reduce consumption.","explanation":"Suggests and tend to signal limited confidence without weakening the point.","difficulty":1},{"prompt":"This ___ suggest a link, but it does not prove one.","options":["may","must","will"],"answer":"may","explanation":"May expresses possibility and keeps the claim proportionate.","difficulty":1},{"prompt":"Which phrase overclaims?","options":["It is likely that...","This arguably shows...","This proves beyond doubt..."],"answer":"This proves beyond doubt...","explanation":"Beyond doubt is an absolute claim, the opposite of hedging.","difficulty":2}],"role":"main"},{"key":"impersonal-structures","role":"light","name":"Impersonal structures","explanation":"Create formal distance in policy essays and position statements with \"It appears that…\", \"There seems to be…\", and \"One could argue that…\".","keyPoints":["Replace \"I think everybody knows\" with \"It is widely acknowledged that…\".","Use \"There tends to be…\" or \"There appears to be…\" to introduce patterns neutrally.","Pair impersonal frames with modals (may, could, might) to avoid sounding dogmatic."],"example":"It appears that cross-border river treaties tend to endure when local farmers are consulted early.","items":[{"prompt":"___ seems to be growing agreement that regional water sharing prevents disputes.","options":["It","There","What"],"answer":"There","explanation":"\"There seems to be + noun phrase\" is a natural impersonal structure.","difficulty":2},{"prompt":"It is ___ acknowledged that preventive disaster aid costs far less than rebuilding.","options":["wide","widely","wideness"],"answer":"widely","explanation":"Adverb \"widely\" modifies the participle \"acknowledged\".","difficulty":1},{"prompt":"Which opening best fits a balanced B2 position statement?","options":["Everyone knows global treaties always fail completely.","One could argue that international agreements work best when targets are verifiable.","International agreements are totally useless in every case."],"answer":"One could argue that international agreements work best when targets are verifiable.","explanation":"Combines an impersonal frame with measured qualification.","difficulty":1}]}],"vocab":[{"term":"cross-border","pos":"adjective","definition":"involving cooperation, trade, or movement across two or more countries","example":"Cross-border rail links make regional trade cleaner and faster.","collocations":["cross-border cooperation","cross-border river"],"wordFamily":["border"],"translation":"transfronterizo","band":"B2","audioRef":"week-13/cross-border.mp3"},{"term":"treaty","pos":"noun","definition":"a formal written agreement signed between two or more states","example":"Nine coastal nations signed a treaty to protect shared fish stocks.","collocations":["sign a treaty","binding treaty"],"wordFamily":["treat"],"translation":"tratado","band":"B2","audioRef":"week-13/treaty.mp3"},{"term":"humanitarian","pos":"adjective","definition":"concerned with reducing human suffering and improving welfare during crises","example":"Humanitarian agencies coordinated emergency water supplies within forty-eight hours.","collocations":["humanitarian aid","humanitarian relief"],"wordFamily":["humanity"],"translation":"humanitario","band":"B2","audioRef":"week-13/humanitarian.mp3"},{"term":"disparity","pos":"noun","definition":"a clear and often unfair difference between two groups or regions","example":"Investment in rural clinics narrowed the health disparity between regions.","collocations":["regional disparity","widening disparity"],"wordFamily":["disparate"],"translation":"desigualdad / disparidad","band":"B2","audioRef":"week-13/disparity.mp3"},{"term":"resilience","pos":"noun","definition":"the ability of a community or system to recover quickly from shocks","example":"Flood-warning networks strengthen coastal resilience ahead of winter storms.","collocations":["build resilience","climate resilience"],"wordFamily":["resilient"],"translation":"resiliencia","band":"B2","audioRef":"week-13/resilience.mp3"},{"term":"multilateral","pos":"adjective","definition":"involving three or more countries or organisations working together","example":"Ocean plastics require multilateral rules rather than isolated national bans.","collocations":["multilateral agreement","multilateral talks"],"wordFamily":["unilateral","bilateral"],"translation":"multilateral","band":"B2","audioRef":"week-13/multilateral.mp3"},{"term":"allocate","pos":"verb","definition":"officially assign money, time, or resources to a specific purpose","example":"Donors agreed to allocate emergency funds directly to local municipalities.","collocations":["allocate resources","allocate funding"],"wordFamily":["allocation"],"translation":"asignar","band":"B2","audioRef":"week-13/allocate.mp3"},{"term":"incentive","pos":"noun","definition":"something that encourages a person or government to take a particular action","example":"Shared research grants give universities a strong incentive to collaborate.","collocations":["financial incentive","provide an incentive"],"wordFamily":["incentivise"],"translation":"incentivo","band":"B2","audioRef":"week-13/incentive.mp3"},{"term":"bottleneck","pos":"noun","definition":"a narrow point in a process that slows down delivery or progress","example":"Customs paperwork created a bottleneck for medical shipments at the port.","collocations":["supply bottleneck","clear a bottleneck"],"wordFamily":["bottleneck"],"translation":"cuello de botella","band":"B2","audioRef":"week-13/bottleneck.mp3"}],"inputs":[{"kind":"listening","lesson":3,"title":"Shared rivers, shared futures","source":"Fluency Studio Global Affairs","accent":"British & Indian English","speaker_accents":[{"speaker":"Rachel","accent":"en-GB","label":"British English"},{"speaker":"Vikram","accent":"en-IN","label":"Indian English"}],"seconds":210,"audioRef":"week-13/shared-rivers.mp3","audioStatus":"tts","body":"Rachel: Global challenges like water scarcity rarely stop at national borders, yet international treaties often take years to negotiate. Vikram, you advise municipal water boards on cross-border river basins. Why do some multilateral water agreements endure for decades while others stall? Vikram: It appears that successful treaties share two quiet features. First, they allocate technical monitoring to joint engineering teams who exchange rainfall data weekly, even when politicians disagree. Second, they build flexibility into dry years instead of locking countries into rigid quotas. Look at how upstream reservoirs and downstream irrigation districts work when they share real-time satellite readings: farmers gain weeks of warning before a drought deepens. Rachel: Critics sometimes argue that international frameworks have no teeth—that governments ignore voluntary targets whenever domestic pressure rises. Vikram: That is a fair concern, and voluntary pledges alone certainly tend to fall short. However, linking cross-border cooperation to shared infrastructure grants creates a practical incentive to stay at the table. When neighbouring cities co-fund flood barriers and early-warning sensors, building resilience becomes mutually rewarding rather than a zero-sum contest. One could argue that steady, modest cooperation saves far more livelihoods than dramatic summit speeches.","questions":[{"prompt":"What helps multilateral river agreements survive political disagreements?","options":["Weekly technical data sharing and flexible drought rules","Banning all downstream farming","Waiting for summit speeches once every ten years"],"answer":"Weekly technical data sharing and flexible drought rules"},{"prompt":"How can agreements overcome the weakness of purely voluntary pledges?","options":["By stopping all cross-border communication","By tying cooperation to shared infrastructure funding and incentives","By using rigid quotas regardless of rainfall"],"answer":"By tying cooperation to shared infrastructure funding and incentives"}]},{"kind":"reading","lesson":4,"title":"Why local cities are quietly shaping global climate action","source":"Fluency Studio Policy Brief","audioRef":"week-13/cities-global-action.mp3","audioStatus":"tts","body":"Public attention during international climate summits naturally centres on prime ministers, binding treaties, and national carbon pledges. Yet a growing body of policy research suggests that many of the fastest reductions in emissions and energy waste happen far closer to the ground—inside city halls, port authorities, and regional power grids. Because mayors manage buses, building codes, waste collection, and urban tree canopies directly, municipal networks can test practical ideas without waiting years for every national legislature to agree. Through multilateral city alliances, engineers in Medellín, Rotterdam, and Bristol exchange exact blueprints for sponge parks, district heating, and flood resilience. Of course, cities cannot solve global disparities on their own. National governments still control tax policy, cross-border energy grids, and humanitarian aid budgets, and smaller towns often lack the specialist staff needed to clear funding bottlenecks. It is widely acknowledged, therefore, that global cooperation works best as a two-way partnership: treaties set ambitious rules and allocate finance fairly, while local municipalities turn broad commitments into streets people actually experience. Measured optimism, grounded in transparent data rather than slogans, tends to sustain public support longest. Equally encouraging is how university researchers, patient networks, and coastal municipalities now share open-source tools across continents. Rather than guarding every flood map or agricultural forecast behind expensive licences, public consortia publish translated manuals and low-cost sensor designs that smaller regions can adapt immediately. Of course, shared tools alone cannot replace steady finance or fair trade rules, and rich nations still face rightful scrutiny over whether promised adaptation funds arrive on schedule. Even so, practical technical solidarity demonstrates that global cooperation need not wait for unanimous treaties before protecting vulnerable communities on the ground.","questions":[{"prompt":"Why can municipal networks sometimes test climate solutions faster than national governments?","options":["Mayors directly manage buses, building codes, and local services","Cities do not need any public funding","National governments have banned treaties"],"answer":"Mayors directly manage buses, building codes, and local services"},{"prompt":"What bottleneck do smaller towns often face according to the brief?","options":["Too many international alliances","A shortage of specialist staff to navigate funding rules","Lack of any building codes"],"answer":"A shortage of specialist staff to navigate funding rules"}]}],"speaking":[{"kind":"monologue","title":"Position statement: international aid & cooperation (up to 3 min)","prompt":"Record a structured position statement (up to 3 minutes): \"Global challenges such as water scarcity and climate resilience are better solved through binding multilateral treaties than voluntary local action.\" Take a nuanced stance using hedging language and impersonal structures.","seconds":180,"phrases":["It is widely acknowledged that…","There appears to be a trade-off between…","One could argue that…"],"linkers":["to a certain extent","nevertheless","in the long run"],"terms":["multilateral","resilience","disparity","incentive"]}],"writing":{"title":"Position essay: global cooperation vs. local action","prompt":"Write a 200–220 word essay evaluating whether global challenges require binding international treaties or grassroots local initiatives first. Use hedging and impersonal structures.","format":"balanced position essay","wordMin":200,"wordMax":220,"outline":{"analyze":"Avoid extreme \"always/never\" claims; frame a clear, qualified thesis.","plan":"Introduction + thesis -> case for binding treaties -> role of local partnerships -> synthesis conclusion.","draft":"Include at least two hedging phrases and two impersonal frames (\"It appears that...\").","improve":"Check transitions between paragraphs so concessions flow naturally.","review":"Verify 200–220 words and formal B2 register."}},"lessons":[{"dayOfWeek":"Mon","requirement":"optional","outputRequired":false,"minutes":15,"title":"Vocabulary: Global issues and cooperation","objective":"Learn 8–10 core B2 items for global issues and cooperation, practising collocations and word families.","canDo":"I can deploy B2 global issues and cooperation collocations accurately in context.","skill":"vocabulary","input":"reading","outputTitle":"Use 4 global issues and cooperation expressions","output":"Write or record 4 nuanced sentences using this week's B2 collocations.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Tue","requirement":"optional","outputRequired":false,"minutes":15,"title":"Grammar: Hedging language","objective":"Practise Hedging language + Impersonal structures with contrast rules and diagnostic drills.","canDo":"I can control Hedging language cleanly in formal and semi-formal B2 expression.","skill":"grammar","input":"reading","outputTitle":"Apply Hedging language","output":"Write or speak 3 complex sentences using Hedging language and Impersonal structures.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Wed","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Listening: Shared rivers, shared futures","objective":"Follow a 3.5-minute multi-accent discussion on global issues and cooperation, noting nuance and hedging.","canDo":"I can extract main arguments, concessions, and implied attitude from a 3.5-minute track.","skill":"listening","input":"listening","outputTitle":"Summarise the speaker's position","output":"Summarise the main viewpoint and one counter-argument from today's listening track.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Thu","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Reading: Why local cities are quietly shaping global climate action","objective":"Analyse a 250–350 word B2 article on global issues and cooperation for evidence, tone, and structure.","canDo":"I can evaluate evidence and distinguish fact from opinion in a 250–350 word text.","skill":"reading","input":"reading","outputTitle":"Critical reaction to the article","output":"Write or record a short reaction explaining which point in the article is strongest and why.","targetSeconds":90,"wordRange":[80,120]},{"dayOfWeek":"Fri","requirement":"required","outputRequired":true,"minutes":15,"title":"Speaking (Required): Position Statement — Global issues and cooperation","objective":"Deliver a structured recorded position statement (up to 3 minutes) on global issues and cooperation, plus Shadowing self-check.","canDo":"I can record a clear, hedged B2 position statement up to 3 minutes on global issues and cooperation.","skill":"speaking","input":"listening","outputTitle":"Recorded position statement (up to 3 min)","output":"Record a position statement (up to 3 min) on multilateral vs. local cooperation using hedging and impersonal structures.","targetSeconds":180,"wordRange":[100,160]},{"dayOfWeek":"Sat","requirement":"required","outputRequired":true,"minutes":30,"title":"Writing (Required): Position essay: global cooperation vs. local action","objective":"Plan, draft, and polish a 200–220 word B2 piece on global issues and cooperation.","canDo":"I can produce a cohesive 200–220 word B2 text using Hedging language.","skill":"writing","input":"reading","outputTitle":"Position essay: global cooperation vs. local action","output":"Write a 200–220 word hedged essay on international cooperation.","targetSeconds":180,"wordRange":[200,220]},{"dayOfWeek":"Sun","requirement":"optional","outputRequired":false,"minutes":15,"title":"Review: Week 13 cards & error log","objective":"Consolidate Week 13 vocabulary cards and self-correct recurring mistakes before the next week.","canDo":"I can recall this week's B2 vocabulary and rewrite my recurring mistakes cleanly.","skill":"review","input":"reading","outputTitle":"Error-log rewrite","output":"Review due SRS cards and complete at least two error-log rewrite checks.","targetSeconds":60,"wordRange":[50,90]}],"vocabPack":{"collocations":[{"phrase":"sign a binding treaty","band":"B2","useRole":"B","example":"Neighbouring nations agreed to sign a binding treaty on river water sharing."},{"phrase":"build climate resilience","band":"B2","useRole":"B","example":"Flood barriers and wetlands work together to build climate resilience."},{"phrase":"allocate emergency funding","band":"B2","useRole":"B","example":"Regional agencies must allocate emergency funding transparently."},{"phrase":"narrow a regional disparity","band":"B2","useRole":"B","example":"Targeted rail links can help narrow a regional disparity in job access."},{"phrase":"clear a supply bottleneck","band":"B2","useRole":"B","example":"Joint customs desks helped clear a supply bottleneck at the port."},{"phrase":"provide a financial incentive","band":"B2","useRole":"B","example":"Grants provide a financial incentive for small towns to insulate public halls."}],"wordFamilies":[{"base":"resilient","forms":["resilience","resiliently"],"example":"Urban resilience depends on infrastructure built to recover resiliently from floods."},{"base":"allocate","forms":["allocation","reallocate"],"example":"Fair funding allocation sometimes requires governments to reallocate old budgets."}],"linkingExpressions":[{"expression":"it would appear that","functionLabel":"Hedging","band":"B2","useRole":"B","example":"It would appear that voluntary targets rarely match the speed of binding treaties."},{"expression":"to some extent","functionLabel":"Qualification","band":"B2","useRole":"B","example":"Local schemes help to some extent, though cross-border rules remain essential."}]}},{"number":14,"phase":"Month 4: Consolidate B2","title":"Innovation and the future","summary":"Project future milestones accurately with future perfect and future continuous, and calibrate probability with B2 speculation language.","hours":4,"releaseStage":"live","vocabularyTopic":"Automation, energy breakthroughs and forecasting","lightGrammar":"Speculation language","grammar":[{"key":"future-perfect-future-continuous","role":"main","name":"Future perfect and future continuous","explanation":"Use future continuous (will be + -ing) for an action in progress at a future moment, and future perfect (will have + past participle) for an achievement completed before a future deadline.","keyPoints":["By 2035, coastal regions will have replaced most diesel ferries with electric vessels.","This time next decade, far more technicians will be maintaining battery storage grids.","Pair future perfect with \"by + future time\" (by 2030, by the end of the decade)."],"example":"By 2032, engineers will have installed smart meters across the district and hospitals will be running on microgrids.","items":[{"prompt":"By the end of the decade, rural clinics ___ shifted most routine bookings online.","options":["will have","will be","are going"],"answer":"will have","explanation":"\"By + future time\" calls for future perfect (\"will have + past participle\").","difficulty":1},{"prompt":"Five years from now, commuters ___ using unified smart tickets across regions.","options":["will have","will be","have been"],"answer":"will be","explanation":"Action in progress at a future point uses future continuous (\"will be + -ing\").","difficulty":1},{"prompt":"By 2040, how many countries ___ phased out coal power completely?","options":["will be","will have","would be"],"answer":"will have","explanation":"Completion before 2040 uses future perfect.","difficulty":2}]},{"key":"speculation-language","role":"light","name":"Speculation language","explanation":"Express nuanced degrees of likelihood about emerging technologies using \"is bound to\", \"is likely/unlikely to\", \"may well\", and \"there is every chance that\".","keyPoints":["High certainty: Solid-state batteries are bound to cut charging times.","Moderate probability: Routine diagnostic tools may well save nurses hours of paperwork.","Low probability: Driverless lorries are unlikely to replace local delivery drivers overnight."],"example":"Automated translation tools may well speed up travel bookings, though face-to-face diplomacy is bound to stay human.","items":[{"prompt":"With battery costs falling steadily, home solar storage ___ become far more common.","options":["is bound to","is bound","bounds to"],"answer":"is bound to","explanation":"\"Be bound to + infinitive\" expresses strong future likelihood.","difficulty":1},{"prompt":"Early prototypes ___ fail in real winter conditions before engineers refine them.","options":["may well","bound to","likely"],"answer":"may well","explanation":"\"May well + bare infinitive\" expresses realistic possibility.","difficulty":2},{"prompt":"Full-scale fusion power is ___ to replace wind farms before 2035.","options":["unlikely","impossible","bound"],"answer":"unlikely","explanation":"\"Be unlikely to + infinitive\" expresses low probability politely.","difficulty":1}]}],"vocab":[{"term":"obsolete","pos":"adjective","definition":"out of date and no longer used because something newer exists","example":"Streaming and cloud backups made optical discs largely obsolete within a decade.","collocations":["become obsolete","render something obsolete"],"wordFamily":["obsolescence"],"translation":"obsoleto","band":"B2","audioRef":"week-14/obsolete.mp3"},{"term":"prototype","pos":"noun","definition":"the first working model of a new device built for testing before mass production","example":"The lab tested three waterproof prototypes before selecting final materials.","collocations":["working prototype","test a prototype"],"wordFamily":["prototyping"],"translation":"prototipo","band":"B2","audioRef":"week-14/prototype.mp3"},{"term":"automation","pos":"noun","definition":"the use of machines or software to perform repetitive work with minimal human input","example":"Warehouse automation changed hiring demand toward software maintenance roles.","collocations":["workplace automation","pace of automation"],"wordFamily":["automate","automated"],"translation":"automatización","band":"B2","audioRef":"week-14/automation.mp3"},{"term":"viable","pos":"adjective","definition":"practical and able to work successfully in real conditions","example":"Cheaper battery recycling makes electric buses financially viable for small towns.","collocations":["economically viable","a viable alternative"],"wordFamily":["viability"],"translation":"viable","band":"B2","audioRef":"week-14/viable.mp3"},{"term":"unforeseen","pos":"adjective","definition":"not expected or predicted before happening","example":"Every ambitious technology rollout brings unforeseen maintenance costs.","collocations":["unforeseen consequences","unforeseen delays"],"wordFamily":["foresee","foreseeable"],"translation":"imprevisto","band":"B2","audioRef":"week-14/unforeseen.mp3"},{"term":"adopt","pos":"verb","definition":"start using a new method, standard, or technology officially","example":"Hospitals may well adopt voice-notes software faster if privacy rules stay strict.","collocations":["widely adopt","slow to adopt"],"wordFamily":["adoption"],"translation":"adoptar","band":"B2","audioRef":"week-14/adopt.mp3"},{"term":"scalability","pos":"noun","definition":"the ability of a system or pilot project to grow smoothly to handle much larger demand","example":"A brilliant lab battery still fails commercially if it lacks scalability.","collocations":["test scalability","limits to scalability"],"wordFamily":["scalable","scale"],"translation":"escalabilidad","band":"B2","audioRef":"week-14/scalability.mp3"},{"term":"disruptive","pos":"adjective","definition":"radically changing how an existing industry or everyday habit works","example":"Cheap solar panels proved far more disruptive to energy markets than analysts forecast.","collocations":["disruptive innovation","disruptive effect"],"wordFamily":["disrupt","disruption"],"translation":"disruptivo","band":"B2","audioRef":"week-14/disruptive.mp3"},{"term":"ethical safeguard","pos":"noun phrase","definition":"a rule or technical limit built in to prevent misuse or harm","example":"Medical AI tools need clear ethical safeguards and human oversight before clinical use.","collocations":["build in ethical safeguards","strict ethical safeguards"],"wordFamily":["safeguard"],"translation":"garantía ética","band":"B2","audioRef":"week-14/ethical-safeguard.mp3"}],"inputs":[{"kind":"listening","lesson":3,"title":"Forecasting 2035: hype vs. quiet breakthroughs","source":"Fluency Studio Science & Future","accent":"British & American English","speaker_accents":[{"speaker":"Nora","accent":"en-GB","label":"British English"},{"speaker":"Devon","accent":"en-US","label":"American English"}],"seconds":210,"audioRef":"week-14/forecasting-2035.mp3","audioStatus":"tts","body":"Nora: Every January brings bold predictions about flying taxis and robotic households. Yet looking back twenty years, the innovations that genuinely reshaped daily life were often quieter: pocket maps, lithium batteries, and instant video calls. Devon, what separates lasting breakthroughs from flashy demos? Devon: Two tests: reliability and scalability. A prototype might look magical on a dry stage in California, yet remain completely unviable in a rainy Scottish winter. By 2035, most cities will have quietly upgraded grid-scale storage and heat pumps—changes nobody films for social media, even though they lower bills and emissions every day. Nora: What about workplace automation? Are office roles bound to shrink? Devon: Routine data entry and basic scheduling may well shrink, yet demand for human judgement, troubleshooting, and clear explanation is unlikely to disappear. Ten years from now, doctors and engineers will be working alongside diagnostic software, checking edge cases and catching unforeseen errors. The smartest policy is building ethical safeguards and continuous adult retraining early, long before older systems become obsolete.","questions":[{"prompt":"What two tests does Devon say separate lasting breakthroughs from flashy demos?","options":["Celebrity endorsement and viral videos","Reliability in real conditions and scalability","High retail price and luxury design"],"answer":"Reliability in real conditions and scalability"},{"prompt":"How does Devon expect workplace automation to affect skilled professionals by 2035?","options":["They will work alongside tools while providing judgement and error checking","Human troubleshooting will become completely obsolete","Nobody will need adult retraining"],"answer":"They will work alongside tools while providing judgement and error checking"}]},{"kind":"reading","lesson":4,"title":"Why repairability may define the next decade of design","source":"Fluency Studio Tech & Society","audioRef":"week-14/repairability.mp3","audioStatus":"tts","body":"For much of the smartphone era, innovation was measured almost exclusively by speed, thinness, and annual upgrades. Consumers grew used to sealed batteries and glued screens that turned minor faults into expensive replacements, making perfectly functional hardware feel obsolete within three years. Today, however, a quiet shift is gaining momentum across engineering departments and European consumer law. Right-to-repair rules increasingly require manufacturers to supply spare parts, modular batteries, and plain repair manuals for years after a device leaves the shelf. By 2032, industry analysts estimate that major appliance makers will have redesigned most everyday electronics so local technicians can swap worn components in ten minutes rather than scrapping whole circuit boards. Critics once warned that modular design might slow down performance, yet early laptops built around replaceable ports and memory modules have proved commercially viable—and unexpectedly popular with universities and small businesses seeking predictable maintenance budgets. Admittedly, software automation and cloud tools will still tempt buyers toward newer models, and unforeseen supply bottlenecks can delay spare parts. Even so, durability is bound to become a genuine badge of prestige: the cleverest future device may not be the thinnest one on stage, but the one still running smoothly eight years later. Education systems and technical colleges are adjusting slowly to keep pace with this shift toward repairable, durable engineering. Instead of treating hardware purely as disposable consumer fashion, vocational programmes increasingly teach diagnostics, component replacement, and clean energy maintenance alongside coding. By the middle of the next decade, skilled repair technicians and systems auditors are likely to be among the most sought-after roles in local economies. If governments back clear labelling—showing expected battery lifespan and spare-part availability right beside the price—shoppers can reward thoughtful design with every ordinary purchase.","questions":[{"prompt":"What problem did sealed batteries and glued screens create?","options":["Devices stayed in use for over ten years","Minor faults forced costly full replacements too early","Local repair shops ran out of customers"],"answer":"Minor faults forced costly full replacements too early"},{"prompt":"Why have modular laptops appealed to universities and small businesses?","options":["They offer easier repairs and more predictable maintenance budgets","They never need software updates","They weigh twice as much as standard laptops"],"answer":"They offer easier repairs and more predictable maintenance budgets"}]}],"speaking":[{"kind":"monologue","title":"Position statement: innovation in 2035 (up to 3 min)","prompt":"Record a position statement (up to 3 minutes) predicting how one sector—transport, healthcare, or education—will have changed by 2035, explaining what is bound to improve and what ethical safeguards are needed.","seconds":180,"phrases":["By 2035, most clinics will have…","Teachers will be using…","While automation may well…"],"linkers":["admittedly","nonetheless","by contrast"],"terms":["prototype","viable","scalability","ethical safeguard"]}],"writing":{"title":"Forecast essay: technology, work and safeguards in 2035","prompt":"Write a 200–220 word essay predicting how emerging technology will change education or healthcare by 2035, weighing practical benefits against unforeseen risks.","format":"future forecast essay","wordMin":200,"wordMax":220,"outline":{"analyze":"Balance realistic predictions with clear caveats about limits and safeguards.","plan":"Introduction -> projected gains (future perfect/continuous) -> risks & safeguards -> conclusion.","draft":"Include both future perfect (\"will have...\") and speculation phrases (\"is bound to\", \"may well\").","improve":"Check precise vocabulary (viable, scalability, obsolete) and formal register.","review":"Verify 200–220 words and verb-form accuracy."}},"lessons":[{"dayOfWeek":"Mon","requirement":"optional","outputRequired":false,"minutes":15,"title":"Vocabulary: Innovation and the future","objective":"Learn 8–10 core B2 items for innovation and the future, practising collocations and word families.","canDo":"I can deploy B2 innovation and the future collocations accurately in context.","skill":"vocabulary","input":"reading","outputTitle":"Use 4 innovation and the future expressions","output":"Write or record 4 nuanced sentences using this week's B2 collocations.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Tue","requirement":"optional","outputRequired":false,"minutes":15,"title":"Grammar: Future perfect and future continuous","objective":"Practise Future perfect and future continuous + Speculation language with contrast rules and diagnostic drills.","canDo":"I can control Future perfect and future continuous cleanly in formal and semi-formal B2 expression.","skill":"grammar","input":"reading","outputTitle":"Apply Future perfect and future continuous","output":"Write or speak 3 complex sentences using Future perfect and future continuous and Speculation language.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Wed","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Listening: Forecasting 2035: hype vs. quiet breakthroughs","objective":"Follow a 3.5-minute multi-accent discussion on innovation and the future, noting nuance and hedging.","canDo":"I can extract main arguments, concessions, and implied attitude from a 3.5-minute track.","skill":"listening","input":"listening","outputTitle":"Summarise the speaker's position","output":"Summarise the main viewpoint and one counter-argument from today's listening track.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Thu","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Reading: Why repairability may define the next decade of design","objective":"Analyse a 250–350 word B2 article on innovation and the future for evidence, tone, and structure.","canDo":"I can evaluate evidence and distinguish fact from opinion in a 250–350 word text.","skill":"reading","input":"reading","outputTitle":"Critical reaction to the article","output":"Write or record a short reaction explaining which point in the article is strongest and why.","targetSeconds":90,"wordRange":[80,120]},{"dayOfWeek":"Fri","requirement":"required","outputRequired":true,"minutes":15,"title":"Speaking (Required): Position Statement — Innovation and the future","objective":"Deliver a structured recorded position statement (up to 3 minutes) on innovation and the future, plus Shadowing self-check.","canDo":"I can record a clear, hedged B2 position statement up to 3 minutes on innovation and the future.","skill":"speaking","input":"listening","outputTitle":"Recorded position statement (up to 3 min)","output":"Record a position statement (up to 3 min) forecasting 2035 changes using future perfect, future continuous, and speculation.","targetSeconds":180,"wordRange":[100,160]},{"dayOfWeek":"Sat","requirement":"required","outputRequired":true,"minutes":30,"title":"Writing (Required): Forecast essay: technology, work and safeguards in 2035","objective":"Plan, draft, and polish a 200–220 word B2 piece on innovation and the future.","canDo":"I can produce a cohesive 200–220 word B2 text using Future perfect and future continuous.","skill":"writing","input":"reading","outputTitle":"Forecast essay: technology, work and safeguards in 2035","output":"Write a 200–220 word essay evaluating technological change by 2035.","targetSeconds":180,"wordRange":[200,220]},{"dayOfWeek":"Sun","requirement":"optional","outputRequired":false,"minutes":15,"title":"Review: Week 14 cards & error log","objective":"Consolidate Week 14 vocabulary cards and self-correct recurring mistakes before the next week.","canDo":"I can recall this week's B2 vocabulary and rewrite my recurring mistakes cleanly.","skill":"review","input":"reading","outputTitle":"Error-log rewrite","output":"Review due SRS cards and complete at least two error-log rewrite checks.","targetSeconds":60,"wordRange":[50,90]}],"vocabPack":{"collocations":[{"phrase":"test a working prototype","band":"B2","useRole":"B","example":"Engineers will test a working prototype in coastal towns next spring."},{"phrase":"become economically viable","band":"B2","useRole":"B","example":"Grid-scale batteries have finally become economically viable for rural clinics."},{"phrase":"trigger unforeseen consequences","band":"B2","useRole":"B","example":"Rushing automation into schools can trigger unforeseen consequences for assessment."},{"phrase":"build in ethical safeguards","band":"B2","useRole":"B","example":"Hospitals must build in ethical safeguards before deploying diagnostic models."},{"phrase":"render equipment obsolete","band":"B2","useRole":"B","example":"Proprietary chargers quickly render otherwise functional equipment obsolete."},{"phrase":"test long-term scalability","band":"B2","useRole":"B","example":"Pilot schemes look promising, yet planners must test long-term scalability."}],"wordFamilies":[{"base":"automate","forms":["automation","automated"],"example":"Automated triage speeds up intake, yet full automation still needs human review."},{"base":"foresee","forms":["foreseeable","unforeseen"],"example":"Even careful forecasts leave room for unforeseen shifts alongside foreseeable trends."}],"linkingExpressions":[{"expression":"by 2035","functionLabel":"Future milestone","band":"B2","useRole":"B","example":"By 2035, most regional rail fleets will have switched to electric traction."},{"expression":"is bound to","functionLabel":"Strong probability","band":"B2","useRole":"B","example":"Repair-right legislation is bound to extend the average lifespan of electronics."}]}},{"number":15,"phase":"Month 4: Consolidate B2","title":"Persuasion and argument","summary":"Build persuasive B2 arguments using concession linkers (even though, despite, whereas) and consistent formal register.","hours":4,"releaseStage":"live","vocabularyTopic":"Debate, evidence, concession and formal proposals","lightGrammar":"Formal register","grammar":[{"key":"advanced-linkers","name":"Linking devices and concession","explanation":"Advanced writing needs linkers that signal contrast, consequence and concession precisely, with the right grammar after each one.","keyPoints":["Contrast between clauses: Whereas the tax raised revenue, it hit low earners hardest.","Consequence: Consequently, consumption fell by eighteen per cent.","Concession: Nevertheless, the measure remains controversial. / In spite of the criticism, it stayed."],"example":"Whereas the levy reduced consumption, it was criticised as regressive; nevertheless, the government has kept it, in spite of two legal challenges.","items":[{"prompt":"___ the tax raised revenue, it hit low earners hardest.","options":["Whereas","Nevertheless","Consequently"],"answer":"Whereas","explanation":"Whereas introduces a direct contrast between two clauses.","difficulty":1},{"prompt":"Consumption fell sharply; ___, revenue also dropped.","options":["consequently","whereas","in spite of"],"answer":"consequently","explanation":"Consequently marks a result of the previous statement.","difficulty":1},{"prompt":"___ the criticism, the policy remained in place.","options":["In spite of","Whereas","Consequently"],"answer":"In spite of","explanation":"In spite of + noun phrase expresses concession.","difficulty":2}],"role":"main"},{"key":"formal-register","role":"light","name":"Formal register","explanation":"Keep essays and proposals consistent by replacing conversational fillers, phrasal verbs, and contractions with precise academic or professional alternatives.","keyPoints":["Replace \"a lot of / big problem\" with \"a substantial proportion of / a pressing challenge\".","Avoid contractions (don’t, can’t) and exclamation marks in formal proposals.","Choose formal verbs: \"implement\" instead of \"put in place\", \"address\" instead of \"sort out\"."],"example":"Notwithstanding the initial capital cost, implementing flexible commuter passes would substantially ease rush-hour overcrowding.","items":[{"prompt":"___ the initial cost, the pilot project delivered measurable savings within a year.","options":["Although","Despite","Whereas"],"answer":"Despite","explanation":"\"Despite\" takes a noun phrase (\"the initial cost\"), whereas \"although\" takes a clause.","difficulty":1},{"prompt":"Which sentence maintains consistent formal register for a council proposal?","options":["We really should sort out this huge mess as soon as possible!","The committee should implement an independent review prior to renewing the contract.","Lots of folks reckon the current system doesn’t work at all."],"answer":"The committee should implement an independent review prior to renewing the contract.","explanation":"Formal lexical choices without contractions or slang.","difficulty":1},{"prompt":"Public libraries cost relatively little to run, ___ their social return is substantial.","options":["despite","whereas","in spite of"],"answer":"whereas","explanation":"\"Whereas\" contrasts two full clauses cleanly.","difficulty":2}]}],"vocab":[{"term":"persuasive","pos":"adjective","definition":"able to convince people to agree","example":"Her closing argument was quietly persuasive.","collocations":["a persuasive argument"],"wordFamily":["persuasive"],"translation":"persuasivo","band":"B2","audioRef":"week-15/persuasive.mp3"},{"term":"compelling evidence","pos":"noun","definition":"evidence strong enough to convince","example":"There is compelling evidence that the scheme works.","collocations":["provide compelling evidence"],"wordFamily":["compelling evidence"],"translation":"pruebas convincentes","band":"B2","audioRef":"week-15/compelling-evidence.mp3"},{"term":"counter-argument","pos":"noun","definition":"a reason against a position","example":"He answered the counter-argument before it was raised.","collocations":["address the counter-argument"],"wordFamily":["counter-argument"],"translation":"contraargumento","band":"B2","audioRef":"week-15/counter-argument.mp3"},{"term":"concede a point","pos":"phrase","definition":"admit that the other side is partly right","example":"I concede the point about cost, but not about fairness.","collocations":["willing to concede a point"],"wordFamily":["concede a point"],"translation":"conceder un punto","band":"B2","audioRef":"week-15/concede-a-point.mp3"},{"term":"policy proposal","pos":"noun","definition":"a suggested plan of action for an organisation","example":"The policy proposal goes to the committee in May.","collocations":["draft a policy proposal"],"wordFamily":["policy proposal"],"translation":"propuesta política","band":"B2","audioRef":"week-15/policy-proposal.mp3"},{"term":"common ground","pos":"noun","definition":"shared opinions or interests","example":"We found common ground on transport.","collocations":["find common ground"],"wordFamily":["common ground"],"translation":"terreno común","band":"B2","audioRef":"week-15/common-ground.mp3"},{"term":"weak argument","pos":"noun","definition":"a reason that does not convince","example":"Saying 'it has always been like this' is a weak argument.","collocations":["a fundamentally weak argument"],"wordFamily":["weak argument"],"translation":"argumento débil","band":"B2","audioRef":"week-15/weak-argument.mp3"},{"term":"rebut","pos":"verb","definition":"answer an argument with evidence or reasoning","example":"She rebutted the claim in two sentences.","collocations":["rebut a claim"],"wordFamily":["rebut"],"translation":"refutar","band":"B2","audioRef":"week-15/rebut.mp3"},{"term":"credibility","pos":"noun","definition":"the quality of being believed or trusted","example":"Overstating the case costs you credibility.","collocations":["lose credibility"],"wordFamily":["credibility"],"translation":"credibilidad","band":"B2","audioRef":"week-15/credibility.mp3"}],"inputs":[{"kind":"listening","lesson":3,"title":"How strong debaters concede without losing","source":"Fluency Studio Rhetoric Workshop","accent":"British & Australian English","speaker_accents":[{"speaker":"Eleanor","accent":"en-GB","label":"British English"},{"speaker":"Liam","accent":"en-AU","label":"Australian English"}],"seconds":210,"audioRef":"week-15/how-debaters-concede.mp3","audioStatus":"tts","body":"Eleanor: Many B1 speakers worry that admitting any weakness in their own opinion ruins an argument. In reality, B2-level persuasion relies on doing the opposite: conceding a real point early so your rebuttal carries real weight. Liam, you coach university debating teams. What happens when a speaker refuses to acknowledge counter-arguments? Liam: Listeners immediately switch off because the argument feels one-sided and naive. Suppose you are arguing for a four-day working week. If you pretend every hospital or emergency service can simply close on Fridays, your credibility vanishes. Instead, a strong speaker says: \"Admittedly, front-line services still require seven-day cover; nevertheless, administrative teams often maintain output in fewer hours when meetings are streamlined.\" Eleanor: And what about register in written proposals? Liam: In formal writing, small shifts make an immediate difference. Replacing \"a lot of people hate\" with \"a significant proportion of residents object to\" signals careful thought rather than personal frustration. Combining crisp linking devices—such as \"despite\", \"whereas\", and \"consequently\"—with one concrete piece of evidence turns loose opinions into compelling advocacy.","questions":[{"prompt":"Why does Liam say conceding an opponent’s point makes an argument stronger?","options":["It shows balanced judgement and protects the speaker’s credibility","It fills extra speaking time without evidence","It confuses the audience about your position"],"answer":"It shows balanced judgement and protects the speaker’s credibility"},{"prompt":"How should a speaker improve register in a formal written proposal?","options":["Use stronger exclamation marks","Use precise wording and linking devices paired with concrete evidence","Write exactly as you chat with close friends"],"answer":"Use precise wording and linking devices paired with concrete evidence"}]},{"kind":"reading","lesson":4,"title":"How to write a proposal that gets read","source":"Studio original","body":"Most proposals fail for a boring reason: the reader cannot find the recommendation. A useful proposal opens with the decision required, not with background. It states the problem in one paragraph, the options in three, and the recommendation in one sentence that could be quoted. Evidence should be proportionate: two strong figures persuade more than ten weak ones. Finally, anticipate the objection your reader will raise and answer it on the page, in their words. Not only does this show respect, but it also removes the easiest reason to say no. Look equally closely at how you rebut predictable objections. A persuasive proposal never waits for sceptical readers to raise budget or staffing worries in the margin; it anticipates the strongest counter-argument in paragraph three, concedes where compromises are sensible, and demonstrates why the remaining benefits still outweigh the drawbacks. Moreover, register consistency matters from the greeting to the closing recommendation. Mixing casual conversational idioms with stiff legal phrases makes a document read unevenly. Aim instead for clear, active formal prose: state the exact problem, cite one measurable outcome from a comparable pilot, specify who owns each action, and close with a realistic three-month review date. Readers remember proposals that respect their time and offer workable next steps. Finally, pay close attention to tone when finishing a formal argument. Ending with an exaggerated warning (\"Otherwise, disaster is inevitable!\") weakens hours of careful analysis, whereas a measured closing recommendation (\"Implementing a six-month trial across two districts would test feasibility at modest cost\") leaves decision-makers ready to engage. Strong persuasion rarely sounds aggressive; it combines respect for the reader’s intelligence with clear evidence, fair concessions, and an actionable path forward. Practising that calm authority prepares speakers and writers alike for university seminars, workplace proposals, and B2 assessments.","questions":[{"prompt":"What should a proposal open with?","options":["The decision required","Long background","A list of sources"],"answer":"The decision required"},{"prompt":"What does the writer advise about evidence?","options":["Use two strong figures","Include everything","Avoid figures"],"answer":"Use two strong figures"}],"audioRef":"module-7/how-to-write-a-proposal-that-gets-read.mp3","audioStatus":"tts"}],"speaking":[{"kind":"prompt_card","title":"Position statement: defending a policy proposal (up to 3 min)","prompt":"Record a 3-minute persuasive position statement proposing one practical policy change in education, work, or city life. Concede the strongest counter-argument fairly before rebutting it with evidence.","seconds":180,"phrases":["Not only does this..., but it also...","It appears that...","I would concede that..., however..."],"linkers":["moreover","nevertheless","in other words"],"terms":["policy proposal","compelling evidence","counter-argument"]}],"writing":{"title":"Formal proposal: a change worth making","prompt":"Write a 200–220 word formal proposal to a decision-maker recommending one change to a policy you know. Include the decision required, the options and a clear recommendation.","format":"formal proposal","wordMin":200,"wordMax":220,"outline":{"analyze":"Purpose: secure a decision. Audience: a busy official. Register: formal and direct.","plan":"Decision required → problem → three options → recommendation → one anticipated objection.","draft":"Use one inversion, two hedges and a conditional offer (provided that).","improve":"Cut background; make the recommendation quotable in one sentence.","review":"Check that a reader could act on the proposal after one reading."}},"lessons":[{"dayOfWeek":"Mon","requirement":"optional","outputRequired":false,"minutes":15,"title":"Vocabulary: Persuasion and argument","objective":"Learn 8–10 core B2 items for persuasion and argument, practising collocations and word families.","canDo":"I can deploy B2 persuasion and argument collocations accurately in context.","skill":"vocabulary","input":"reading","outputTitle":"Use 4 persuasion and argument expressions","output":"Write or record 4 nuanced sentences using this week's B2 collocations.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Tue","requirement":"optional","outputRequired":false,"minutes":15,"title":"Grammar: Linking devices and concession","objective":"Practise Linking devices and concession + Formal register with contrast rules and diagnostic drills.","canDo":"I can control Linking devices and concession cleanly in formal and semi-formal B2 expression.","skill":"grammar","input":"reading","outputTitle":"Apply Linking devices and concession","output":"Write or speak 3 complex sentences using Linking devices and concession and Formal register.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Wed","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Listening: How strong debaters concede without losing","objective":"Follow a 3.5-minute multi-accent discussion on persuasion and argument, noting nuance and hedging.","canDo":"I can extract main arguments, concessions, and implied attitude from a 3.5-minute track.","skill":"listening","input":"listening","outputTitle":"Summarise the speaker's position","output":"Summarise the main viewpoint and one counter-argument from today's listening track.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Thu","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Reading: How to write a proposal that gets read","objective":"Analyse a 250–350 word B2 article on persuasion and argument for evidence, tone, and structure.","canDo":"I can evaluate evidence and distinguish fact from opinion in a 250–350 word text.","skill":"reading","input":"reading","outputTitle":"Critical reaction to the article","output":"Write or record a short reaction explaining which point in the article is strongest and why.","targetSeconds":90,"wordRange":[80,120]},{"dayOfWeek":"Fri","requirement":"required","outputRequired":true,"minutes":15,"title":"Speaking (Required): Position Statement — Persuasion and argument","objective":"Deliver a structured recorded position statement (up to 3 minutes) on persuasion and argument, plus Shadowing self-check.","canDo":"I can record a clear, hedged B2 position statement up to 3 minutes on persuasion and argument.","skill":"speaking","input":"listening","outputTitle":"Recorded position statement (up to 3 min)","output":"Record a position statement (up to 3 min) defending a proposal with fair concession and rebuttal.","targetSeconds":180,"wordRange":[100,160]},{"dayOfWeek":"Sat","requirement":"required","outputRequired":true,"minutes":30,"title":"Writing (Required): Formal proposal: a change worth making","objective":"Plan, draft, and polish a 200–220 word B2 piece on persuasion and argument.","canDo":"I can produce a cohesive 200–220 word B2 text using Linking devices and concession.","skill":"writing","input":"reading","outputTitle":"Formal proposal: a change worth making","output":"Write a 200–220 word formal proposal to a decision-maker recommending one change to a policy you know. Include the decision required, the options and a clear recommendation.","targetSeconds":180,"wordRange":[200,220]},{"dayOfWeek":"Sun","requirement":"optional","outputRequired":false,"minutes":15,"title":"Review: Week 15 cards & error log","objective":"Consolidate Week 15 vocabulary cards and self-correct recurring mistakes before the next week.","canDo":"I can recall this week's B2 vocabulary and rewrite my recurring mistakes cleanly.","skill":"review","input":"reading","outputTitle":"Error-log rewrite","output":"Review due SRS cards and complete at least two error-log rewrite checks.","targetSeconds":60,"wordRange":[50,90]}],"vocabPack":{"collocations":[{"phrase":"provide compelling evidence","band":"B2","useRole":"B","example":"Three independent trials provide compelling evidence for extending library hours."},{"phrase":"concede a valid point","band":"B2","useRole":"B","example":"Strong proposals concede a valid point about cost before proposing savings."},{"phrase":"find common ground","band":"B2","useRole":"B","example":"Employers and unions managed to find common ground on flexible shift swaps."},{"phrase":"rebut a counter-argument","band":"B2","useRole":"B","example":"Use concrete figures rather than slogans to rebut a counter-argument."},{"phrase":"draft a policy proposal","band":"B2","useRole":"B","example":"The working group will draft a policy proposal for Monday’s board meeting."},{"phrase":"maintain credibility","band":"B2","useRole":"B","example":"Acknowledging limitations openly helps analysts maintain credibility."}],"wordFamilies":[{"base":"persuade","forms":["persuasive","persuasion","persuasively"],"example":"Persuasive writing pairs calm persuasion with evidence presented persuasively."},{"base":"credible","forms":["credibility","incredible"],"example":"Exaggerated claims damage credibility far faster than modest, credible estimates."}],"linkingExpressions":[{"expression":"admittedly","functionLabel":"Concession","band":"B2","useRole":"B","example":"Admittedly, the initial setup costs are high; nonetheless, operating expenses fall."},{"expression":"in light of","functionLabel":"Formal cause","band":"B2","useRole":"B","example":"In light of recent ridership figures, we recommend extending the evening bus route."}]}},{"number":16,"phase":"Month 4: Consolidate B2","title":"B2 consolidation and review","summary":"Consolidate B2 accuracy and fluency through a dynamic mixed review drawn from your personal error log and final checkpoint preparation.","hours":4,"releaseStage":"live","vocabularyTopic":"Synthesis, nuance, evidence and self-evaluation","lightGrammar":null,"grammar":[{"key":"error-log-mixed-review","role":"main","name":"Mixed review chosen from each learner’s error log","explanation":"Week 16 targets your personal recurring patterns across articles, prepositions, tense shifts, passive/reported structures, and lexical collocations alongside B2-level synthesis.","keyPoints":["Review your personal recurring error categories on Tuesday and Sunday before Checkpoint 4.","Check subject–verb agreement, article precision, and verb complementation in every draft.","Use balanced concession and hedging rather than sweeping generalisations."],"example":"Having reviewed fifteen weeks of drafts, I noticed that checking prepositions and articles after writing cuts my error rate in half.","items":[{"prompt":"Even ___ clear evidence from pilot studies, several districts hesitated to act.","options":["although","despite","whereas"],"answer":"despite","explanation":"Concession before a noun phrase requires \"despite\" (or \"in spite of\").","difficulty":2},{"prompt":"Not only ___ reliable data crucial, but transparent communication also matters.","options":["is","are","does"],"answer":"is","explanation":"Negative inversion after \"Not only\" uses singular \"is\" to match uncountable \"data\" (treated singular here).","difficulty":2},{"prompt":"By next month, our cohort ___ completed sixteen weeks of structured output.","options":["will be","will have","would have"],"answer":"will have","explanation":"\"By next month\" calls for future perfect (\"will have + past participle\").","difficulty":1}]}],"vocab":[{"term":"outweigh","pos":"verb","definition":"be more important than something else","example":"The benefits outweigh the costs in the long run.","collocations":["benefits outweigh the risks"],"wordFamily":["outweigh"],"translation":"superar en importancia","band":"B2","audioRef":"week-16/outweigh.mp3"},{"term":"inevitable","pos":"adjective","definition":"certain to happen and impossible to avoid","example":"Some disruption is inevitable during the works.","collocations":["a seemingly inevitable outcome"],"wordFamily":["inevitable"],"translation":"inevitable","band":"B2","audioRef":"week-16/inevitable.mp3"},{"term":"mitigate","pos":"verb","definition":"reduce the harmful effects of something","example":"Trees mitigate the heat in dense districts.","collocations":["mitigate the impact"],"wordFamily":["mitigate"],"translation":"mitigar","band":"B2","audioRef":"week-16/mitigate.mp3"},{"term":"prevalent","pos":"adjective","definition":"common in a particular place or time","example":"The practice is most prevalent in coastal towns.","collocations":["increasingly prevalent"],"wordFamily":["prevalent"],"translation":"predominante","band":"B2","audioRef":"week-16/prevalent.mp3"},{"term":"contend","pos":"verb","definition":"argue that something is true","example":"Critics contend that the figures are incomplete.","collocations":["critics contend that"],"wordFamily":["contend"],"translation":"sostener, afirmar","band":"B2","audioRef":"week-16/contend.mp3"},{"term":"detrimental","pos":"adjective","definition":"causing harm","example":"Long commutes are detrimental to health.","collocations":["detrimental to wellbeing"],"wordFamily":["detrimental"],"translation":"perjudicial","band":"B2","audioRef":"week-16/detrimental.mp3"},{"term":"feasible","pos":"adjective","definition":"possible and practical to do","example":"A partial ban is feasible within a year.","collocations":["technically feasible"],"wordFamily":["feasible"],"translation":"viable","band":"B2","audioRef":"week-16/feasible.mp3"},{"term":"consensus","pos":"noun","definition":"general agreement among a group","example":"There is broad consensus on the diagnosis, not the cure.","collocations":["reach a consensus"],"wordFamily":["consensus"],"translation":"consenso","band":"B2","audioRef":"week-16/consensus.mp3"},{"term":"nuance","pos":"noun","definition":"a small but important difference in meaning","example":"The argument ignores an important nuance.","collocations":["lose the nuance"],"wordFamily":["nuance"],"translation":"matiz","band":"B2","audioRef":"week-16/nuance.mp3"}],"inputs":[{"kind":"listening","lesson":3,"title":"Timed listening: three accents, one topic","source":"Studio original — mixed accents","accent":"British, Nigerian and Indian","seconds":225,"body":"SPEAKER 1: I grew up in a city where nobody cycled, and now there are more bikes than cars on my old street. SPEAKER 2: The infrastructure came first, which is the opposite of what most cities try. You cannot ask people to change and then blame them when there is nowhere safe to go. SPEAKER 3: What interests me is the budget. Cycle lanes are cheap compared with a motorway, yet they are treated as a luxury. If the same money had gone into roads, nobody would have questioned it. In the second half of the seminar, the three speakers compared how learners move from comfortable B1 fluency into dependable B2 control. All three agreed that passive recognition is never enough: speaking and writing under gentle time pressure reveals exactly which grammar slips still appear automatically—whether missing articles, tense jumps, or awkward prepositions. Once a learner spots those two or three personal habits in an error log and practises rewriting them aloud, overall clarity jumps far faster than memorising rare idioms.","questions":[{"prompt":"What does Speaker 2 say cities usually do wrong?","options":["Build infrastructure after asking people to change","Ignore their residents","Spend too much on bikes"],"answer":"Build infrastructure after asking people to change"},{"prompt":"What surprises Speaker 3?","options":["Cycle lanes are treated as a luxury","Roads are expensive","Nobody cycles"],"answer":"Cycle lanes are treated as a luxury"}],"speaker_accents":[{"speaker":"SPEAKER 1","accent":"en-GB","label":"British"},{"speaker":"SPEAKER 2","accent":"en-NG","label":"Nigerian"},{"speaker":"SPEAKER 3","accent":"en-IN","label":"Indian"}],"audioRef":"module-8/timed-listening-three-accents-one-topic.mp3","audioStatus":"actor_pending"},{"kind":"reading","lesson":4,"title":"Timed reading: the limits of a good statistic","source":"Studio original","body":"A single impressive number can end a discussion before it starts, which is precisely why it deserves suspicion. Take the claim that a policy 'created ten thousand jobs'. The figure may be accurate and still misleading: it says nothing about whether those jobs replaced others, how long they lasted, or who got them. Serious evaluation asks for the counterfactual — what would have happened anyway — and that is the question a headline rarely answers. Readers who learn to ask it become considerably harder to persuade with a number alone. Equally important at B2 level is knowing how to qualify a claim without sounding uncertain. Strong writers rarely announce that a policy \"solves everything\" or \"fails completely\"; instead, they explain the conditions under which evidence holds, acknowledge trade-offs openly, and cite realistic limits. Look closely at sample size, timeframe, and alternative explanations whenever a headline quotes a neat percentage. Developing that calm, analytical habit serves learners well whether they sit a formal B2 examination later or lead international discussions at work. Treating Checkpoint 4 as a snapshot of real progress—and naming one concrete next step if an area still needs polish—keeps long-term language growth grounded and motivating. Looking ahead after Week 16, maintaining B2 momentum requires far less daily effort than building it in the first place, provided output stays regular. Reading one longer feature article each weekend, listening to a varied mix of accents on your commute, and keeping a short personal notebook of awkward collocations ensures vocabulary keeps deepening naturally. Whenever a familiar tense or preposition slip reappears in writing, returning briefly to the Grammar Clinic keeps accuracy sharp. Above all, trust the cumulative effect of small, honest output: speaking and writing regularly turns hesitant knowledge into confident, lasting fluency.","questions":[{"prompt":"Why does the writer distrust impressive numbers?","options":["They can be accurate yet misleading","They are usually false","They are hard to read"],"answer":"They can be accurate yet misleading"},{"prompt":"What question does serious evaluation ask?","options":["What would have happened anyway?","Who paid for the study?","How was it reported?"],"answer":"What would have happened anyway?"}],"audioRef":"module-8/timed-reading-the-limits-of-a-good-statistic.mp3","audioStatus":"tts"}],"speaking":[{"kind":"monologue","title":"Final position statement: B2 synthesis (up to 3 min)","prompt":"Record a final B2 position statement (up to 3 minutes) evaluating a balanced policy question—weighing evidence, conceding a counter-argument, and defending your conclusion clearly.","seconds":180,"phrases":["On balance...","The evidence suggests...","A good illustration of this is..."],"linkers":["moreover","whereas","as a result","nevertheless"],"terms":["productivity","consolidation","consensus"]}],"writing":{"title":"Final essay: an argument with examples","prompt":"Write a 200–220-word argument essay: is remote work better for productivity and wellbeing? Present both sides, use evidence, and reach a clear conclusion.","format":"argument essay","wordMin":200,"wordMax":220,"outline":{"analyze":"Purpose: argue and conclude. Audience: an examiner. Register: formal.","plan":"Introduction with position → for → against → evaluation → conclusion.","draft":"Use one inversion, two hedges, two advanced linkers and one conditional.","improve":"Replace generic claims with qualified ones; add one concrete example.","review":"Check the essay answers the question, not merely the topic."}},"lessons":[{"dayOfWeek":"Mon","requirement":"optional","outputRequired":false,"minutes":15,"title":"Vocabulary: B2 consolidation and review","objective":"Learn 8–10 core B2 items for B2 consolidation and review, practising collocations and word families.","canDo":"I can deploy B2 consolidation and review collocations accurately in context.","skill":"vocabulary","input":"reading","outputTitle":"Use 4 B2 consolidation and review expressions","output":"Write or record 4 nuanced sentences using this week's B2 collocations.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Tue","requirement":"optional","outputRequired":false,"minutes":15,"title":"Grammar: Personal Error-Log Mixed Review","objective":"Target the recurring grammar and vocabulary mistakes from your personal 15-week error log.","canDo":"I can identify and self-correct my top recurring grammar and collocation patterns.","skill":"grammar","input":"reading","outputTitle":"Personal error-log repair","output":"Rewrite 3 sentences from your personal mistake log accurately.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Wed","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Listening: Timed listening: three accents, one topic","objective":"Follow a 3.5-minute multi-accent discussion on B2 consolidation and review, noting nuance and hedging.","canDo":"I can extract main arguments, concessions, and implied attitude from a 3.5-minute track.","skill":"listening","input":"listening","outputTitle":"Summarise the speaker's position","output":"Summarise the main viewpoint and one counter-argument from today's listening track.","targetSeconds":90,"wordRange":[70,110]},{"dayOfWeek":"Thu","requirement":"either_wed_thu","outputRequired":false,"minutes":15,"title":"Reading: Timed reading: the limits of a good statistic","objective":"Analyse a 250–350 word B2 article on B2 consolidation and review for evidence, tone, and structure.","canDo":"I can evaluate evidence and distinguish fact from opinion in a 250–350 word text.","skill":"reading","input":"reading","outputTitle":"Critical reaction to the article","output":"Write or record a short reaction explaining which point in the article is strongest and why.","targetSeconds":90,"wordRange":[80,120]},{"dayOfWeek":"Fri","requirement":"required","outputRequired":true,"minutes":15,"title":"Speaking (Required): Position Statement — B2 consolidation and review","objective":"Deliver a structured recorded position statement (up to 3 minutes) on B2 consolidation and review, plus Shadowing self-check.","canDo":"I can record a clear, hedged B2 position statement up to 3 minutes on B2 consolidation and review.","skill":"speaking","input":"listening","outputTitle":"Recorded position statement (up to 3 min)","output":"Record your final Week 16 position statement (up to 3 min) and prepare for Checkpoint 4.","targetSeconds":180,"wordRange":[100,160]},{"dayOfWeek":"Sat","requirement":"required","outputRequired":true,"minutes":30,"title":"Writing (Required): Final essay: an argument with examples","objective":"Plan, draft, and polish a 200–220 word B2 piece on B2 consolidation and review.","canDo":"I can produce a cohesive 200–220 word B2 text using mixed B2 structures and my personal error-log targets.","skill":"writing","input":"reading","outputTitle":"Final essay: an argument with examples","output":"Write a 200–220-word argument essay: is remote work better for productivity and wellbeing? Present both sides, use evidence, and reach a clear conclusion.","targetSeconds":180,"wordRange":[200,220]},{"dayOfWeek":"Sun","requirement":"optional","outputRequired":false,"minutes":15,"title":"Review: Week 16 cards & error log","objective":"Consolidate Week 16 vocabulary cards and self-correct recurring mistakes before the next week.","canDo":"I can recall this week's B2 vocabulary and rewrite my recurring mistakes cleanly.","skill":"review","input":"reading","outputTitle":"Error-log rewrite","output":"Review due SRS cards and complete at least two error-log rewrite checks.","targetSeconds":60,"wordRange":[50,90]}],"vocabPack":{"collocations":[{"phrase":"outweigh the drawbacks","band":"B2","useRole":"B","example":"For hybrid teams, lower commuting stress can outweigh the drawbacks of remote calls."},{"phrase":"mitigate the impact","band":"B2","useRole":"B","example":"Scheduled mentoring days help mitigate the impact of working from home."},{"phrase":"reach a broad consensus","band":"B2","useRole":"B","example":"After two rounds of consultation, the panel managed to reach a broad consensus."},{"phrase":"prove detrimental to","band":"B2","useRole":"B","example":"Constant late-evening messages can prove detrimental to staff retention."},{"phrase":"technically feasible","band":"B2","useRole":"B","example":"The pilot proved technically feasible, though funding remains uncertain."},{"phrase":"retain the nuance","band":"B2","useRole":"B","example":"Good summaries stay concise while managing to retain the nuance of the debate."}],"wordFamilies":[{"base":"mitigate","forms":["mitigation","mitigating"],"example":"Careful planning offers practical mitigation against burnout."},{"base":"prevail","forms":["prevalent","prevalence"],"example":"Flexible contracts have grown increasingly prevalent across service industries."}],"linkingExpressions":[{"expression":"on balance","functionLabel":"Synthesis","band":"B2","useRole":"B","example":"On balance, the evidence favours hybrid arrangements over rigid office mandates."},{"expression":"taking everything into account","functionLabel":"Conclusion","band":"B2","useRole":"B","example":"Taking everything into account, clear expectations matter more than physical desks."}]}}]} $json$::jsonb) as imported_weeks_13_14_15_16;

-- 4. Vocabulary windows and item counts ----------------------------------
insert into public.lesson_vocab (lesson_id, vocab_item_id, sort_order)
select l.id, it.id, 6 + k
from public.lessons l
join lateral (
  select vi.id, (row_number() over (order by vi.term) - 1) as idx, count(*) over () as total
  from public.vocab_items vi
  join public.vocab_decks vd on vd.id = vi.deck_id and vd.module_id = l.module_id
) it on true
cross join generate_series(1, 2) as k
where it.idx = ((l.module_lesson_number - 1 + 6 + k - 1) % it.total)
  and (
    l.module_lesson_number <> 1
    or not exists (
      select 1 from public.vocab_items vi2
      join public.vocab_decks vd2 on vd2.id = vi2.deck_id
      where vd2.module_id = l.module_id and vi2.gap_fill is not null
    )
  )
  and not (
    l.module_lesson_number = 2
    and exists (
      select 1 from public.lesson_blocks lb
      where lb.lesson_id = l.id and lb.block_kind = 'practice'
        and coalesce((lb.content->'mix'->>'grammar')::int, 0) >= 5
    )
  )
on conflict do nothing;

insert into public.practice_items (lesson_id, kind, sort_order, prompt, options, answer, explanation, grammar_point, difficulty)
select
  lv.lesson_id, 'multiple_choice', lv.sort_order + 2,
  format('Which expression matches this meaning? "%s"', vi.definition),
  jsonb_build_array(vi.term) || coalesce((
    select jsonb_agg(d.term order by d.term) from (
      select vi2.term from public.vocab_items vi2
      where vi2.deck_id = vi.deck_id and vi2.term <> vi.term
      order by md5(vi2.term || lv.sort_order::text), vi2.term limit 2) d), '[]'::jsonb),
  vi.term, format('Example: %s', vi.example), l.grammar_point, 1
from public.lesson_vocab lv
join public.vocab_items vi on vi.id = lv.vocab_item_id
join public.lessons l on l.id = lv.lesson_id
where lv.sort_order in (7, 8)
  and (
    l.module_lesson_number <> 1
    or vi.gap_fill is null
  )
  and not (
    l.module_lesson_number = 2
    and exists (
      select 1 from public.lesson_blocks lb
      where lb.lesson_id = l.id and lb.block_kind = 'practice'
        and coalesce((lb.content->'mix'->>'grammar')::int, 0) >= 5
    )
  )
  and not exists (select 1 from public.practice_items p where p.lesson_id = lv.lesson_id and p.sort_order = lv.sort_order + 2);

update public.lesson_blocks b
   set content = jsonb_set(jsonb_set(b.content, '{item_count}', '10'::jsonb), '{mix}', '{"grammar":2,"vocabulary":8}'::jsonb)
 where b.block_kind = 'practice'
   and coalesce((b.content->'mix'->>'grammar')::int, 0) < 5
   and not exists (
     select 1 from public.lessons l
     join public.vocab_decks vd on vd.module_id = l.module_id
     join public.vocab_items vi on vi.deck_id = vd.id
     where l.id = b.lesson_id and l.module_lesson_number = 1 and vi.gap_fill is not null
   );

-- 5. Summary --------------------------------------------------------------
select jsonb_build_object(
  'weeks', (select count(*) from public.modules),
  'sessions', (select count(*) from public.lessons),
  'lesson_blocks', (select count(*) from public.lesson_blocks),
  'practice_items', (select count(*) from public.practice_items),
  'vocab_items', (select count(*) from public.vocab_items),
  'content_inputs', (select count(*) from public.content_inputs),
  'speaking_tasks', (select count(*) from public.speaking_tasks),
  'writing_tasks', (select count(*) from public.writing_tasks),
  'checkpoints', (select count(*) from public.checkpoints),
  'badges', (select count(*) from public.badges)
) as seed_summary;
